import time
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be greater than 0")

        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._cache = OrderedDict()
        self._stats = {
            'hits': 0,
            'misses': 0,
            'evictions': 0,
            'expirations': 0
        }

    def _is_expired(self, time_stored):
        if self._ttl is None:
            return False
        return (self._clock() - time_stored) >= self._ttl

    def _cleanup_expired(self):
        """Removes all expired entries and updates expiration stats.
        Returns the number of unexpired entries remaining.
        """
        if self._ttl is None:
            return len(self._cache)

        now = self._clock()
        expired_keys = []
        for key, (value, time_stored) in self._cache.items():
            if (now - time_stored) >= self._ttl:
                expired_keys.append(key)
            # Cannot break early because OrderedDict is ordered by LRU (access), not insertion time.
            # An expired entry might appear later in the sequence if it was accessed recently.

        count_expired = 0
        for key in expired_keys:
            del self._cache[key]
            count_expired += 1

        self._stats['expirations'] += count_expired
        return len(self._cache)

    def get(self, key, default=None):
        if key in self._cache:
            value, time_stored = self._cache[key]
            if self._is_expired(time_stored):
                del self._cache[key]
                self._stats['expirations'] += 1
                self._stats['misses'] += 1
                return default
            else:
                self._cache.move_to_end(key)
                self._stats['hits'] += 1
                return value
        else:
            self._stats['misses'] += 1
            return default

    def put(self, key, value):
        # Check if key exists and is not expired
        if key in self._cache:
            value_old, time_stored_old = self._cache[key]
            if self._is_expired(time_stored_old):
                # Treat expired existing key as non-existent for insertion purposes
                del self._cache[key]
                self._stats['expirations'] += 1
                # Proceed to insert as new key
            else:
                # Update existing unexpired entry
                self._cache[key] = (value, self._clock())
                self._cache.move_to_end(key)
                return None

        # At this point, the key is either new or was just deleted due to expiration.
        # Ensure expired entries are cleaned up before capacity check.
        unexpired_count = self._cleanup_expired()

        evicted_key = None
        if unexpired_count >= self._capacity:
            # Evict Least Recently Used unexpired entry.
            # Since _cleanup_expired removed all expired ones, the front of OrderedDict is LRU unexpired.
            lru_key, _ = self._cache.popitem(last=False)
            evicted_key = lru_key
            self._stats['evictions'] += 1

        self._cache[key] = (value, self._clock())
        return evicted_key

    def resize(self, new_capacity: int):
        if new_capacity < 1:
            raise ValueError("capacity must be at least 1")

        self._capacity = new_capacity
        unexpired_count = self._cleanup_expired()

        while unexpired_count > self._capacity:
            lru_key, _ = self._cache.popitem(last=False)
            self._stats['evictions'] += 1
            unexpired_count -= 1

    def __contains__(self, key):
        if key in self._cache:
            _, time_stored = self._cache[key]
            if self._is_expired(time_stored):
                del self._cache[key]
                self._stats['expirations'] += 1
                return False
            return True
        return False

    def __len__(self):
        return self._cleanup_expired()

    def keys(self):
        # Cleanup ensures we don't expose expired keys
        self._cleanup_expired()
        # Return a list of keys to avoid issues with view modifications if any, 
        # but standard dict_keys view is fine. However, spec says "not in keys()" for expired.
        # Since we cleaned up, they aren't there.
        return self._cache.keys()

    def stats(self):
        return dict(self._stats)
