# ini.py

class ParseError(ValueError):
    """Exception raised when an INI configuration file cannot be parsed."""
    def __init__(self, message: str, lineno: int):
        super().__init__(f"line {lineno}: {message}")
        self.lineno = lineno


class Config:
    """Represents parsed INI configuration data."""

    def __init__(self, data: dict):
        """Initialize with nested dict structure {section: {key: value}}."""
        self._data = data

    def sections(self) -> list[str]:
        """Return list of section names in order of appearance."""
        return list(self._data.keys())

    def keys(self, section: str) -> list[str]:
        """Return list of keys in a section in order of appearance."""
        if section not in self._data:
            raise KeyError(section)
        return list(self._data[section].keys())

    def get(self, section: str, key: str, default: str | None = None) -> str | None:
        """Get value as string, or default if missing."""
        sec_data = self._data.get(section)
        if sec_data is None:
            return default
        return sec_data.get(key, default)

    def getint(self, section: str, key: str, default: int | None = None) -> int | None:
        """Get value as int. Raises ValueError if not an integer."""
        val_str = self.get(section, key)
        if val_str is None:
            return default
        try:
            # Strictly accept optional sign and decimal digits only
            # int() handles this correctly for standard strings.
            # int('0x10') raises ValueError in Python 3 unless base is specified.
            # int('4.0') raises ValueError.
            return int(val_str)
        except ValueError:
            raise ValueError(f"invalid literal for int(): {val_str!r}")

    def getbool(self, section: str, key: str, default: bool | None = None) -> bool | None:
        """Get value as bool. Raises ValueError if not a recognized boolean."""
        val_str = self.get(section, key)
        if val_str is None:
            return default

        lower_val = val_str.lower()
        if lower_val in ('true', 'yes', 'on', '1'):
            return True
        elif lower_val in ('false', 'no', 'off', '0'):
            return False
        else:
            raise ValueError(f"invalid literal for bool(): {val_str!r}")

    def getlist(self, section: str, key: str, default: list[str] | None = None) -> list[str] | None:
        """Get value as list of strings split by comma, stripped, non-empty."""
        val_str = self.get(section, key)
        if val_str is None:
            return default

        if val_str == '':
            return []

        items = val_str.split(',')
        stripped_items = [item.strip() for item in items]
        non_empty = [item for item in stripped_items if item]
        return non_empty


def parse(text: str) -> Config:
    """
    Parse INI-style configuration text.

    Args:
        text: The string content of the INI file.

    Returns:
        A Config object containing the parsed data.

    Raises:
        ParseError: If the text is malformed.
    """
    # Use dict which preserves insertion order in Python 3.7+
    config_data = {}
    current_section = None
    prev_key = None

    lines = text.splitlines()

    for lineno, line in enumerate(lines, 1):
        # Check for blank line (empty or whitespace only)
        if not line.strip():
            prev_key = None
            continue

        stripped_line = line.strip()

        # Check for comment line
        if stripped_line.startswith(';') or stripped_line.startswith('#'):
            prev_key = None
            continue

        # Check for indented line (continuation or error)
        # An indented line is defined as starting with space or tab
        if line[0] in ' \t':
            if prev_key is None:
                raise ParseError("invalid indented line: no preceding key or section to continue", lineno)

            # It is a continuation line
            # Append stripped text to the value of prev_key with \n
            current_val = config_data[current_section][prev_key]
            config_data[current_section][prev_key] = current_val + '\n' + stripped_line

            # prev_key stays the same
            continue

        # Unindented, non-blank, non-comment line

        # Check for section header
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            section_name = stripped_line[1:-1].strip()
            if not section_name:
                raise ParseError("empty section name", lineno)
            if section_name in config_data:
                raise ParseError(f"duplicate section '{section_name}'", lineno)

            config_data[section_name] = {}
            current_section = section_name
            prev_key = None
            continue

        # Check for key-value pair
        if '=' in stripped_line:
            key, value = stripped_line.split('=', 1)
            key = key.strip()
            value = value.strip()

            if not key:
                raise ParseError("empty key", lineno)

            if current_section is None:
                raise ParseError("key-value pair before section header", lineno)

            if key in config_data[current_section]:
                raise ParseError(f"duplicate key '{key}' in section '{current_section}'", lineno)

            config_data[current_section][key] = value
            prev_key = key
            continue

        # If we reach here, the line is unindented, non-blank, non-comment,
        # not a valid section header, and doesn't contain '='. It's invalid.
        raise ParseError(f"invalid line: {stripped_line}", lineno)

    return Config(config_data)
