import re
from typing import Tuple, Union

# SemVer 2.0.0 regex
# https://semver.org/#is-there-a-suggested-regular-expression-regex-to-check-a-semver-string
_SEMVER_REGEX = re.compile(
    r"^"
    r"(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)"
    r"(?:-(?P<prerelease>(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?"
    r"(?:\+(?P<build>[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?"
    r"$"
)


class Version:
    def __init__(self, major: int, minor: int, patch: int, prerelease: Tuple[str, ...] = (), build: Tuple[str, ...] = ()):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    @classmethod
    def parse(cls, text: str) -> "Version":
        if not isinstance(text, str):
            raise ValueError("Version text must be a string")
        match = _SEMVER_REGEX.match(text)
        if not match:
            raise ValueError(f"Invalid SemVer string: {text!r}")

        major = int(match.group('major'))
        minor = int(match.group('minor'))
        patch = int(match.group('patch'))

        prerelease_str = match.group('prerelease')
        build_str = match.group('build')

        prerelease = tuple(prerelease_str.split('.')) if prerelease_str else ()
        build = tuple(build_str.split('.')) if build_str else ()

        return cls(major, minor, patch, prerelease, build)

    def __str__(self) -> str:
        parts = [f"{self.major}.{self.minor}.{self.patch}"]
        if self.prerelease:
            parts.append('-')
            parts.append('.'.join(self.prerelease))
        if self.build:
            parts.append('+')
            parts.append('.'.join(self.build))
        return ''.join(parts)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        # Build metadata is ignored for equality
        return (
            self.major == other.major
            and self.minor == other.minor
            and self.patch == other.patch
            and self.prerelease == other.prerelease
        )

    def __ne__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return not self.__eq__(other)

    def _compare_prerelease(self, other: "Version") -> int:
        # If both have no prerelease, they are equal in this aspect
        if not self.prerelease and not other.prerelease:
            return 0
        # If one has prerelease and other doesn't, the one with prerelease is lower
        if self.prerelease and not other.prerelease:
            return -1
        if not self.prerelease and other.prerelease:
            return 1

        # Both have prerelease, compare left to right
        for a, b in zip(self.prerelease, other.prerelease):
            if a == b:
                continue

            # Determine if identifiers are numeric
            a_is_num = a.isdigit()
            b_is_num = b.isdigit()

            if a_is_num and b_is_num:
                # Compare numerically
                int_a = int(a)
                int_b = int(b)
                if int_a < int_b:
                    return -1
                elif int_a > int_b:
                    return 1
            elif a_is_num and not b_is_num:
                # Numeric identifier is always lower than alphanumeric
                return -1
            elif not a_is_num and b_is_num:
                return 1
            else:
                # Both are alphanumeric (or mixed but not purely numeric), compare lexically
                if a < b:
                    return -1
                elif a > b:
                    return 1

        # If all compared identifiers are equal, the one with fewer identifiers is lower
        if len(self.prerelease) < len(other.prerelease):
            return -1
        elif len(self.prerelease) > len(other.prerelease):
            return 1

        return 0

    def _compare(self, other: "Version") -> int:
        # Compare major, minor, patch numerically
        if self.major != other.major:
            return -1 if self.major < other.major else 1
        if self.minor != other.minor:
            return -1 if self.minor < other.minor else 1
        if self.patch != other.patch:
            return -1 if self.patch < other.patch else 1

        # If core versions are equal, compare prerelease
        return self._compare_prerelease(other)

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) < 0

    def __le__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) <= 0

    def __gt__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) > 0

    def __ge__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) >= 0

    def __hash__(self) -> int:
        # Build metadata is ignored for hashing
        return hash((self.major, self.minor, self.patch, self.prerelease))
    def bump(self, kind: str) -> "Version":
        if kind == "major":
            return Version(self.major + 1, 0, 0)
        elif kind == "minor":
            return Version(self.major, self.minor + 1, 0)
        elif kind == "patch":
            return Version(self.major, self.minor, self.patch + 1)
        else:
            raise ValueError(f"Invalid bump kind: {kind!r}. Must be 'major', 'minor', or 'patch'")# semver.py additions

def _parse_spec_version(text: str) -> Version:
    """
    Parses a partial version string for use in comparators.
    Supports '1', '1.2', and '1.2.3'. 
    Does not support pre-release or build metadata in spec versions per prompt instructions.
    """
    if not text:
        raise ValueError("Empty version in spec")

    parts = text.split('.')
    if len(parts) > 3:
        raise ValueError(f"Invalid version in spec: {text}")

    def parse_num(s):
        if not s.isdigit():
            # Check for leading zeros in non-zero numbers? SemVer spec says no leading zeros for 0.
            # But for range specs, usually it's more lenient or follows strict SemVer.
            # Prompt says "A partial version cannot have a pre-release or build part."
            # It doesn't explicitly forbid leading zeros in range specs, but usually strict.
            # However, '0' is valid. '01' is likely invalid.
            if len(s) > 1 and s[0] == '0':
                 raise ValueError(f"Invalid number in spec version: {s}")
            if not s.isdigit():
                 raise ValueError(f"Invalid number in spec version: {s}")
        return int(s)

