from fractions import Fraction
from typing import List, Union

class CalcError(Exception):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.position = position

def evaluate(expr: str) -> Fraction:
    """
    Evaluates an arithmetic expression string exactly using Fractions.

    Args:
        expr: The arithmetic expression string.

    Returns:
        The result as a fractions.Fraction.

    Raises:
        CalcError: If there is a syntax error or division by zero.
    """
    parser = _Parser(expr)
    result = parser.parse_expr()

    # Check if there are any remaining characters (excluding whitespace)
    parser._skip_whitespace()
    if parser.pos < len(parser.expr):
        raise CalcError(f"Unexpected character '{parser.expr[parser.pos]}'", parser.pos)

    return result

class _Parser:
    def __init__(self, expr: str):
        self.expr = expr
        self.pos = 0

    def _skip_whitespace(self):
        while self.pos < len(self.expr) and self.expr[self.pos] in ' \t':
            self.pos += 1

    def _peek(self) -> str:
        if self.pos < len(self.expr):
            return self.expr[self.pos]
        return ''

    def _consume(self, expected: str) -> str:
        self._skip_whitespace()
        if self.pos < len(self.expr) and self.expr[self.pos] == expected:
            val = self.expr[self.pos]
            self.pos += 1
            return val
        raise CalcError(f"Expected '{expected}'", self.pos)

    def _get_next_token(self):
        """
        Returns (token_type, token_value, position)
        Types: 'number', 'op', 'lparen', 'rparen', 'error'
        """
        self._skip_whitespace()
        if self.pos >= len(self.expr):
            return ('eof', None, self.pos)

        ch = self.expr[self.pos]

        if ch.isdigit():
            # Parse number
            start = self.pos
            # Integer part
            while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
                self.pos += 1

            # Fractional part?
            if self.pos < len(self.expr) and self.expr[self.pos] == '.':
                # Check if next is digit
                if self.pos + 1 < len(self.expr) and self.expr[self.pos+1].isdigit():
                    self.pos += 1 # consume dot
                    while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
                        self.pos += 1
                else:
                    # Dot is not part of this number. 
                    # It might be an error later, or start of something else? 
                    # Spec: .5 is not a number. So dot cannot start a number.
                    # So if we see . not followed by digit, we don't consume it.
                    # The number ends at the digit.
                    pass

            num_str = self.expr[start:self.pos]
            return ('number', Fraction(num_str), start)

        elif ch in '+-*/':
            self.pos += 1
            return ('op', ch, self.pos - 1)

        elif ch == '(':
            self.pos += 1
            return ('lparen', '(', self.pos - 1)

        elif ch == ')':
            self.pos += 1
            return ('rparen', ')', self.pos - 1)

        else:
            # Invalid character
            return ('error', ch, self.pos)

    def _is_token(self, type_val: Union[str, List[str]], value: Union[str, None] = None) -> bool:
        """
        Peeks at the next token. If it matches, returns True, else False.
        Does NOT consume.
        """
        self._skip_whitespace()
        if self.pos >= len(self.expr):
            return False

        ch = self.expr[self.pos]

        types = [type_val] if isinstance(type_val, str) else type_val

        # Number check
        if 'number' in types:
            if ch.isdigit():
                return True

        # Operator check
        if 'op' in types:
            if ch in '+-*/':
                if value is None or ch == value:
                    return True

        # Parentheses check
        if 'lparen' in types:
            if ch == '(':
                return True

        if 'rparen' in types:
            if ch == ')':
                return True

        return False

    def _peek_token(self):
        """
        Peeks at the next token info without consuming state changes for position.
        Returns (type, value, position) or None if EOF.
        """
        old_pos = self.pos
        self._skip_whitespace()
        if self.pos >= len(self.expr):
            self.pos = old_pos
            return ('eof', None, self.pos)

        ch = self.expr[self.pos]
        res = None

        if ch.isdigit():
            res = ('number', None, self.pos)
        elif ch in '+-*/':
            res = ('op', ch, self.pos)
        elif ch == '(':
            res = ('lparen', '(', self.pos)
        elif ch == ')':
            res = ('rparen', ')', self.pos)
        else:
            res = ('error', ch, self.pos)

        self.pos = old_pos
        return res

    def parse_expr(self) -> Fraction:
        """
        Expr -> Term {('+' | '-') Term}
        """
        result = self.parse_term()

        while True:
            tok = self._peek_token()
            if tok and tok[0] == 'op' and tok[1] in ('+', '-'):
                op = tok[1]
                op_pos = tok[2]
                self._consume(op) # Consumes the operator

                right = self.parse_term()

                if op == '+':
                    result = result + right
                else:
                    result = result - right
            else:
                break

        return result

    def parse_term(self) -> Fraction:
        """
        Term -> Factor {('*' | '/') Factor}
        """
        result = self.parse_factor()

        while True:
            tok = self._peek_token()
            if tok and tok[0] == 'op' and tok[1] in ('*', '/'):
                op = tok[1]
                op_pos = tok[2]
                self._consume(op) # Consumes the operator

                right = self.parse_factor()

                if op == '*':
                    result = result * right
                else:
                    if right == 0:
                        raise CalcError("Division by zero", op_pos)
                    result = result / right
            else:
                break

        return result

    def parse_factor(self) -> Fraction:
        """
        Factor -> ['-'] Primary
        """
        tok = self._peek_token()
        if tok and tok[0] == 'op' and tok[1] == '-':
            # Unary minus
            self._consume('-') # Consume minus
            operand = self.parse_factor() # Recursively handle multiple minuses
            return -operand
        else:
            return self.parse_primary()

    def parse_primary(self) -> Fraction:
        """
        Primary -> Number | '(' Expr ')'
        """
        tok = self._peek_token()

        if tok is None or tok[0] == 'eof':
            raise CalcError("Unexpected end of expression", self.pos)

        if tok[0] == 'number':
            # Consume number
            val, pos = self._consume('number')
            return val

        if tok[0] == 'lparen':
            self._consume('(')
            expr_val = self.parse_expr()
            self._consume(')')
            return expr_val

        # If it's not a number and not a left paren, it's an error
        raise CalcError(f"Unexpected token '{tok[1]}'", tok[2])

    def _consume(self, expected_type: str, expected_value: Union[str, None] = None):
        tok = self._peek_token()
        if tok is None or tok[0] == 'eof':
            raise CalcError("Unexpected end of expression", self.pos)

        t, v, p = tok

        if t != expected_type:
            raise CalcError(f"Expected {expected_type}, got {t}", p)

        if expected_value is not None and v != expected_value:
            raise CalcError(f"Expected '{expected_value}', got '{v}'", p)

        # Now actually consume it by calling _get_next_token
        if t == 'number':
            # _get_next_token handles parsing and advancing pos
            # We must ensure we don't skip whitespace twice incorrectly or lose position
            # _get_next_token starts with _skip_whitespace, so it's safe.
            type, val, pos = self._get_next_token()
            if type == 'number':
                return (val, pos)
            raise CalcError("Internal error: number consumption failed", self.pos)

        # For operators and parens, _get_next_token is safe
        type, val, pos = self._get_next_token()
        return (val, pos)
