    """Tokenizes an arithmetic expression string."""
    def __init__(self, expr: str):
        self.expr = expr
        self.pos = 0
        self.tokens: List[Token] = []
        self._tokenize()

    def _tokenize(self):
        """Tokenize the entire expression upfront."""
        while self.pos < len(self.expr):
            ch = self.expr[self.pos]

            # Skip whitespace (spaces and tabs)
            if ch in ' \t':
                self.pos += 1
                continue

            # Numbers: digits optionally followed by . and more digits
            if ch.isdigit():
                start = self.pos
                while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
                    self.pos += 1
                # Check for fractional part: '.' followed by at least one digit
                if self.pos < len(self.expr) and self.expr[self.pos] == '.':
                    if self.pos + 1 < len(self.expr) and self.expr[self.pos + 1].isdigit():
                        self.pos += 1  # consume '.'
                        while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
                            self.pos += 1
                    # If '.' is not followed by a digit, we don't consume it.
                    # The '.' will be handled as an invalid character next.
                num_str = self.expr[start:self.pos]
                try:
                    val = Fraction(num_str)
                except (ValueError, ZeroDivisionError):
                    raise CalcError(f"Invalid number '{num_str}'", start)
                self.tokens.append(Token(TOKEN_NUMBER, val, start))
                continue

            # Operators
            if ch in '+-*/':
                self.tokens.append(Token(TOKEN_OP, ch, self.pos))
                self.pos += 1
                continue

            # Parentheses
            if ch == '(':
                self.tokens.append(Token(TOKEN_LPAREN, '(', self.pos))
                self.pos += 1
                continue

            if ch == ')':
                self.tokens.append(Token(TOKEN_RPAREN, ')', self.pos))
                self.pos += 1
                continue

            # Any other character is an error at its position
            raise CalcError(f"Invalid character '{ch}'", self.pos)

        self.tokens.append(Token(TOKEN_EOF, None, len(self.expr)))


# --- Parser (builds AST, validates syntax) ---
class Parser:
    """Recursive descent parser that builds an AST from tokens."""
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.index = 0

    def _peek(self) -> Token:
        return self.tokens[self.index]

    def _advance(self) -> Token:
        tok = self.tokens[self.index]
        self.index += 1
        return tok

    def parse(self):
        """Parse the full expression and ensure all input is consumed."""
        node = self._parse_expr()
        tok = self._peek()
        if tok.type != TOKEN_EOF:
            raise CalcError("Unexpected token", tok.pos)
        return node

    def _parse_expr(self):
        """Expr -> Term {('+' | '-') Term}"""
        left = self._parse_term()
        while True:
            tok = self._peek()
            if tok.type == TOKEN_OP and tok.value in ('+', '-'):
                op_tok = self._advance()
                right = self._parse_term()
                left = BinaryOpNode(op_tok.value, left, right, op_tok.pos)
            else:
                break
        return left

    def _parse_term(self):
        """Term -> Factor {('*' | '/') Factor}"""
        left = self._parse_factor()
        while True:
            tok = self._peek()
            if tok.type == TOKEN_OP and tok.value in ('*', '/'):
                op_tok = self._advance()
                right = self._parse_factor()
                left = BinaryOpNode(op_tok.value, left, right, op_tok.pos)
            else:
                break
        return left

    def _parse_factor(self):
        """Factor -> '-' Factor | Primary"""
        tok = self._peek()
        if tok.type == TOKEN_OP and tok.value == '-':
            op_tok = self._advance()
            operand = self._parse_factor()
            return UnaryMinusNode(operand, op_tok.pos)
        return self._parse_primary()

    def _parse_primary(self):
        """Primary -> Number | '(' Expr ')'"""
        tok = self._peek()
        if tok.type == TOKEN_NUMBER:
            self._advance()
            return NumberNode(tok.value, tok.pos)
        if tok.type == TOKEN_LPAREN:
            self._advance()
            inner = self._parse_expr()
            tok = self._peek()
            if tok.type != TOKEN_RPAREN:
                raise CalcError("Expected ')'", tok.pos)
            self._advance()
            return inner
        raise CalcError("Unexpected token", tok.pos)


# --- Evaluator (walks AST, computes result, detects division by zero) ---
def _evaluate_node(node) -> Fraction:
    """Recursively evaluate an AST node. Raises CalcError on division by zero."""
    if isinstance(node, NumberNode):
        return node.value
    if isinstance(node, UnaryMinusNode):
        return -_evaluate_node(node.operand)
    if isinstance(node, BinaryOpNode):
        # Evaluate left-to-right: left first, then right
        left_val = _evaluate_node(node.left)
        right_val = _evaluate_node(node.right)
        if node.op == '+':
            return left_val + right_val
        if node.op == '-':
            return left_val - right_val
        if node.op == '*':
            return left_val * right_val
        if node.op == '/':
            if right_val == 0:
                raise CalcError("Division by zero", node.op_pos)
            return left_val / right_val
    raise CalcError("Unknown node type", 0)


# --- Public API ---
def evaluate(expr: str) -> Fraction:
    """
    Evaluates an arithmetic expression string exactly using Fractions.

    Grammar:
        Expr   -> Term {('+' | '-') Term}
        Term   -> Factor {('*' | '/') Factor}
        Factor -> '-' Factor | Primary
        Primary -> Number | '(' Expr ')'

    Numbers are decimal: digits, optionally followed by '.' and digits.
    All arithmetic is exact using fractions.Fraction.
    Spaces and tabs are ignored.

    Args:
        expr: The arithmetic expression string.

    Returns:
        The result as a fractions.Fraction.

    Raises:
        CalcError: If there is a syntax error or division by zero.
    """
    # Step 1: Tokenize (may raise CalcError for invalid characters)
    tokenizer = Tokenizer(expr)

    # Step 2: Parse into AST (validates syntax; raises CalcError for syntax errors)
    parser = Parser(tokenizer.tokens)
    ast = parser.parse()

    # Step 3: Evaluate AST (raises CalcError for division by zero)
    return _evaluate_node(ast)
