from fractions import Fraction
from typing import List, Union, Dict, Optional, Any
import math

class CalcError(Exception):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.position = position

# --- AST Nodes ---
# Using simple dataclasses or namedtuples to store position and structure
class Node:
    __slots__ = ('pos',)

class NumNode(Node):
    __slots__ = ('value',)
    def __init__(self, value: Fraction, pos: int):
        self.value = value
        self.pos = pos

class VarNode(Node):
    __slots__ = ('name',)
    def __init__(self, name: str, pos: int):
        self.name = name
        self.pos = pos

class FuncCallNode(Node):
    __slots__ = ('name', 'args')
    def __init__(self, name: str, args: List[Node], pos: int):
        self.name = name
        self.args = args
        self.pos = pos

class BinOpNode(Node):
    __slots__ = ('op', 'left', 'right')
    def __init__(self, op: str, left: Node, right: Node, pos: int):
        self.op = op
        self.left = left
        self.right = right
        self.pos = pos

class PowerNode(Node):
    __slots__ = ('base', 'exp')
    def __init__(self, base: Node, exp: Node, pos: int):
        self.base = base
        self.exp = exp
        self.pos = pos

class UnaryMinusNode(Node):
    __slots__ = ('operand',)
    def __init__(self, operand: Node, pos: int):
        self.operand = operand
        self.pos = pos

# --- Tokenizer ---
# Token types: 'number', 'op', 'lparen', 'rparen', 'name', 'eof'
# op values: '+', '-', '*', '/', '**', ',' (comma treated as op for simplicity in lexer? No, distinct type better)
# Let's use types: 'NUMBER', 'OP', 'LPAREN', 'RPAREN', 'NAME', 'COMMA', 'EOF'

class Token:
    def __init__(self, type: str, value: Any, pos: int):
        self.type = type
        self.value = value
        self.pos = pos

class Lexer:
    def __init__(self, expr: str):
        self.expr = expr
        self.pos = 0

    def _skip_whitespace(self):
        while self.pos < len(self.expr) and self.expr[self.pos] in ' \t':
            self.pos += 1

    def get_next_token(self) -> Token:
        self._skip_whitespace()
        if self.pos >= len(self.expr):
            return Token('EOF', None, self.pos)

        ch = self.expr[self.pos]

        if ch.isdigit():
            start = self.pos
            while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
                self.pos += 1

            if self.pos < len(self.expr) and self.expr[self.pos] == '.':
                if self.pos + 1 < len(self.expr) and self.expr[self.pos+1].isdigit():
                    self.pos += 1
                    while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
                        self.pos += 1

            num_str = self.expr[start:self.pos]
            try:
                val = Fraction(num_str)
            except ValueError:
                # Should not happen if regex/loop correct, but defensive
                raise CalcError(f"Invalid number '{num_str}'", start)
            return Token('NUMBER', val, start)

        elif ch.isalpha() or ch == '_':
            start = self.pos
            while self.pos < len(self.expr) and (self.expr[self.pos].isalnum() or self.expr[self.pos] == '_'):
                self.pos += 1
            return Token('NAME', self.expr[start:self.pos], start)

        elif ch == '+':
            self.pos += 1
            return Token('OP', '+', self.pos - 1)

        elif ch == '-':
            self.pos += 1
            return Token('OP', '-', self.pos - 1)

        elif ch == '*':
