            if self.pos + 1 < len(self.expr) and self.expr[self.pos+1] == '*':
                self.pos += 2
                return Token('OP', '**', self.pos - 2)
            else:
                self.pos += 1
                return Token('OP', '*', self.pos - 1)

        elif ch == '/':
            self.pos += 1
            return Token('OP', '/', self.pos - 1)

        elif ch == '(':
            self.pos += 1
            return Token('LPAREN', '(', self.pos - 1)

        elif ch == ')':
