                return Token('OP', '**', self.pos - 2)
            else:
                self.pos += 1
                return Token('OP', '*', self.pos - 1)

        elif ch == '/':
            self.pos += 1
            return Token('OP', '/', self.pos - 1)

        elif ch == '(':
            self.pos += 1
            return Token('LPAREN', '(', self.pos - 1)

        elif ch == ')':
            self.pos += 1
            return Token('RPAREN', ')', self.pos - 1)

        elif ch == ',':
            self.pos += 1
            return Token('COMMA', ',', self.pos - 1)

