            pos = self.current_token.pos
            self._eat('OP')
            operand = self.parse_factor() # Recursively handle multiple minuses or power?
            # If -2**2: 
            # parse_factor sees -, eats it.
            # calls parse_factor.
            # Inner parse_factor: calls parse_power?
            # Let's refactor to match: Unary -> Power -> Primary
            return UnaryMinusNode(operand, pos)
        else:
            return self.parse_power()

    def parse_power(self) -> Node:
        # Power := Primary ( '**' Unary )?
        base = self.parse_primary()
        if self.current_token.type == 'OP' and self.current_token.value == '**':
            pos = self.current_token.pos
            self._eat('OP')
            # Right operand is Unary. Unary includes minus.
            # parse_factor handles unary minus.
            exponent = self.parse_factor()
            return PowerNode(base, exponent, pos)
        return base

    def parse_primary(self) -> Node:
        tok = self.current_token

        if tok.type == 'NUMBER':
            self._eat('NUMBER')
            return NumNode(tok.value, tok.pos)

        if tok.type == 'LPAREN':
            self._eat('LPAREN')
            expr = self.parse_expr()
            self._eat('RPAREN')
            return expr

        if tok.type == 'NAME':
            name = tok.value
            name_pos = tok.pos
            self._eat('NAME')

            # Check for function call
            if self.current_token.type == 'LPAREN':
                self._eat('LPAREN')
                args = []

                # Handle empty args
                if self.current_token.type == 'RPAREN':
                    self._eat('RPAREN')
                    return FuncCallNode(name, args, name_pos)

                # Parse args
                while True:
                    arg = self.parse_expr()
                    args.append(arg)

                    if self.current_token.type == 'COMMA':
                        self._eat('COMMA')
                    elif self.current_token.type == 'RPAREN':
                        self._eat('RPAREN')
                        break
                    else:
                        raise CalcError("Expected ',' or ')'", self.current_token.pos)

                return FuncCallNode(name, args, name_pos)
            else:
                return VarNode(name, name_pos)

        raise CalcError(f"Unexpected token '{tok.value}'", tok.pos)

# --- Evaluator ---
class Evaluator:
    def __init__(self, variables: Optional[Dict[str, Union[int, Fraction]]]):
        self.variables = variables if variables is not None else {}
        self.builtins = {
            'abs': self._builtin_abs,
            'min': self._builtin_min,
            'max': self._builtin_max,
        }

    def evaluate(self, node: Node) -> Fraction:
        if isinstance(node, NumNode):
            return node.value

        if isinstance(node, VarNode):
            if node.name not in self.variables:
                raise CalcError(f"Unknown variable '{node.name}'", node.pos)
            return Fraction(self.variables[node.name])

        if isinstance(node, UnaryMinusNode):
            val = self.evaluate(node.operand)
            return -val

        if isinstance(node, BinOpNode):
            left = self.evaluate(node.left)
            right = self.evaluate(node.right)
            if node.op == '+':
                return left + right
            elif node.op == '-':
                return left - right
            elif node.op == '*':
                return left * right
            elif node.op == '/':
                if right == 0:
                    raise CalcError("Division by zero", node.pos)
                return left / right

        if isinstance(node, PowerNode):
            base = self.evaluate(node.base)
            exp = self.evaluate(node.exp)

            # Check exponent is integer
            if exp.denominator != 1:
                raise CalcError(f"Exponent must be integer", node.pos)

            # Check 0 ** negative
            if base == 0 and exp < 0:
                raise CalcError("Division by zero", node.pos)

            try:
                # Fraction supports integer powers
                return base ** exp
            except ZeroDivisionError:
                # Should be caught above, but safety
                raise CalcError("Division by zero", node.pos)

        if isinstance(node, FuncCallNode):
            # Check function name and arg count BEFORE evaluating args
            if node.name not in self.builtins:
                raise CalcError(f"Unknown function '{node.name}'", node.pos)

            func = self.builtins[node.name]
            # Validate args
            func(node.name, node.args, node.pos, self, validate_only=True)

            # Evaluate args left to right
            evaluated_args = [self.evaluate(arg) for arg in node.args]

            return func(node.name, evaluated_args, node.pos, self)

        raise CalcError("Invalid AST node", 0)

    def _builtin_abs(self, name: str, args: List[Union[Fraction, Node]], pos: int, evaluator: 'Evaluator', validate_only: bool = False) -> Fraction:
        if len(args) != 1:
            raise CalcError(f"Function '{name}' takes 1 argument", pos)
        if validate_only:
            return None
        return abs(args[0])

    def _builtin_min(self, name: str, args: List[Union[Fraction, Node]], pos: int, evaluator: 'Evaluator', validate_only: bool = False) -> Fraction:
        if len(args) < 1:
            raise CalcError(f"Function '{name}' takes at least 1 argument", pos)
        if validate_only:
            return None
        return min(args)

    def _builtin_max(self, name: str, args: List[Union[Fraction, Node]], pos: int, evaluator: 'Evaluator', validate_only: bool = False) -> Fraction:
        if len(args) < 1:
            raise CalcError(f"Function '{name}' takes at least 1 argument", pos)
        if validate_only:
            return None
        return max(args)

# --- Public Interface ---
def evaluate(expr: str, variables: Optional[Dict[str, Union[int, Fraction]]] = None) -> Fraction:
    parser = Parser(expr)
    ast = parser.parse() # Raises CalcError for syntax errors
    evaluator = Evaluator(variables)
    return evaluator.evaluate(ast) # Raises CalcError for eval errors
