def justify(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("Width must be at least 1")

    words = text.split()
    if not words:
        return []

    all_lines = []
    current_words = []
    current_len = 0

    for word in words:
        if not current_words:
            if len(word) > width:
                all_lines.append([word])
                continue
            current_words.append(word)
            current_len = len(word)
        else:
            # Check if adding the word fits in the current line with single spaces
            # current_len is sum of lengths of words in current_words
            # To add word, we need current_len + 1 (space) + len(word) <= width
            if current_len + 1 + len(word) <= width:
                current_words.append(word)
                current_len += 1 + len(word)
            else:
                # Word doesn't fit, finalize current line
                all_lines.append(current_words)
                current_words = []
                current_len = 0

                # Now process the current word again in the context of an empty line
                if len(word) > width:
                    all_lines.append([word])
                else:
                    current_words.append(word)
                    current_len = len(word)

    if current_words:
        all_lines.append(current_words)

    def format_line(line_words: list[str], is_last: bool) -> str:
        if is_last:
            return " ".join(line_words)

        if len(line_words) == 1:
            if len(line_words[0]) > width:
                return line_words[0]
            return line_words[0].ljust(width)

        # Multiple words, distribute spaces
        total_content_len = sum(len(w) for w in line_words)
        total_spaces_needed = width - total_content_len
        num_gaps = len(line_words) - 1

        base_spaces, remainder = divmod(total_spaces_needed, num_gaps)

        result = []
        for i, word in enumerate(line_words):
            result.append(word)
            if i < num_gaps:
                spaces = base_spaces + (1 if i < remainder else 0)
                result.append(" " * spaces)

        return "".join(result)

    return [format_line(line, i == len(all_lines) - 1) for i, line in enumerate(all_lines)]

