            else:
                start = i
                while i < n and path[i] not in (".", "[", "]", '"'):
                    i += 1
                name = path[start:i]
                if not name:
                    _error("empty name after dot")
                segments.append(name)
                if i < n and path[i] == ".":
                    i += 1
                    state = "after_dot"
                elif i < n and path[i] == "[":
                    state = "segment"
                elif i < n:
                    _error(
                        f"unexpected {path[i]!r} after name"
                    )

    # trailing dot leaves state == 'after_dot'
    if state == "after_dot":
        _error("trailing dot")

    return segments


# Sentinel to distinguish "no default provided" from "default is None"
_MISSING = object()


def _get_wildcards(obj, segments: list, path: str) -> list:
    """Recursively resolve a path with wildcards, returning a list of values."""
    if not segments:
        return [obj]

    seg = segments[0]
    rest = segments[1:]

    if seg is WILDCARD:
        results = []
        if isinstance(obj, (list, tuple)):
            for item in obj:
                results.extend(_get_wildcards(item, rest, path))
        elif isinstance(obj, collections.abc.Mapping):
            # In Python 3.7+, dict preserves insertion order. 
            # The spec says "insertion order".
            for key in obj:
                val = obj[key]
                results.extend(_get_wildcards(val, rest, path))
        else:
            # Wildcard on other types matches nothing
            return []
        return results

    elif isinstance(seg, str):
        if isinstance(obj, collections.abc.Mapping):
            if seg in obj:
                return _get_wildcards(obj[seg], rest, path)
        return []

    elif isinstance(seg, int):
        if isinstance(obj, (list, tuple)):
            try:
                val = obj[seg]
                return _get_wildcards(val, rest, path)
            except IndexError:
                return []
        return []

    return []


def get(obj, path: str, default=_MISSING):
    """Return the value at *path* in *obj*.

    If the path contains at least one wildcard ``[*]``:
    *   Returns a list of all values reached by the path.
    *   Missing branches are skipped.
    *   ``default`` is ignored.
    *   Returns ``[]`` if no values match.

    If the path contains no wildcards:
    *   Returns the single value at the path.
    *   Raises ``PathError`` if the path is invalid or missing (unless *default* is provided).
    """
    segments = parse(path)

    # Check for wildcards
    has_wildcard = any(seg is WILDCARD for seg in segments)

    if has_wildcard:
        return _get_wildcards(obj, segments, path)

    # Original logic for non-wildcard paths
    current = obj

    for segment in segments:
        if isinstance(segment, str):
            # Must be a Mapping and have the key
            if isinstance(current, collections.abc.Mapping):
                if segment in current:
                    current = current[segment]
                    continue
            # If we get here, it's a missing value
            return _handle_missing(path, default)

        elif isinstance(segment, int):
            # Must be a list or tuple and index must be valid
            if isinstance(current, (list, tuple)):
                try:
                    # Using indexing directly; Python handles negative indices.
                    # If out of range, it raises IndexError.
                    current = current[segment]
                    continue
                except IndexError:
                    pass
            # If we get here, it's a missing value (wrong type or out of range)
            return _handle_missing(path, default)

        else:
            # Should never happen given parse() guarantees str|int for non-wildcard paths
            return _handle_missing(path, default)

    return current


def _handle_missing(path: str, default):
    """Helper to return default or raise PathError when a segment is missing."""
    if default is _MISSING:
        raise PathError(path, "value not found")
    return default


def _is_index_in_list_range(seg: int, length: int) -> tuple[bool, bool]:
    """Return (ok, is_append) for *seg* against a list of *length*.

    Valid indices are ``-length .. length - 1`` (existing element) and
    ``length`` (append).  Anything else is invalid.
    """
    if -length <= seg < 0 or 0 <= seg < length:
        return True, False
    if seg == length:
        return True, True
    return False, False


def _next_create_type(seg) -> type | None:
    """Container type to create for a missing intermediate container.

    A ``dict`` for a str segment, a ``list`` for an int segment.
    """
    if isinstance(seg, str):
        return dict
    if isinstance(seg, int):
        return list
    return None


def set(obj, path: str, value) -> None:
    """Store *value* at *path* inside *obj*, mutating *obj* in place.

    Rules:
    *   The path must have at least one segment and contain no wildcard;
        otherwise ``PathError``.
    *   Every segment but the last is followed as :func:`get` would (through
        mappings, lists and tuples).  When the value at an intermediate
        segment is missing, a new container is created there: a ``list`` if
        the *next* segment is an index, a ``dict`` if it is a key.
    *   A container can only be created – and the final value only stored –
        inside a ``dict`` (for a key segment) or a ``list`` (for an index
        segment).
    *   In a list, indices ``-len .. len-1`` refer to existing elements and
        ``len`` appends.  Any other index raises ``PathError``.
    *   Any other combination (key on list, index on dict, or any segment on
        a string / number / ``None`` / a tuple that would have to change)
        raises ``PathError``.
    *   When :func:`set` raises, *obj* is left exactly as it was.
    """
    segments = parse(path)

    if not segments:
        raise PathError(path, "empty path cannot be used with set")
    if any(seg is WILDCARD for seg in segments):
        raise PathError(path, "wildcard is not allowed in set paths")

    # ------------------------------------------------------------------ #
    #  Phase 1 – validate and build a commit plan WITHOUT mutating obj.
    #
    #  ``frames`` lists the actions to perform top-down.  Each frame is a
    #  tuple describing how to move from the current (real) container to the
    #  next, and the last frame is the store.
    #
    #    ('key', seg)            – existing dict key, move to obj[seg]
    #    ('idx', seg)            – existing list index, move to obj[seg]
    #    ('create_dict', seg)    – create a dict into parent at seg
    #    ('create_list', seg)    – create a list into parent at seg
    #    ('store_key', seg)      – final: parent[seg] = value  (dict)
    #    ('store_idx', seg)      – final: parent[seg] = value  (existing)
    #    ('append', seg)         – final: parent.append(value) (index == len)
    # ------------------------------------------------------------------ #
    frames: list[tuple] = []
    # A placeholder mirrors the real structure so we can continue to
    # validate the remaining segments against a freshly "created" container.
    cur = obj

    last_index = len(segments) - 1

    for pos, seg in enumerate(segments):
        is_last = pos == last_index

        # ---- store into a dict (key segment) ----
        if isinstance(cur, collections.abc.Mapping):
            if isinstance(seg, str):
                if is_last:
                    frames.append(("store_key", seg))
                    break
                if seg in cur:
                    frames.append(("key", seg))
                    cur = cur[seg]
                    continue
                # missing intermediate -> create container per next segment
                next_seg = segments[pos + 1]
                ctype = _next_create_type(next_seg)
                if ctype is None:
                    raise PathError(path, "cannot create container for wildcard")
                frames.append(("create_dict" if ctype is dict else "create_list", seg))
                cur = ctype()
                continue
            else:
                raise PathError(path, "cannot use index segment on a dict")

        # ---- store into a list (index segment) ----
        if isinstance(cur, list):
            if isinstance(seg, int):
                ok, is_append = _is_index_in_list_range(seg, len(cur))
                if not ok:
                    raise PathError(path, f"index {seg} out of range for list of length {len(cur)}")
                if is_last:
                    if is_append:
                        frames.append(("append", seg))
                    else:
                        frames.append(("store_idx", seg))
                    break
                if is_append:
                    # Must create a container to append
                    next_seg = segments[pos + 1]
                    ctype = _next_create_type(next_seg)
                    if ctype is None:
                        raise PathError(path, "cannot create container for wildcard")
                    frames.append(("create_list" if ctype is list else "create_dict", seg))
                    cur = ctype()
                    # Note: 'cur' here is the *new* object. The parent list hasn't been
                    # modified yet in Phase 1. In Phase 2, we will append this new object
                    # to the actual parent list. The 'create_list' frame handler needs to
                    # handle this logic. Wait, 'create_list' in Phase 2 does 'cur.append(new)'
                    # if seg == len(cur). But here 'cur' is the *parent* list in Phase 2 loop.
                    # Let's trace Phase 2 for append.
                    # If we are at frame 'create_list' with seg=len(parent_list):
                    #   new = ctype()
                    #   if isinstance(cur, list) and seg == len(cur): cur.append(new)
                    #   cur = new
                    # This works if 'cur' in Phase 2 loop is the actual parent list.
                    # In Phase 1, 'cur' is a virtual proxy. This is fine.
                    continue
                # existing element – move into it (may be dict/list/tuple/...)
                frames.append(("idx", seg))
                cur = cur[seg]
                continue
            else:
                raise PathError(path, "cannot use key segment on a list")

        # ---- tuples: read-only, cannot store into them ----
        if isinstance(cur, tuple):
            if is_last:
                raise PathError(path, "cannot store value into a tuple")
            if isinstance(seg, int):
                try:
                    cur = cur[seg]
                except IndexError:
                    raise PathError(path, "index out of range for tuple")
                frames.append(("read_tuple", seg))
                continue
            else:
                raise PathError(path, "cannot use key segment on a tuple")

        # ---- everything else (str, number, None, ...) cannot be traversed ----
        raise PathError(
            path, "cannot descend into value of type %s" % type(cur).__name__
        )

    # ------------------------------------------------------------------ #
    #  Phase 2 – commit, applying every frame in order.  Phase 1 succeeded
    #  so no validation error can occur here; obj stays untouched on any
    #  PathError raised above.
    # ------------------------------------------------------------------ #
    cur = obj
    for action, seg in frames:
        if action == "key":
            cur = cur[seg]
        elif action == "idx":
            cur = cur[seg]
        elif action == "read_tuple":
            cur = cur[seg]
        elif action == "create_dict":
            new = {}
            cur[seg] = new
            cur = new
        elif action == "create_list":
            new = []
            # If parent is a list and seg == len -> append, else assign.
            if isinstance(cur, list) and seg == len(cur):
                cur.append(new)
            else:
                cur[seg] = new
            cur = new
        elif action == "store_key":
            cur[seg] = value
            return
        elif action == "store_idx":
            cur[seg] = value
            return
        elif action == "append":
            cur.append(value)
            return


def delete(obj, path: str):
    """Remove and return the value at *path* from its parent ``dict``/``list``.

    Negative indices work as in :func:`get`.  Raises ``PathError`` if the
    path is empty, contains a wildcard, the value is missing, or the parent
    is not a ``dict`` or ``list``.
    """
    segments = parse(path)

    if not segments:
        raise PathError(path, "empty path cannot be used with delete")
    if any(seg is WILDCARD for seg in segments):
        raise PathError(path, "wildcard is not allowed in delete paths")

    cur = obj
    # Walk to the parent of the last segment.
    for seg in segments[:-1]:
        if isinstance(seg, str):
            if isinstance(cur, collections.abc.Mapping) and seg in cur:
                cur = cur[seg]
                continue
            raise PathError(path, "value not found")
        elif isinstance(seg, int):
            if isinstance(cur, (list, tuple)):
                try:
                    cur = cur[seg]
                except IndexError:
                    raise PathError(path, "value not found")
                continue
            raise PathError(path, "value not found")
        else:
            raise PathError(path, "value not found")

    last = segments[-1]

    # ---- delete from a dict ----
    if isinstance(last, str):
        if isinstance(cur, collections.abc.Mapping) and last in cur:
            return cur.pop(last)
        raise PathError(path, "value not found")

    # ---- delete from a list ----
    if isinstance(last, int):
        if isinstance(cur, list):
            length = len(cur)
            if -length <= last < 0 or 0 <= last < length:
                return cur.pop(last)
            raise PathError(path, "index out of range")
        raise PathError(path, "parent is not a dict or list")

    raise PathError(path, "value not found")
