    """Validate that the grid is a 9x9 list of lists with integers 0-9.

    Args:
        grid: The grid to validate.

    Raises:
        ValueError: If the grid is not 9x9 or contains invalid values.
    """
    if not isinstance(grid, list) or len(grid) != 9:
        raise ValueError("Grid must be a list of 9 rows.")
    for row in grid:
        if not isinstance(row, list) or len(row) != 9:
            raise ValueError("Each row must be a list of 9 integers.")
        for val in row:
            if not isinstance(val, int) or isinstance(val, bool) or not 0 <= val <= 9:
                raise ValueError("Grid values must be integers from 0 to 9.")


def parse(text: str) -> Grid:
    """Parse a string representation of a Sudoku puzzle into a grid.

    Args:
        text: A string containing 81 cells in row-major order. 
              Digits 1-9 are givens. 0 and . are empty cells. 
              Whitespace is ignored.

    Returns:
        A 9x9 grid represented as a list of lists of integers.

    Raises:
        ValueError: If the string contains invalid characters or incorrect cell count.
    """
    cells = []
    for char in text:
        if char in " \t\n\r":
            continue
        elif char == "." or char == "0":
            cells.append(0)
        elif char in "123456789":
            cells.append(int(char))
        else:
            raise ValueError(f"Invalid character in Sudoku string: '{char}'")

    if len(cells) != 81:
        raise ValueError(f"Expected 81 cells, found {len(cells)}")

    grid = [cells[i * 9:(i + 1) * 9] for i in range(9)]
    return grid


def to_string(grid: Grid) -> str:
    """Convert a Sudoku grid to its string representation.

    Args:
        grid: A 9x9 grid.

    Returns:
        A string with 81 characters in row-major order, using '.' for empty cells.

    Raises:
        ValueError: If the grid is invalid.
    """
    _validate_grid(grid)
    chars = []
    for row in grid:
        for val in row:
            if val == 0:
                chars.append(".")
            else:
                chars.append(str(val))
    return "".join(chars)


def is_valid(grid: Grid) -> bool:
    """Check if a Sudoku grid is valid (no conflicts among non-zero cells).

    Args:
        grid: A 9x9 grid.

    Returns:
        True if the grid is valid, False otherwise.

    Raises:
        ValueError: If the grid shape or values are invalid.
    """
    _validate_grid(grid)

    # Check rows
    for r in range(9):
        seen = set()
        for c in range(9):
            val = grid[r][c]
            if val != 0:
                if val in seen:
                    return False
                seen.add(val)

    # Check columns
    for c in range(9):
        seen = set()
        for r in range(9):
            val = grid[r][c]
            if val != 0:
                if val in seen:
                    return False
                seen.add(val)

    # Check 3x3 boxes
    for box_r in range(0, 9, 3):
        for box_c in range(0, 9, 3):
            seen = set()
            for r in range(box_r, box_r + 3):
                for c in range(box_c, box_c + 3):
                    val = grid[r][c]
                    if val != 0:
                        if val in seen:
                            return False
                        seen.add(val)

    return True


def _get_candidates(grid: Grid, row: int, col: int) -> set[int]:
    """Determine candidate digits for a given empty cell."""
    if grid[row][col] != 0:
        return set()

    used = set()

    # Check row
    for c in range(9):
        if grid[row][c] != 0:
            used.add(grid[row][c])

    # Check column
    for r in range(9):
        if grid[r][col] != 0:
            used.add(grid[r][col])

    # Check box
    start_r, start_c = (row // 3) * 3, (col // 3) * 3
    for r in range(start_r, start_r + 3):
        for c in range(start_c, start_c + 3):
            if grid[r][c] != 0:
                used.add(grid[r][c])

    return set(range(1, 10)) - used


def _get_cells_in_row(row: int) -> list[tuple[int, int]]:
    """Get all cell coordinates in a row."""
    return [(row, c) for c in range(9)]


def _get_cells_in_col(col: int) -> list[tuple[int, int]]:
    """Get all cell coordinates in a column."""
    return [(r, col) for r in range(9)]


def _get_cells_in_box(box: int) -> list[tuple[int, int]]:
    """Get all cell coordinates in a box (0-8)."""
    start_r, start_c = (box // 3) * 3, (box % 3) * 3
    return [(r, c) for r in range(start_r, start_r + 3) for c in range(start_c, start_c + 3)]


def hint(grid: Grid) -> Optional[Tuple[int, int, int, str]]:
    """Find the next logical step for a Sudoku puzzle.

    Args:
        grid: A valid 9x9 Sudoku grid.

    Returns:
        A tuple (row, col, digit, reason) representing the next step,
        or None if no simple step is found.

    Raises:
        ValueError: If the grid is invalid.
    """
    _validate_grid(grid)
    if not is_valid(grid):
        raise ValueError("Grid is not valid.")

    # 1. Naked single: scanning row-major
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                candidates = _get_candidates(grid, r, c)
                if len(candidates) == 1:
                    digit = next(iter(candidates))
                    return (r, c, digit, "naked single")

    # 2. Hidden single: units order rows 0-8, cols 0-8, boxes 0-8
    # Digits 1-9 increasing order

    # Rows
    for r in range(9):
        cells_in_unit = _get_cells_in_row(r)
        empty_cells = [(rr, cc) for rr, cc in cells_in_unit if grid[rr][cc] == 0]
        if not empty_cells:
            continue

        # Determine digits not yet in the unit
        digits_in_unit = set(grid[rr][cc] for rr, cc in cells_in_unit if grid[rr][cc] != 0)
        missing_digits = sorted(set(range(1, 10)) - digits_in_unit)

        for d in missing_digits:
            positions = []
            for rr, cc in empty_cells:
                if d in _get_candidates(grid, rr, cc):
                    positions.append((rr, cc))
            if len(positions) == 1:
                r_pos, c_pos = positions[0]
                return (r_pos, c_pos, d, "hidden single in row")

    # Cols
    for c in range(9):
        cells_in_unit = _get_cells_in_col(c)
        empty_cells = [(rr, cc) for rr, cc in cells_in_unit if grid[rr][cc] == 0]
        if not empty_cells:
            continue

        digits_in_unit = set(grid[rr][cc] for rr, cc in cells_in_unit if grid[rr][cc] != 0)
        missing_digits = sorted(set(range(1, 10)) - digits_in_unit)

        for d in missing_digits:
            positions = []
            for rr, cc in empty_cells:
                if d in _get_candidates(grid, rr, cc):
                    positions.append((rr, cc))
            if len(positions) == 1:
                r_pos, c_pos = positions[0]
                return (r_pos, c_pos, d, "hidden single in column")

    # Boxes
    for b in range(9):
        cells_in_unit = _get_cells_in_box(b)
        empty_cells = [(rr, cc) for rr, cc in cells_in_unit if grid[rr][cc] == 0]
        if not empty_cells:
            continue

        digits_in_unit = set(grid[rr][cc] for rr, cc in cells_in_unit if grid[rr][cc] != 0)
        missing_digits = sorted(set(range(1, 10)) - digits_in_unit)

        for d in missing_digits:
            positions = []
            for rr, cc in empty_cells:
                if d in _get_candidates(grid, rr, cc):
                    positions.append((rr, cc))
            if len(positions) == 1:
                r_pos, c_pos = positions[0]
                return (r_pos, c_pos, d, "hidden single in box")

    return None


def difficulty(grid: Grid) -> Optional[Dict[str, int]]:
    """Estimate puzzle difficulty by simulating solution steps.

    Args:
        grid: A valid 9x9 Sudoku grid.

    Returns:
        A dictionary {'naked': N, 'hidden': H} counting steps used,
        or None if the puzzle cannot be completed using these steps.

    Raises:
        ValueError: If the grid is invalid.
    """
    _validate_grid(grid)
    if not is_valid(grid):
        raise ValueError("Grid is not valid.")

    grid_copy = copy.deepcopy(grid)
    counts = {'naked': 0, 'hidden': 0}

    while True:
        # Check if complete
        is_complete = True
        for r in range(9):
            for c in range(9):
                if grid_copy[r][c] == 0:
                    is_complete = False
                    break
            if not is_complete:
                break

        if is_complete:
            break

        step = hint(grid_copy)
        if step is None:
            return None

        r, c, d, reason = step
        grid_copy[r][c] = d

        if reason == 'naked single':
            counts['naked'] += 1
        elif reason in ('hidden single in row', 'hidden single in column', 'hidden single in box'):
            counts['hidden'] += 1

    return counts


def _get_possible_values(grid: Grid, row: int, col: int) -> List[int]:
    """Determine possible values for a given cell."""
    if grid[row][col] != 0:
        return []

    used = set()

    # Check row
    for c in range(9):
        if grid[row][c] != 0:
            used.add(grid[row][c])

    # Check column
    for r in range(9):
        if grid[r][col] != 0:
            used.add(grid[r][col])

    # Check box
    start_r, start_c = (row // 3) * 3, (col // 3) * 3
    for r in range(start_r, start_r + 3):
        for c in range(start_c, start_c + 3):
            if grid[r][c] != 0:
                used.add(grid[r][c])

    return [val for val in range(1, 10) if val not in used]


def _solve_backtrack(grid: Grid, count_mode: bool = False, limit: int = 1) -> List[Grid]:
    """Internal backtracking solver.

    Args:
        grid: The grid to solve (modified in place).
        count_mode: If True, find up to 'limit' solutions. If False, find first.
        limit: Max solutions to find in count_mode.

    Returns:
        List of solutions (max 'limit' if count_mode, else 0 or 1).
    """
    solutions = []

    # Find next empty cell
    empty_pos = None
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                empty_pos = (r, c)
                break
        if empty_pos:
            break

    # Base case: no empty cells
    if not empty_pos:
        solutions.append(copy.deepcopy(grid))
        return solutions

    r, c = empty_pos
    possible_vals = _get_possible_values(grid, r, c)

    for val in possible_vals:
        grid[r][c] = val
        sols = _solve_backtrack(grid, count_mode, limit)
        solutions.extend(sols)

        # Stop if limit reached in count mode
        if count_mode and len(solutions) >= limit:
            return solutions

        grid[r][c] = 0  # Backtrack

        # If not count mode, stop at first solution
        if not count_mode and solutions:
            return solutions

    return solutions


def solve(grid: Grid) -> Optional[Grid]:
    """Solve a Sudoku puzzle.

    Args:
        grid: A valid 9x9 Sudoku grid.

    Returns:
        A completed grid if solvable, None otherwise.

    Raises:
        ValueError: If the grid is invalid.
    """
    _validate_grid(grid)

    if not is_valid(grid):
        return None

    # Work on a deep copy to avoid modifying input
    grid_copy = copy.deepcopy(grid)
    solutions = _solve_backtrack(grid_copy, count_mode=False, limit=1)

    if solutions:
        return solutions[0]
    return None


def count_solutions(grid: Grid, limit: int = 2) -> int:
    """Count the number of solutions to a Sudoku puzzle.

    Args:
        grid: A valid 9x9 Sudoku grid.
        limit: Maximum number of solutions to count.

    Returns:
        The number of solutions, capped at 'limit'.

    Raises:
        ValueError: If limit < 1 or grid is invalid.
    """
    if limit < 1:
        raise ValueError("limit must be at least 1")

    _validate_grid(grid)

    if not is_valid(grid):
        return 0

    grid_copy = copy.deepcopy(grid)
    solutions = _solve_backtrack(grid_copy, count_mode=True, limit=limit)

    return len(solutions)
