def first_index(a: list, x) -> int:
    """Return the index of the first element equal to x in sorted list a, or -1."""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    if lo < len(a) and a[lo] == x:
        return lo
    return -1


def last_index(a: list, x) -> int:
    """Return the index of the last element equal to x in sorted list a, or -1."""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] <= x:
            lo = mid + 1
        else:
            hi = mid
    idx = lo - 1
    if idx >= 0 and a[idx] == x:
        return idx
    return -1


def insertion_point(a: list, x) -> int:
    """Return the smallest index i such that inserting x before a[i] keeps a sorted."""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo


def count(a: list, x) -> int:
    """Return how many elements in sorted list a equal x."""
    fi = first_index(a, x)
    if fi == -1:
        return 0
    li = last_index(a, x)
    return li - fi + 1


def rotation_offset(a: list) -> int:
    """
    For a rotated sorted list of distinct values, returns the index of the smallest element.
    0 if not rotated. Raises ValueError if list is empty.
    """
    if not a:
        raise ValueError("Empty list")

    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] > a[hi]:
            lo = mid + 1
        else:
            hi = mid
    return lo


def search_rotated(a: list, x) -> int:
    """
    Searches for x in a rotated sorted list of distinct values.
    Returns index of x or -1.
    """
    n = len(a)
    if n == 0:
        return -1

    # Find pivot (index of minimum element)
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] > a[hi]:
            lo = mid + 1
        else:
            hi = mid
    pivot = lo

    # Determine which sub-array contains x based on range
    # Left segment: [0, pivot) -> values [a[0], a[pivot-1]] (if pivot > 0)
    # Right segment: [pivot, n) -> values [a[pivot], a[n-1]]

    if pivot > 0 and a[0] <= x <= a[pivot - 1]:
        # x is in the left sorted segment
        lo, hi = 0, pivot - 1
    elif a[pivot] <= x <= a[n - 1]:
        # x is in the right sorted segment
        lo, hi = pivot, n - 1
    else:
        # x is out of bounds of the value ranges
        return -1

    # Standard binary search in the determined range
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == x:
            return mid
        elif a[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1

    return -1


def isqrt(n: int) -> int:
    """Return the largest integer r such that r*r <= n.

    Raises:
        TypeError: If n is not an int (bools are rejected).
        ValueError: If n is negative.
    """
    if type(n) is not int:
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    # Binary search for the largest r such that r*r <= n.
    # We maintain the invariant that lo is always valid (lo*lo <= n) if lo >= 0.
    # hi is the current upper bound to search.
    lo, hi = 0, n

    # Special handling for small numbers to optimize slightly or just ensure correctness.
    # If n == 0, lo=0, hi=0, loop doesn't run, returns 0. Correct.

    while lo < hi:
        # Use upper mid to prevent infinite loop when lo = hi - 1
        # mid = (lo + hi + 1) // 2
        mid = (lo + hi + 1) // 2

        # Calculate mid * mid. This can be huge for large n, but Python handles big ints.
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid - 1

    return lo
