import tempfile
from pathlib import Path
from typing import Union

from todo.model import Task, normalize_title, normalize_tag


class StoreError(Exception):
    """Raised when the todo file is invalid or cannot be read."""
    pass


class TodoStore:
    def __init__(self, path: Union[str, Path]):
        self.path = Path(path)
        self._next_id = 1
        self._tasks: list[Task] = []
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            # Missing file is an empty store
            self._next_id = 1
            self._tasks = []
            return

        try:
            raw = self.path.read_text(encoding="utf-8")
            data = json.loads(raw)
        except json.JSONDecodeError as e:
            raise StoreError(f"Invalid JSON: {e}") from e
        except OSError as e:
            raise StoreError(f"Cannot read file: {e}") from e

        if not isinstance(data, dict):
            raise StoreError("Root is not an object")

        version = data.get("version")
        if version != 1:
            raise StoreError(f"Unsupported version: {version!r}")

        next_id = data.get("next_id")
        if not isinstance(next_id, int) or isinstance(next_id, bool):
            raise StoreError("'next_id' must be an integer")
        if next_id < 1:
            raise StoreError("'next_id' must be >= 1")

        tasks_raw = data.get("tasks")
        if not isinstance(tasks_raw, list):
            raise StoreError("'tasks' must be a list")

        loaded_tasks = []
        seen_ids = set()

        for item in tasks_raw:
            try:
                task = Task.from_dict(item)
            except ValueError as e:
                raise StoreError(f"Invalid task: {e}") from e

            if task.id in seen_ids:
                raise StoreError(f"Duplicate task id: {task.id}")
            if task.id >= next_id:
                raise StoreError(f"Task id {task.id} >= next_id {next_id}")

            loaded_tasks.append(task)
            seen_ids.add(task.id)

        # Check order
        for i in range(1, len(loaded_tasks)):
            if loaded_tasks[i].id < loaded_tasks[i-1].id:
                raise StoreError("Tasks are not in increasing id order")

        self._next_id = next_id
        self._tasks = loaded_tasks

    def _save(self) -> None:
        data = {
            "version": 1,
            "next_id": self._next_id,
            "tasks": [t.to_dict() for t in self._tasks]
        }

        # Atomic write: temp file next to target, then replace
        target_dir = self.path.parent
        try:
            fd, tmp_path = tempfile.mkstemp(dir=target_dir, prefix=".todo_", suffix=".tmp")
            try:
                with os.fdopen(fd, "w", encoding="utf-8") as f:
                    json.dump(data, f, indent=2)
                os.replace(tmp_path, self.path)
            except Exception:
                # Cleanup temp file on failure
                try:
                    os.remove(tmp_path)
                except OSError:
                    pass
                raise
        except OSError as e:
            raise StoreError(f"Failed to write store: {e}") from e

    def _get_copy(self, task: Task) -> Task:
        """Returns a copy of the task to prevent external mutation."""
        return Task(
            id=task.id,
            title=task.title,
            tags=list(task.tags), # copy list
            done=task.done
        )

    def _find_task_index(self, task_id: int) -> int:
        """Finds index of task with id, or raises KeyError."""
        for i, t in enumerate(self._tasks):
            if t.id == task_id:
                return i
        raise KeyError(task_id)

    def _find_task(self, task_id: int) -> Task:
        """Finds task object internally, or raises KeyError."""
        for t in self._tasks:
            if t.id == task_id:
                return t
        raise KeyError(task_id)

    def add(self, title: str, tags=()) -> Task:
        title = normalize_title(title)
        norm_tags = sorted(set(normalize_tag(t) for t in tags))

        new_task = Task(
            id=self._next_id,
            title=title,
            tags=norm_tags,
            done=False
        )

        self._tasks.append(new_task)
        self._next_id += 1
        self._save()

        return self._get_copy(new_task)

    def get(self, task_id: int) -> Task:
        task = self._find_task(task_id)
        return self._get_copy(task)

    def list(self, status: str = "open", tags=()) -> list[Task]:
        if status not in ("open", "done", "all"):
            raise ValueError("status must be 'open', 'done', or 'all'")

        target_tags = set()
        for t in tags:
            target_tags.add(normalize_tag(t))

        result = []
        for task in self._tasks:
            # Status filter
            if status == "open" and task.done:
                continue
            if status == "done" and not task.done:
                continue

            # Tag filter
            if target_tags:
                if not target_tags.issubset(set(task.tags)):
                    continue

            result.append(self._get_copy(task))

        return result

    def mark_done(self, task_id: int) -> Task:
        task = self._find_task(task_id)
        if not task.done:
            task.done = True
            self._save()
        return self._get_copy(task)

    def remove(self, task_id: int) -> Task:
        idx = self._find_task_index(task_id)
        task = self._tasks.pop(idx)
        self._save()
        return self._get_copy(task)

    def edit(self, task_id: int, title: str | None = None, add_tags=(), remove_tags=()) -> Task:
        task = self._find_task(task_id)

        # Prepare new state
        new_title = task.title
        new_tags = set(task.tags)

        if title is not None:
            try:
                new_title = normalize_title(title)
            except ValueError:
                raise ValueError("Invalid title")

        for tag in add_tags:
            try:
                norm_tag = normalize_tag(tag)
                new_tags.add(norm_tag)
            except ValueError:
                raise ValueError(f"Invalid add-tag: {tag!r}")

        for tag in remove_tags:
            try:
                norm_tag = normalize_tag(tag)
                new_tags.discard(norm_tag)
            except ValueError:
                raise ValueError(f"Invalid remove-tag: {tag!r}")

        # If nothing changed, we can skip write, but return copy is still needed
        changed = (new_title != task.title) or (set(task.tags) != new_tags)

        task.title = new_title
        task.tags = sorted(new_tags)

        if changed:
            self._save()

        return self._get_copy(task)
