import re
import datetime
from dataclasses import dataclass

_TAG_PATTERN = re.compile(r"^[a-z0-9][a-z0-9_-]*$")
_PRIORITY_VALUES = frozenset({"high", "normal", "low"})


def normalize_title(title: str) -> str:
    """Strips surrounding whitespace and returns the result. Raises ValueError if empty."""
    stripped = title.strip()
    if not stripped:
        raise ValueError("Title cannot be empty")
    return stripped


def normalize_tag(tag: str) -> str:
    """Strips surrounding whitespace, lowercases, and validates against ^[a-z0-9][a-z0-9_-]*$."""
    stripped = tag.strip().lower()
    if not _TAG_PATTERN.fullmatch(stripped):
        raise ValueError(f"Invalid tag: {tag!r}")
    return stripped


def normalize_priority(p: str) -> str:
    """Strips, lowercases, and validates that the priority is high, normal, or low."""
    stripped = p.strip().lower()
    if stripped not in _PRIORITY_VALUES:
        raise ValueError(f"Invalid priority: {p!r}")
    return stripped


def parse_date(s: str) -> datetime.date:
    """Parses a YYYY-MM-DD string into a datetime.date. Raises ValueError if invalid."""
    # Strict format check
    m = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", s)
    if not m:
        raise ValueError(f"Invalid date format: {s!r}")
    y, mo, d = map(int, m.groups())
    try:
        return datetime.date(y, mo, d)
    except ValueError as e:
        raise ValueError(f"Invalid calendar date: {s!r}") from e


@dataclass
class Task:
    id: int
    title: str
    tags: list[str]
    done: bool = False
    priority: str = "normal"
    due: datetime.date | None = None

    def __post_init__(self):
        # Ensure tags are sorted and unique
        self.tags = sorted(set(self.tags))
        # Validate priority
        self.priority = normalize_priority(self.priority)

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "title": self.title,
            "tags": self.tags,
            "done": self.done,
            "priority": self.priority,
            "due": self.due.isoformat() if self.due is not None else None,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "Task":
        """Builds a task from a dict, validating types and values."""
        required_keys = {"id", "title", "tags", "done"}
        if not required_keys.issubset(d.keys()):
            missing = required_keys - d.keys()
            raise ValueError(f"Missing keys: {missing}")

        raw_id = d["id"]
        raw_title = d["title"]
        raw_tags = d["tags"]
        raw_done = d["done"]

        # Optional fields with defaults
        raw_priority = d.get("priority", "normal")
        raw_due = d.get("due", None)

        # Validate types for required fields
        if not isinstance(raw_id, int) or isinstance(raw_id, bool):
            raise ValueError("'id' must be an int (and not a bool)")
        if not isinstance(raw_title, str):
            raise ValueError("'title' must be a str")
        if not isinstance(raw_tags, list):
            raise ValueError("'tags' must be a list")
        if not all(isinstance(t, str) for t in raw_tags):
            raise ValueError("All items in 'tags' must be str")
        if not isinstance(raw_done, bool):
            raise ValueError("'done' must be a bool")

        # Normalize and validate content for required fields
        try:
            title = normalize_title(raw_title)
            tags = sorted(set(normalize_tag(t) for t in raw_tags))
        except ValueError as e:
            raise ValueError(f"Invalid field content: {e}") from e

        # Validate priority
        try:
            priority = normalize_priority(raw_priority)
        except ValueError as e:
            raise ValueError(f"Invalid priority: {e}") from e

        # Validate due date
        due = None
        if raw_due is not None:
            if not isinstance(raw_due, str):
                raise ValueError("'due' must be a string or null")
            try:
                due = parse_date(raw_due)
            except ValueError as e:
                raise ValueError(f"Invalid due date: {e}") from e

        return cls(
            id=raw_id,
            title=title,
            tags=tags,
            done=raw_done,
            priority=priority,
            due=due,
        )
