import json
import os
import tempfile
import datetime
from pathlib import Path
from typing import Union

from todo.model import (
    Task,
    normalize_title,
    normalize_tag,
    normalize_priority,
    parse_date,
)


class StoreError(Exception):
    """Raised when the todo file is invalid or cannot be read."""
    pass


class TodoStore:
    def __init__(self, path: Union[str, Path]):
        self.path = Path(path)
        self._next_id = 1
        self._tasks: list[Task] = []
        self._needs_save = False
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            # Missing file is an empty store
            self._next_id = 1
            self._tasks = []
            self._needs_save = False
            return

        try:
            raw = self.path.read_text(encoding="utf-8")
            data = json.loads(raw)
        except json.JSONDecodeError as e:
            raise StoreError(f"Invalid JSON: {e}") from e
        except OSError as e:
            raise StoreError(f"Cannot read file: {e}") from e

        if not isinstance(data, dict):
            raise StoreError("Root is not an object")

        version = data.get("version")
        if version not in (1, 2):
            raise StoreError(f"Unsupported version: {version!r}")

        # If version 1, we will need to save as version 2 on next change
        self._needs_save = (version == 1)

        next_id = data.get("next_id")
        if not isinstance(next_id, int) or isinstance(next_id, bool):
            raise StoreError("'next_id' must be an integer")
        if next_id < 1:
            raise StoreError("'next_id' must be >= 1")

        tasks_raw = data.get("tasks")
        if not isinstance(tasks_raw, list):
            raise StoreError("'tasks' must be a list")

        loaded_tasks = []
        seen_ids = set()

        for item in tasks_raw:
            try:
                task = Task.from_dict(item)
            except ValueError as e:
                raise StoreError(f"Invalid task: {e}") from e

            if task.id in seen_ids:
                raise StoreError(f"Duplicate task id: {task.id}")
            if task.id >= next_id:
                raise StoreError(f"Task id {task.id} >= next_id {next_id}")

            loaded_tasks.append(task)
            seen_ids.add(task.id)

        # Check order
        for i in range(1, len(loaded_tasks)):
            if loaded_tasks[i].id < loaded_tasks[i-1].id:
                raise StoreError("Tasks are not in increasing id order")

        self._next_id = next_id
        self._tasks = loaded_tasks

    def _save(self) -> None:
        data = {
            "version": 2,
            "next_id": self._next_id,
            "tasks": [t.to_dict() for t in self._tasks]
        }

        # Atomic write: temp file next to target, then replace
        target_dir = self.path.parent
        try:
            fd, tmp_path = tempfile.mkstemp(dir=target_dir, prefix=".todo_", suffix=".tmp")
            try:
                with os.fdopen(fd, "w", encoding="utf-8") as f:
                    json.dump(data, f, indent=2)
                os.replace(tmp_path, self.path)
                self._needs_save = False
            except Exception:
                # Cleanup temp file on failure
                try:
                    os.remove(tmp_path)
                except OSError:
                    pass
                raise
        except OSError as e:
            raise StoreError(f"Failed to write store: {e}") from e

    def _check_and_save(self):
        """Saves if needed (e.g. after loading a v1 file)."""
        if self._needs_save:
            self._save()

    def _get_copy(self, task: Task) -> Task:
        """Returns a copy of the task to prevent external mutation."""
        return Task(
            id=task.id,
            title=task.title,
            tags=list(task.tags),
            done=task.done,
            priority=task.priority,
            due=task.due,
        )

    def _find_task_index(self, task_id: int) -> int:
        """Finds index of task with id, or raises KeyError."""
        for i, t in enumerate(self._tasks):
            if t.id == task_id:
                return i
        raise KeyError(task_id)

    def _find_task(self, task_id: int) -> Task:
        """Finds task object internally, or raises KeyError."""
        for t in self._tasks:
            if t.id == task_id:
                return t
        raise KeyError(task_id)

    def add(self, title: str, tags=(), priority: str = "normal", due: datetime.date | None = None) -> Task:
        title = normalize_title(title)
        norm_tags = sorted(set(normalize_tag(t) for t in tags))
        norm_priority = normalize_priority(priority)

        # If due is provided, it must be a date object or None. 
        # We don't validate the date object itself as it's already a datetime.date.
        # However, we ensure it's passed correctly.

        new_task = Task(
            id=self._next_id,
            title=title,
            tags=norm_tags,
            done=False,
            priority=norm_priority,
            due=due,
        )

        self._tasks.append(new_task)
        self._next_id += 1
        self._save()

        return self._get_copy(new_task)

    def get(self, task_id: int) -> Task:
        task = self._find_task(task_id)
        return self._get_copy(task)

    def list(self, status: str = "open", tags=(), overdue: bool = False, today: datetime.date | None = None, sort: str = "id") -> list[Task]:
        if status not in ("open", "done", "all"):
            raise ValueError("status must be 'open', 'done', or 'all'")

        if sort not in ("id", "priority", "due"):
            raise ValueError("sort must be 'id', 'priority', or 'due'")

        if overdue and today is None:
            raise ValueError("'today' must be provided when 'overdue' is True")

        target_tags = set()
        for t in tags:
            target_tags.add(normalize_tag(t))

        result = []
        for task in self._tasks:
            # Status filter
            if status == "open" and task.done:
                continue
            if status == "done" and not task.done:
                continue

            # Tag filter
            if target_tags:
                if not target_tags.issubset(set(task.tags)):
                    continue

            # Overdue filter
            if overdue:
                # Must be open (already checked by status filter if status != 'all' or 'done')
                # But strictly, overdue means not done.
                if task.done:
                    continue
                if task.due is None:
                    continue
                if task.due >= today:
                    continue

            result.append(self._get_copy(task))

        # Sorting
        if sort == "id":
            result.sort(key=lambda t: t.id)
        elif sort == "priority":
            priority_order = {"high": 0, "normal": 1, "low": 2}
            result.sort(key=lambda t: (priority_order.get(t.priority, 1), t.id))
        elif sort == "due":
            # Tasks with due date first (earliest first), then tasks without due date
            # Tie break by id
            def due_sort_key(t):
                if t.due is None:
                    return (1, t.id)  # 1 ensures they come after those with dates (0)
                return (0, t.due, t.id)
            result.sort(key=due_sort_key)

        return result

    def mark_done(self, task_id: int) -> Task:
        task = self._find_task(task_id)
        if not task.done:
            task.done = True
            self._save()
        return self._get_copy(task)

    def remove(self, task_id: int) -> Task:
        idx = self._find_task_index(task_id)
        task = self._tasks.pop(idx)
        self._save()
        return self._get_copy(task)

    def edit(self, task_id: int, title: str | None = None, add_tags=(), remove_tags=(), priority: str | None = None, due: datetime.date | None = None, clear_due: bool = False) -> Task:
        if due is not None and clear_due:
            raise ValueError("Cannot specify both 'due' and 'clear_due'")

        task = self._find_task(task_id)

        # Prepare new state
        new_title = task.title
        new_tags = set(task.tags)
        new_priority = task.priority
        new_due = task.due

        if title is not None:
            try:
                new_title = normalize_title(title)
            except ValueError:
                raise ValueError("Invalid title")

        for tag in add_tags:
            try:
                norm_tag = normalize_tag(tag)
                new_tags.add(norm_tag)
            except ValueError:
                raise ValueError(f"Invalid add-tag: {tag!r}")

        for tag in remove_tags:
            try:
                norm_tag = normalize_tag(tag)
                new_tags.discard(norm_tag)
            except ValueError:
                raise ValueError(f"Invalid remove-tag: {tag!r}")

        if priority is not None:
            try:
                new_priority = normalize_priority(priority)
            except ValueError:
                raise ValueError(f"Invalid priority: {priority!r}")

        if clear_due:
            new_due = None
        elif due is not None:
            new_due = due

        # Check for changes
        changed = (
            new_title != task.title 
            or set(task.tags) != new_tags 
            or new_priority != task.priority 
            or new_due != task.due
        )

        task.title = new_title
        task.tags = sorted(new_tags)
        task.priority = new_priority
        task.due = new_due

        if changed:
            self._save()

        return self._get_copy(task)
