"""Parser for the template engine."""

from __future__ import annotations
import dataclasses
from typing import Union, Optional, Any, List
from .lexer import tokenize, Token, TemplateSyntaxError

# ---------------------------------------------------------------------------
# AST Nodes
# ---------------------------------------------------------------------------

@dataclasses.dataclass
class Node:
    pass

@dataclasses.dataclass
class TextNode(Node):
    text: str

# Expressions
@dataclasses.dataclass
class Expr:
    pass

@dataclasses.dataclass
class StrLit(Expr):
    value: str

@dataclasses.dataclass
class IntLit(Expr):
    value: int

@dataclasses.dataclass
class PathExpr(Expr):
    base: str
    segments: List[Union[str, int]]

@dataclasses.dataclass
class Filter:
    name: str
    arg: Union[str, int, None] = None

@dataclasses.dataclass
class FilterExpr(Expr):
    base: Expr
    filters: List[Filter] = dataclasses.field(default_factory=list)

# Conditions
@dataclasses.dataclass
class Cond:
    pass

@dataclasses.dataclass
class BoolOp(Cond):
    op: str  # "and", "or"
    left: Cond
    right: Cond

@dataclasses.dataclass
class NotOp(Cond):
    operand: Cond

@dataclasses.dataclass
class Compare(Cond):
    left: Expr
    op: str
    right: Expr

# Statements
@dataclasses.dataclass
class VarNode(Node):
    lineno: int
    expr: FilterExpr

@dataclasses.dataclass
class IfBranch:
    condition: Optional[Cond]  # None for else branch
    body: List[Node]

@dataclasses.dataclass
class IfNode(Node):
    lineno: int
    branches: List[IfBranch]

@dataclasses.dataclass
class ForNode(Node):
    lineno: int
    name: str
    iterable: FilterExpr
    body: List[Node]
    else_body: List[Node]  # Empty list if no else

# ---------------------------------------------------------------------------
# Parser Helper Classes / Constants
# ---------------------------------------------------------------------------

RESERVED_WORDS = {"and", "or", "not", "in"}
COMPARISON_OPS = {"==", "!=", "<", "<=", ">", ">="}

FILTERS_WITHOUT_ARGS = {"upper", "lower", "trim", "length", "first", "last", "reverse", "items"}
FILTERS_WITH_STRING_ARG = {"join"}
FILTERS_WITH_INT_ARG = {"truncate", "default"} # default can be string or int
FILTERS_WITH_STR_OR_INT_ARG = {"default"}

# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def error(self, msg: str, lineno: int) -> None:
        raise TemplateSyntaxError(msg, lineno)

    def peek(self) -> Optional[Token]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self) -> Token:
        tok = self.peek()
        if tok is None:
            raise TemplateSyntaxError("unexpected end of template", self._current_lineno())
        self.pos += 1
        return tok

    def _current_lineno(self) -> int:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos].lineno
        if self.tokens:
            return self.tokens[-1].lineno
        return 1

    def parse(self) -> List[Node]:
        nodes = self.parse_body()
        if self.pos != len(self.tokens):
            # Should not happen if parse_body handles all tokens
            pass 
        return nodes

    def parse_body(self, end_keywords: List[str] | None = None) -> List[Node]:
        nodes: List[Node] = []
        while True:
            tok = self.peek()
            if tok is None:
                break

            if tok.kind == "block":
                # Check if it's a closing keyword
                # The value is stripped
                parts = tok.value.split()
                if not parts:
                    self.error("empty block", tok.lineno)
                first_word = parts[0]

                if end_keywords and first_word in end_keywords:
                    break

                # Parse statement
                node = self.parse_block(tok)
                nodes.append(node)
            elif tok.kind == "var":
                node = self.parse_var(tok)
                nodes.append(node)
            elif tok.kind == "text":
                nodes.append(TextNode(tok.value))
                self.consume()
            else:
                self.error(f"unexpected token kind: {tok.kind}", tok.lineno)

        return nodes

    def parse_var(self, tok: Token) -> VarNode:
        self.consume() # consume the var token
        expr = self.parse_value_expression(tok.value, tok.lineno)
        return VarNode(tok.lineno, expr)

    def parse_block(self, tok: Token) -> Node:
        self.consume() # consume the block token
        value = tok.value
        lineno = tok.lineno

        if not value:
            self.error("empty block", lineno)

        parts = value.split()
        keyword = parts[0]

        if keyword == "for":
            return self.parse_for(value, parts, lineno)
        elif keyword == "if":
            return self.parse_if(value, parts, lineno)
        else:
            self.error(f"unknown statement: {keyword}", lineno)
            # unreachable
            return Node() 

    def parse_for(self, value: str, parts: List[str], lineno: int) -> ForNode:
        # Syntax: {% for NAME in EXPR %}
        # parts = ["for", "name", "in", "expr..."]
        if len(parts) < 4 or parts[2] != "in":
            self.error("malformed for statement", lineno)

        name = parts[1]
        if name in RESERVED_WORDS:
            self.error(f"cannot use reserved word '{name}' as loop variable", lineno)

        expr_str = " ".join(parts[3:])
        if not expr_str:
            self.error("missing iterable in for statement", lineno)

        iterable_expr = self.parse_value_expression(expr_str, lineno)

        # Parse body until endfor
        # We need to handle nested ifs etc.
        # parse_body will stop at "endfor" keyword in block

        # But wait, parse_body looks at the token stream.
        # The current token stream is positioned AFTER this 'for' block token.

        body_nodes = self.parse_body(end_keywords=["endfor", "else"])

        next_tok = self.peek()
        if next_tok is None:
            self.error("unclosed for", lineno)

        # It must be a block token with value starting with endfor or else
        if next_tok.kind != "block":
            self.error("expected endfor or else", next_tok.lineno)

        next_parts = next_tok.value.split()
        if not next_parts:
             self.error("empty block", next_tok.lineno)

        next_kw = next_parts[0]

        else_body: List[Node] = []

        if next_kw == "else":
            self.consume() # consume else
            # Parse until endfor
            else_body = self.parse_body(end_keywords=["endfor"])
            next_tok = self.peek()
            if next_tok is None or next_tok.kind != "block" or next_tok.value.split()[0] != "endfor":
                self.error("expected endfor", next_tok.lineno if next_tok else lineno)
        elif next_kw == "endfor":
            pass
        else:
            self.error(f"unexpected block in for: {next_kw}", next_tok.lineno)

        # Consume endfor
        endfor_tok = self.consume()
        if endfor_tok.value != "endfor":
            # Should have been checked
            self.error("expected endfor", endfor_tok.lineno)

        return ForNode(lineno, name, iterable_expr, body_nodes, else_body)

    def parse_if(self, value: str, parts: List[str], lineno: int) -> IfNode:
        # Syntax: {% if COND %}...{% elif COND %}...{% else %}...{% endif %}
        # First part is "if"

        # Check if there's an expression
        if len(parts) <= 1:
            self.error("missing condition in if", lineno)

        cond_str = " ".join(parts[1:])
        condition = self.parse_condition(cond_str, lineno)

        branches: List[IfBranch] = []

        # Parse first body
        body = self.parse_body(end_keywords=["elif", "else", "endif"])
        branches.append(IfBranch(condition, body))

        has_else = False

        while True:
            tok = self.peek()
            if tok is None:
                self.error("unclosed if", lineno)

            if tok.kind != "block":
                self.error("expected block", tok.lineno)

            block_parts = tok.value.split()
            if not block_parts:
                self.error("empty block", tok.lineno)

            kw = block_parts[0]

            if kw == "elif":
                if has_else:
                    self.error("elif after else", tok.lineno)

                if len(block_parts) <= 1:
                    self.error("missing condition in elif", tok.lineno)

                self.consume() # consume elif
                elif_cond_str = " ".join(block_parts[1:])
                elif_cond = self.parse_condition(elif_cond_str, tok.lineno)

                elif_body = self.parse_body(end_keywords=["elif", "else", "endif"])
                branches.append(IfBranch(elif_cond, elif_body))

            elif kw == "else":
                if has_else:
                    self.error("duplicate else", tok.lineno)

                if len(block_parts) > 1:
                    # "else" should be alone
                    self.error("unexpected token after else", tok.lineno)

                self.consume() # consume else
                has_else = True
                else_body = self.parse_body(end_keywords=["endif"])
                branches.append(IfBranch(None, else_body))

            elif kw == "endif":
                self.consume() # consume endif
                break
            else:
                self.error(f"unexpected block in if: {kw}", tok.lineno)

        return IfNode(lineno, branches)

    # -----------------------------------------------------------------------
    # Expression Parsing
    # -----------------------------------------------------------------------

    def parse_value_expression(self, source: str, lineno: int) -> FilterExpr:
        # Parse atom
        atom = self.parse_atom(source, lineno)
        filters = []

        # Parse filters: |name[:arg]
        # We need to parse the remainder of the string after the atom
        # But my parse_atom returns the Atom and the remaining string?
        # No, the design above was to parse from a string context.
        # Let's refactor to use a token-like scanner for the expression string.

        # Actually, simpler: tokenize the expression string? 
        # The lexer only tokenizes the whole source. 
        # Inside a block/var, the "value" is a raw string like "a | b:c".
        # I need a mini-parser for this string.

        return self._parse_expr_from_string(source, lineno)

    def _parse_expr_from_string(self, source: str, lineno: int) -> FilterExpr:
        # This is a bit messy if we don't use a proper tokenizer for expressions.
        # Let's implement a simple recursive descent on the string.

        expr = FilterExpr(base=None, filters=[]) # type: ignore

        # Parse Base Atom
        remaining = source.strip()
        if not remaining:
            self.error("empty expression", lineno)

        atom, remaining = self._parse_atom_string(remaining, lineno)
        expr.base = atom

        # Parse Filters
        while remaining:
            remaining = remaining.strip()
            if not remaining:
                break

            if not remaining.startswith("|"):
                # If there is leftover text, it's a syntax error
                # Or maybe it's part of the atom? No, atom parsing should consume valid parts.
                self.error(f"unexpected characters in expression: {remaining}", lineno)

            remaining = remaining[1:].strip()

            # Parse filter name
            name = self._read_name(remaining, lineno)
            if not name:
                 self.error("expected filter name", lineno)

            remaining = remaining[len(name):].strip()

            # Parse optional argument
            arg = None
            if remaining.startswith(":"):
                remaining = remaining[1:].strip()
                arg, remaining = self._parse_filter_arg(remaining, lineno)

            elif remaining and not remaining.startswith("|"):
                 # If there's text that isn't a pipe or colon, and we just parsed a name,
                 # it might be an error or end of expr?
                 # But usually filters are just |name or |name:arg
                 # If we have "upper lower", that's an error.
                 self.error(f"unexpected text after filter: {remaining}", lineno)

            filters.append(Filter(name, arg))

        expr.filters = filters
        return expr

    def _read_name(self, source: str, lineno: int) -> str:
        if not source or not (source[0].isalpha() or source[0] == '_'):
            return ""
        i = 0
        while i < len(source) and (source[i].isalnum() or source[i] == '_'):
            i += 1
        return source[:i]

    def _parse_atom_string(self, source: str, lineno: int) -> tuple[Expr, str]:
        source = source.strip()
        if not source:
            self.error("expected atom", lineno)

        # String literal
        if source[0] in ('"', "'"):
            quote = source[0]
            i = 1
            while i < len(source) and source[i] != quote:
                i += 1
            if i >= len(source):
                self.error("unterminated string", lineno)
            val = source[1:i]
            return StrLit(val), source[i+1:]

        # Integer literal
        if source[0].isdigit() or (source[0] == '-' and len(source) > 1 and source[1].isdigit()):
            i = 1 if source[0] == '-' else 0
            while i < len(source) and source[i].isdigit():
                i += 1
            val_str = source[:i]
            val = int(val_str)
            return IntLit(val), source[i:]

        # Name / Path
        name = self._read_name(source, lineno)
        if not name:
            self.error(f"invalid atom: {source[:10]}", lineno)

        if name in RESERVED_WORDS:
            self.error(f"cannot use reserved word '{name}' as name", lineno)

        remaining = source[len(name):]
        segments = []

        # Parse segments .segment
        # .name or .0
        while remaining.startswith("."):
            remaining = remaining[1:].strip()
            if not remaining:
                self.error("expected segment after dot", lineno)

            # Try integer first?
            # Spec: "non-negative integer" or "name"
            # If it starts with digit, treat as integer segment?
            # But what about `0` as name? Names can't start with digit.
            # So if starts with digit, it's an index.

            seg_val: Union[str, int]
            if remaining[0].isdigit():
                j = 0
                while j < len(remaining) and remaining[j].isdigit():
                    j += 1
                seg_val = int(remaining[:j])
                remaining = remaining[j:].strip()
            else:
                seg_name = self._read_name(remaining, lineno)
                if not seg_name:
                    self.error("invalid segment", lineno)
                if seg_name in RESERVED_WORDS:
                     self.error(f"cannot use reserved word '{seg_name}' as segment", lineno)
                seg_val = seg_name
                remaining = remaining[len(seg_name):].strip()

            segments.append(seg_val)

        return PathExpr(name, segments), remaining

    def _parse_filter_arg(self, source: str, lineno: int) -> tuple[Union[str, int], str]:
        source = source.strip()
        if not source:
            self.error("expected filter argument", lineno)

        if source[0] in ('"', "'"):
            quote = source[0]
            i = 1
            while i < len(source) and source[i] != quote:
                i += 1
            if i >= len(source):
                self.error("unterminated string arg", lineno)
            return source[1:i], source[i+1:]

        if source[0].isdigit() or (source[0] == '-' and len(source) > 1 and source[1].isdigit()):
            j = 1 if source[0] == '-' else 0
            while j < len(source) and source[j].isdigit():
                j += 1
            return int(source[:j]), source[j:]

        self.error("invalid filter argument", lineno)
        return "", "" # unreachable

    # -----------------------------------------------------------------------
    # Condition Parsing
    # -----------------------------------------------------------------------

    def parse_condition(self, source: str, lineno: int) -> Cond:
        # We need to parse: Or -> And -> Not -> Compare
        # And handle the fact that we are working with a string source

        # This is tricky because we need to split by operators while respecting
        # atoms. 
        # Let's build a mini-tokenizer for the condition string.

        tokens = self._tokenize_condition(source, lineno)

        # Now parse tokens
        self.cond_tokens = tokens
        self.cond_pos = 0

        cond = self._parse_or()

        if self.cond_pos != len(tokens):
            self.error("trailing characters in condition", lineno)

        return cond

    def _tokenize_condition(self, source: str, lineno: int) -> List[Token]:
        # Simplified tokenizer for expressions within blocks
        # Returns list of "tokens" for the parser. 
        # I'll reuse the Token class but with kind representing expression parts.
        # Kind: "STR", "INT", "NAME", "OP", "DOT", "PIPE", "COLON", "AND", "OR", "NOT", "IN", "EOF"
        # Actually, for conditions, I mainly need to identify operators vs values.

        tokens = []
        i = 0
        n = len(source)
        while i < n:
            # Skip whitespace
            while i < n and source[i].isspace():
                i += 1
            if i >= n:
                break

            ch = source[i]

            if ch in ('"', "'"):
                quote = ch
                j = i + 1
                while j < n and source[j] != quote:
                    j += 1
                if j >= n:
                    self.error("unterminated string", lineno)
                tokens.append(Token("STR", source[i+1:j], lineno))
                i = j + 1

            elif ch.isdigit() or (ch == '-' and i + 1 < n and source[i+1].isdigit()):
                j = i + 1 if ch == '-' else i
                while j < n and source[j].isdigit():
                    j += 1
                tokens.append(Token("INT", source[i:j], lineno))
                i = j

            elif ch.isalpha() or ch == '_':
                j = i + 1
                while j < n and (source[j].isalnum() or source[j] == '_'):
                    j += 1
                word = source[i:j]
                if word in ("and", "or", "not", "in"):
                    tokens.append(Token(word.upper(), word, lineno))
                else:
                    tokens.append(Token("NAME", word, lineno))
                i = j

            elif ch in ("==", "!=", "<", ">", "<=", ">="):
                # Need to check 2-char ops first
                if ch in ("<", ">") and i + 1 < n and source[i+1] == "=":
                    tokens.append(Token("OP", source[i:i+2], lineno))
                    i += 2
                elif ch in ("=", "!") and i + 1 < n and source[i+1] == "=":
                    tokens.append(Token("OP", source[i:i+2], lineno))
                    i += 2
                elif ch in ("<", ">"):
                    tokens.append(Token("OP", ch, lineno))
                    i += 1
                else:
                    # Invalid operator
                    self.error(f"invalid character '{ch}'", lineno)

            elif ch == ".":
                tokens.append(Token("DOT", ".", lineno))
                i += 1

            elif ch == "|":
                tokens.append(Token("PIPE", "|", lineno))
                i += 1

            elif ch == ":":
                tokens.append(Token("COLON", ":", lineno))
                i += 1

            else:
                self.error(f"unexpected character '{ch}'", lineno)

        tokens.append(Token("EOF", "", lineno))
        return tokens

    def _cond_peek(self) -> Token:
        return self.cond_tokens[self.cond_pos]

    def _cond_consume(self) -> Token:
        t = self.cond_tokens[self.cond_pos]
        self.cond_pos += 1
        return t

    def _cond_match(self, kind: str) -> bool:
        if self.cond_peek().kind == kind:
            self._cond_consume()
            return True
        return False

    def _parse_or(self) -> Cond:
        left = self._parse_and()
        while self._cond_peek().kind == "OR":
            self._cond_consume()
            right = self._parse_and()
            left = BoolOp("or", left, right)
        return left

    def _parse_and(self) -> Cond:
        left = self._parse_not()
        while self._cond_peek().kind == "AND":
            self._cond_consume()
            right = self._parse_not()
            left = BoolOp("and", left, right)
        return left

    def _parse_not(self) -> Cond:
        if self._cond_peek().kind == "NOT":
            self._cond_consume()
            operand = self._parse_not()
            return NotOp(operand)
        return self._parse_comparison()

    def _parse_comparison(self) -> Cond:
        left = self._parse_expr_node()
        if self._cond_peek().kind == "OP":
            op_tok = self._cond_consume()
            right = self._parse_expr_node()
            return Compare(left, op_tok.value, right)

        # Check for trailing junk that isn't a keyword?
        # Actually, comparison returns a Cond. 
        # If we are in a bare expression context (which we aren't here, this is condition),
        # a bare Expr is converted to a Cond? 
        # The spec says "A bare value expression is tested with Python truthiness."
        # So if we have `if a`, `a` is an Expr. 
        # But my return type is Cond. 
        # I need a way to wrap Expr as Cond.

        # Let's create a wrapper or just return Expr and have Cast?
        # Or better: Define a Cond subclass that holds an Expr?
        # Or simply: If no operator, return a special Cond node?

        # Let's modify Cond structure:
        # class ExprCond(Cond):
        #    expr: Expr

        # I'll add this class definition above.
        # But since I'm generating code in one go, I need to make sure it's in the final output.

        return ExprCond(left)

    def _parse_expr_node(self) -> Expr:
        # Parses an Atom + Filters using the condition tokens
        atom = self._parse_atom_node()
        filters = []
        while self._cond_peek().kind == "PIPE":
            self._cond_consume()
            # Filter name
            name_tok = self._cond_consume()
            if name_tok.kind != "NAME":
                self.error("expected filter name", name_tok.lineno)
            fname = name_tok.value

            # Argument
            arg = None
            if self._cond_peek().kind == "COLON":
                self._cond_consume()
                arg_tok = self._cond_consume()
                if arg_tok.kind == "STR":
                    arg = arg_tok.value
                elif arg_tok.kind == "INT":
                    arg = int(arg_tok.value)
                else:
                    self.error("invalid filter argument", arg_tok.lineno)

            filters.append(Filter(fname, arg))

        # If base is PathExpr, it's already handled by _parse_atom_node? 
        # No, _parse_atom_node should handle Dot notation.

        return FilterExpr(atom, filters)

    def _parse_atom_node(self) -> Expr:
        tok = self._cond_peek()
        if tok.kind == "STR":
            self._cond_consume()
            return StrLit(tok.value)
        if tok.kind == "INT":
            self._cond_consume()
            return IntLit(int(tok.value))
        if tok.kind == "NAME":
            self._cond_consume()
            if tok.value in RESERVED_WORDS:
                self.error(f"cannot use reserved word '{tok.value}' as name", tok.lineno)

            base = tok.value
            segments = []

            while self._cond_peek().kind == "DOT":
                self._cond_consume()
                seg_tok = self._cond_peek()
                if seg_tok.kind == "NAME":
                    self._cond_consume()
                    if seg_tok.value in RESERVED_WORDS:
                         self.error(f"cannot use reserved word '{seg_tok.value}' as segment", seg_tok.lineno)
                    segments.append(seg_tok.value)
                elif seg_tok.kind == "INT":
                    self._cond_consume()
                    segments.append(int(seg_tok.value))
                else:
                    self.error("invalid segment", seg_tok.lineno)

            return PathExpr(base, segments)

        self.error(f"expected atom, got {tok.kind}", tok.lineno)
        return Node() # unreachable

# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def parse(source: str) -> List[Node]:
    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()

