"""Render engine for the template."""

import typing
import html
import collections.abc

from .lexer import TemplateNotFound, TemplateRenderError, TemplateSyntaxError
from .parser import (
    parse, Node, TextNode, VarNode, ForNode, IfNode, IfBranch,
    FilterExpr, StrLit, IntLit, PathExpr, Filter,
    Cond, BoolOp, NotOp, Compare, SuperExpr,
    ExtendsNode, BlockNode
)


def to_text(value: typing.Any) -> str:
    """Convert value to output text."""
    if value is None:
        return ""
    return str(value)


def _resolve_path(path: PathExpr, context: dict, lineno: int) -> typing.Any:
    """Resolve a variable path in the context."""
    # Base name
    if path.base in context:
        current_val = context[path.base]
    else:
        current_val = None

    for segment in path.segments:
        if current_val is None:
            current_val = None
            continue

        # Handle Mapping
        if isinstance(current_val, collections.abc.Mapping):
            key_str = str(segment)
            if key_str in current_val:
                current_val = current_val[key_str]
            else:
                current_val = None
                continue

        # Handle Sequence (list/tuple)
        elif isinstance(current_val, (list, tuple)):
            if isinstance(segment, int):
                if 0 <= segment < len(current_val):
                    current_val = current_val[segment]
                else:
                    current_val = None
                    continue
            else:
                current_val = None
                continue

        # Handle other objects
        else:
            if isinstance(segment, str):
                if segment.startswith("_"):
                    current_val = None
                    continue
                if hasattr(current_val, segment):
                    current_val = getattr(current_val, segment)
                else:
                    current_val = None
                    continue
            else:
                current_val = None
                continue

    return current_val


def _apply_filters(value: typing.Any, filters: typing.List[Filter], lineno: int) -> typing.Any:
    """Apply a list of filters to a value. Returns (value, last_filter_was_safe_or_escape)."""
    current_val = value

    for f in filters:
        name = f.name
        arg = f.arg

        try:
            if name == "upper":
                current_val = to_text(current_val).upper()
            elif name == "lower":
                current_val = to_text(current_val).lower()
            elif name == "trim":
                current_val = to_text(current_val).strip()
            elif name == "length":
                if current_val is None:
                    current_val = 0
                else:
                    try:
                        current_val = len(current_val)
                    except TypeError:
                        current_val = 0
            elif name == "first":
                if current_val is None:
                    current_val = None
                elif isinstance(current_val, (list, tuple, str)):
                    if len(current_val) > 0:
                        current_val = current_val[0]
                    else:
                        current_val = None
                else:
                    current_val = None
            elif name == "last":
                if current_val is None:
                    current_val = None
                elif isinstance(current_val, (list, tuple, str)):
                    if len(current_val) > 0:
                        current_val = current_val[-1]
                    else:
                        current_val = None
                else:
                    current_val = None
            elif name == "escape":
                current_val = html.escape(to_text(current_val), quote=True)
            elif name == "safe":
                # Returns value unchanged. Autoescaping skip handled in VarNode eval.
                pass
            else:
                raise TemplateRenderError(f"unknown filter: {name}", lineno)

        except TemplateRenderError:
            raise
        except Exception as e:
            raise TemplateRenderError(f"filter error: {e}", lineno)

    return current_val


def _eval_expr(expr: typing.Any, context: dict, lineno: int, autoescape: bool, inheritance_chain=None, current_block_name=None, current_block_level=0) -> tuple[str, bool]:
    """
    Evaluate an expression AST node.
    Returns (text_output, is_safe).
    """
    if isinstance(expr, FilterExpr):
        base_val = _eval_expr(expr.base, context, lineno, autoescape, inheritance_chain, current_block_name, current_block_level)
        # base_val is (text, is_safe) from recursion? No, for FilterExpr base, we usually want raw value.
        # Let's adjust: For Path/Lit, return raw value. For Super, return text/is_safe.

        if isinstance(expr.base, SuperExpr):
             # super() returns rendered text, considered safe (pre-escaped)
             # We need to handle super resolution separately or within this function
             pass 
             # This is getting complex. Let's separate Super logic.

        # Simplified: Evaluate base to raw value first if it's a path/lit
        if isinstance(expr.base, (PathExpr, StrLit, IntLit)):
            if isinstance(expr.base, PathExpr):
                val = _resolve_path(expr.base, context, lineno)
            elif isinstance(expr.base, StrLit):
                val = expr.base.value
            else:
                val = expr.base.value
        else:
            val = _eval_expr(expr.base, context, lineno, autoescape, inheritance_chain, current_block_name, current_block_level)[0]

        final_val, _ = _apply_filters(val, expr.filters, lineno)
        text = to_text(final_val)

        # Check last filter for safe
        is_safe = False
        if expr.filters:
            last_filter = expr.filters[-1].name
            if last_filter == "safe":
                is_safe = True
            elif last_filter == "escape":
                # Already escaped by filter, don't auto-escape again? Spec: "When escape is the last filter, autoescaping does not escape that output a second time."
                # This implies we treat it as safe for autoescaping purposes.
                is_safe = True 

        return text, is_safe

    elif isinstance(expr, (PathExpr, StrLit, IntLit)):
        if isinstance(expr, PathExpr):
            val = _resolve_path(expr, context, lineno)
        elif isinstance(expr, StrLit):
            val = expr.base.value
        else:
            val = expr.base.value
        return to_text(val), False

    elif isinstance(expr, SuperExpr):
        # Resolution of super() is complex and depends on inheritance chain
        # For now, raise error if no chain provided, this is handled in render_nodes typically for VarNode(SuperExpr)
        raise TemplateRenderError("super() called outside block", lineno)

    else:
        # Fallback for other expression types (BoolOp, etc. usually inside If/For, not direct VarNode text)
        return to_text(expr), False


def render_nodes(
    nodes: typing.List[Node], 
    context: dict, 
    output: typing.List[str],
    autoescape: bool = False,
    inheritance_chain: typing.Optional[typing.List['Template']] = None,
    current_block_name: typing.Optional[str] = None,
    current_block_level: int = 0
) -> None:
    """Render a list of nodes into the output buffer."""
    for node in nodes:
        if isinstance(node, TextNode):
            output.append(node.text)

        elif isinstance(node, VarNode):
            expr = node.expr
            text = ""
            is_safe = False

            if isinstance(expr, FilterExpr) and isinstance(expr.base, SuperExpr):
                # Handle super() specifically
                if inheritance_chain is None or current_block_name is None:
                    raise TemplateRenderError("super() used outside block", node.lineno)

                # Find the next definition down the chain
                next_level = current_block_level + 1
                if next_level >= len(inheritance_chain):
                    raise TemplateRenderError("no super() definition available", node.lineno)

                next_template = inheritance_chain[next_level]
                next_block = next_template.blocks.get(current_block_name)

                if next_block is None:
                    # If parent doesn't define block, super() renders nothing? Or error?
                    # Spec: "TemplateRenderError ... when there is no less derived definition"
                    # But if parent doesn't define it, it's just empty?
                    # Usually super() on undefined block is empty string if not strict, or error if strict.
                    # Spec says: "Errors raised by render: TemplateRenderError ... when there is no less derived definition of the block"
                    # This implies if the chain has no more definitions, it's an error.
                    # Wait, "no less derived definition" usually means the current one is the base? 
                    # Let's assume if next_block is None, we look further or error?
                    # If the chain continues but doesn't define the block, we might go deeper?
                    # For simplicity, assume next_level template MUST have it if we are calling super on current block.
                    # If not, error.
                    raise TemplateRenderError("no super() definition available", node.lineno)

                # Render the next block
                block_output: typing.List[str] = []
                # Recursively render the next block's nodes, passing the chain and incremented level
                # But wait, the block content of the parent is just nodes. 
                # We need to render those nodes. 
                # However, if the parent's block contains `super()`, it needs to find the *next* one.
                # So we pass `current_block_level + 1` to the recursive call.
                render_nodes(
                    next_block, 
                    context, 
                    block_output, 
                    autoescape, 
                    inheritance_chain, 
                    current_block_name, 
                    next_level
                )
                text = "".join(block_output)
                is_safe = True # super output is pre-rendered/escaped

            else:
                text, is_safe = _eval_expr(expr, context, node.lineno, autoescape, inheritance_chain, current_block_name, current_block_level)

            if autoescape and not is_safe:
                output.append(html.escape(text, quote=True))
            else:
                output.append(text)

        elif isinstance(node, ForNode):
            iterable = _resolve_path(node.expr, context, node.lineno) if isinstance(node.expr, PathExpr) else _eval_expr(node.expr, context, node.lineno, autoescape)[0]
            if iterable is None:
                iterable = []

            for item in iterable:
                child_context = context.copy()
                child_context[node.loop_var] = item
                render_nodes(node.body, child_context, output, autoescape, inheritance_chain, current_block_name, current_block_level)

        elif isinstance(node, IfNode):
            cond_val = _eval_expr(node.cond, context, node.lineno, autoescape)[0]
            # Truthiness check
            if cond_val:
                render_nodes(node.body, context, output, autoescape, inheritance_chain, current_block_name, current_block_level)
            else:
                if node.else_body:
                    render_nodes(node.else_body, context, output, autoescape, inheritance_chain, current_block_name, current_block_level)

        elif isinstance(node, BlockNode):
            # In a template that does not extend another, a block simply renders its contents in place.
            # If it extends, the block logic is handled at the Template level before calling render_nodes on the root nodes? 
            # Actually, if we are rendering a template directly (no extends), BlockNodes are rendered here.
            # If we are rendering a parent (because of extends), the parent's BlockNodes are replaced by child's.
            # This replacement happens in Template.render.
            # So here, if we hit a BlockNode, it means we are rendering the template's own body.
            # If the template extends, the Template.render method would have already swapped the nodes or handled it.
            # But `extends` templates usually just have blocks and no direct output outside blocks? 
            # "Everything in the child outside its blocks is ignored when rendering".
            # So for a child template, we don't render its root nodes normally, we render the parent.
            # This implies Template.render handles the swapping.
            # Here, if we are in render_nodes, we are likely rendering the resolved final body (possibly parent's body with child blocks injected).
            # So BlockNode inside render_nodes should probably be ignored or rendered if it's a base template without extends?
            # If it's a base template without extends, it renders the block's content.
            # If it's part of a chain, the node injection already happened.
            # To be safe, if we encounter a BlockNode here, it means it's a base template rendering directly.
            render_nodes(node.body, context, output, autoescape, inheritance_chain, node.name, current_block_level)


class DictLoader:
    def __init__(self, templates: typing.Dict[str, str]):
        self.templates = templates

    def get_source(self, name: str) -> str:
        if name in self.templates:
            return self.templates[name]
        raise TemplateNotFound(name)


class Template:
    def __init__(self, source: str, *, loader=None, autoescape: bool = False, name: typing.Optional[str] = None):
        self.source = source
        self.loader = loader
        self.autoescape = autoescape
        self.name = name
        self.ast = parse(source, name=name)

        # Identify extends and blocks
        self.extends_name: typing.Optional[str] = None
        self.blocks: typing.Dict[str, typing.List[Node]] = {}
        self._analyze_ast(self.ast)

    def _analyze_ast(self, nodes: typing.List[Node]):
        """Find extends and blocks in the template."""
        if not isinstance(nodes, list):
            nodes = [nodes] if isinstance(nodes, Node) else []

        for node in nodes:
            if isinstance(node, ExtendsNode):
                if self.extends_name is not None:
                     # Extends must be first tag. If we find multiple or late, it's syntax error in parse? 
                     # Parser likely handles "must be first". 
                     self.extends_name = node.name
                else:
                    self.extends_name = node.name
            elif isinstance(node, BlockNode):
                self.blocks[node.name] = node.body
            elif isinstance(node, ForNode):
                self._analyze_ast(node.body)
            elif isinstance(node, IfNode):
                self._analyze_ast(node.body)
                if node.else_body:
                    self._analyze_ast(node.else_body)

    def render(self, **context) -> str:
        # Determine inheritance chain
        chain: typing.List[Template] = [self]
        loaded_names = {self.name} if self.name else set()

        current_template = self
        while current_template.extends_name:
            if not current_template.loader:
                raise TemplateNotFound(current_template.extends_name)

            parent_source = current_template.loader.get_source(current_template.extends_name)
            # Create parent template. Inherit autoescape? Spec: "The whole render ... uses the autoescape setting of the template whose render was called."
            # But the chain construction uses the *loader* of the rendering template.

            # Check for loops
            if current_template.extends_name in loaded_names:
                raise TemplateRenderError(f"Circular inheritance detected: {current_template.extends_name}", self.ast[0].lineno if self.ast else 0)

            parent_template = Template(
                parent_source, 
                loader=self.loader, 
                autoescape=self.autoescape, 
                name=current_template.extends_name
            )

            # Inject child blocks into parent's AST logic? 
            # Instead of mutating, we resolve blocks at render time.

            chain.append(parent_template)
            loaded_names.add(current_template.extends_name)
            current_template = parent_template

        # The final root is the most derived base (the last one in chain, which has no extends)
        # Or the root is the base template's AST.

        # Render the root template (the one without extends) 
        root_template = chain[-1]

        # To handle block replacement, we can either:
        # 1. Copy root AST and replace BlockNodes with child blocks.
        # 2. Pass chain context to render_nodes so it knows how to resolve super() and block content.

        # Approach 2 is more dynamic. render_nodes needs to know:
        # - current_block_name (if inside one)
        # - current_block_level (index in chain)
        # - chain (list of templates)

        # However, if the child template defines a block, and we are rendering the parent (root), 
        # when we hit a BlockNode in the root, we must check if the child (chain[0] or intermediate) defines it.
        # "every block in the parent is replaced by the child's block of the same name if the child has one."
        # "A child's block whose name the parent never renders is not output."

        # So, when rendering root's nodes:
        # If we encounter BlockNode(name):
        #   1. Find the most derived template in `chain` that defines this block.
        #   2. Render that block's body.
        #   3. Inside that body, if `super()` is called, it goes to the next definition down.

        output: typing.List[str] = []

        # We need a modified render_nodes or a wrapper that handles block resolution.
        # Let's implement a helper that renders the specific body of a block found in the chain.

        # But root's non-block content must also be rendered.
        # And root's blocks are replaced.

        def render_template_body(template: Template, block_overrides: typing.Dict[str, int], is_root: bool):
            # This is getting complicated. Standard approach:
            # 1. Collect all blocks from chain: {name: [template_indices]}
            # 2. Render root AST. 
            # 3. When hitting BlockNode(name), lookup the highest priority definition in chain.

            pass

        # Simpler approach for the implementation:
        # The `chain` is ordered: [child, parent, grandparent, ..., root]
        # When rendering `root`'s AST:
        # If BlockNode `name` is found:
        #   Find the first template in `chain` that has `name` in its blocks. 
        #   Since chain is ordered child->root, the first one found is the most derived.
        #   Render THAT block's body.
        #   Inside that body, we set `current_block_name=name` and `current_block_level=index_of_that_template_in_chain`.

        # Wait, `chain` is [self, parent, ..., root]. 
        # If `self` defines block X, and `parent` defines block X. 
        # `chain` = [self, parent, ...]. 
        # When rendering root, we hit BlockNode X. 
        # We check chain[0] (self) -> has it? Yes. Use it.
        # `current_block_level` = 0.
        # Inside this block, if `super()` is called, it looks at `chain[1]` (parent).
        # This works perfectly.

        # Non-block content of Root is rendered as is.
        # Non-block content of Child/Intermediate templates is IGNORED (as per spec: "Everything in the child outside its blocks is ignored"). 
        # BUT, if we are rendering the root, the root's non-block content IS rendered.
        # The child's non-block content is never rendered because we only render the root's AST.

        render_nodes(
            root_template.ast, 
            context, 
            output, 
            self.autoescape, 
            chain=chain, 
            current_block_name=None, 
            current_block_level=0 # Root level
        )

        # Correction on render_nodes BlockNode handling:
        # The logic in `render_nodes` I wrote earlier just rendered `node.body`. 
        # I need to update `render_nodes` to perform the lookup in `chain`.

        return "".join(output)


class Environment:
    def __init__(self, loader=None, autoescape: bool = False):
        self.loader = loader
        self.autoescape = autoescape
        self._cache: typing.Dict[str, Template] = {}

    def get_template(self, name: str) -> Template:
        if name in self._cache:
            return self._cache[name]

        if not self.loader:
            raise TemplateNotFound(name)

        source = self.loader.get_source(name)
        tmpl = Template(source, loader=self.loader, autoescape=self.autoescape, name=name)
        self._cache[name] = tmpl
        return tmpl

    def from_string(self, source: str) -> Template:
        return Template(source, loader=self.loader, autoescape=self.autoescape, name=None)
