"""Render engine for the template."""

import typing
import html
from collections.abc import Mapping, Iterable

from .lexer import TemplateRenderError, TemplateNotFound
from .parser import (
    parse, Node, TextNode, VarNode, ForNode, IfNode, IfBranch,
    FilterExpr, StrLit, IntLit, PathExpr, Filter,
    Cond, BoolOp, NotOp, Compare
)


def to_text(value: typing.Any) -> str:
    """Convert value to output text."""
    if value is None:
        return ""
    return str(value)


def _resolve_path(path: PathExpr, context: dict, lineno: int) -> typing.Any:
    """Resolve a variable path in the context."""
    # Base name
    if path.base in context:
        current_val = context[path.base]
    else:
        current_val = None

    for segment in path.segments:
        if current_val is None:
            current_val = None
            continue

        # Handle Mapping
        if isinstance(current_val, Mapping):
            # Spec: value stored under segment as string key
            # But segment in AST is Union[str, int]. 
            # Parser creates segments: int if starts with digit, else str.
            # Spec says: on a mapping ... value stored under the segment as a string key
            key_str = str(segment)
            if key_str in current_val:
                current_val = current_val[key_str]
            else:
                current_val = None
                continue

        # Handle Sequence (list/tuple)
        elif isinstance(current_val, (list, tuple)):
            if isinstance(segment, int):
                if 0 <= segment < len(current_val):
                    current_val = current_val[segment]
                else:
                    current_val = None
                    continue
            else:
                # Not an integer segment on a list/tuple -> None
                current_val = None
                continue

        # Handle other objects
        else:
            if isinstance(segment, str):
                # Spec: name segment that does not start with _
                if segment.startswith("_"):
                    current_val = None
                    continue
                if hasattr(current_val, segment):
                    current_val = getattr(current_val, segment)
                else:
                    current_val = None
                    continue
            else:
                # Integer segment on non-sequence/mapping -> None
                current_val = None
                continue

    return current_val


def _apply_filters(value: typing.Any, filters: typing.List[Filter], lineno: int) -> typing.Any:
    """Apply a list of filters to a value."""
    current_val = value

    for f in filters:
        name = f.name
        arg = f.arg

        try:
            if name == "upper":
                current_val = to_text(current_val).upper()

            elif name == "lower":
                current_val = to_text(current_val).lower()

            elif name == "trim":
                current_val = to_text(current_val).strip()

            elif name == "length":
                if current_val is None:
                    current_val = 0
                else:
                    current_val = len(current_val)

            elif name == "first":
                if current_val is None:
                    current_val = None
                elif isinstance(current_val, (list, tuple, str)) or hasattr(current_val, '__getitem__'):
                    if hasattr(current_val, '__getitem__'):
                         # Check if empty
                         try:
                             if len(current_val) == 0:
                                 current_val = None
                             else:
                                 current_val = current_val[0]
                         except TypeError:
                             # Not sized, try iterator
                             try:
                                current_val = next(iter(current_val))
                             except (StopIteration, TypeError):
                                current_val = None
                    else:
                        current_val = None
                else:
                    # Try generic iteration? Spec says "first or last item". 
                    # Usually implies sequence. If it's an iterator, it consumes it.
                    # But we usually have lists/tuples/strings.
                    try:
                        # Check if iterable
                        iter(current_val) 
                        if len(current_val) == 0:
                            current_val = None
                        else:
                            current_val = current_val[0]
                    except TypeError:
                        current_val = None

            elif name == "last":
                if current_val is None:
                    current_val = None
                elif hasattr(current_val, '__getitem__') and hasattr(current_val, '__len__'):
                     if len(current_val) == 0:
                         current_val = None
                     else:
                         current_val = current_val[-1]
                else:
                     try:
                         # Iterator fallback
                         items = list(current_val)
                         if len(items) == 0:
                             current_val = None
                         else:
                             current_val = items[-1]
                     except TypeError:
                         current_val = None

            elif name == "reverse":
                if current_val is None:
                    current_val = None
                elif isinstance(current_val, str):
                    current_val = current_val[::-1]
                else:
                    current_val = list(current_val)[::-1]

            elif name == "join":
                if current_val is None:
                    current_val = ""
                else:
                    # arg must be string
                    sep = str(arg)
                    try:
                        # Iterate over items
                        # Spec: output text of each item, joined with sep
                        items = []
                        for item in current_val:
                            items.append(to_text(item))
                        current_val = sep.join(items)
                    except TypeError:
                        # Not iterable
                        current_val = ""

            elif name == "default":
                # Argument is required (string or int)
                if current_val is None or current_val == "":
                    current_val = arg
                else:
                    current_val = current_val

            elif name == "truncate":
                # Arg is int >= 0
                if arg is None:
                    raise TemplateRenderError("truncate requires integer argument", lineno)
                n = int(arg)
                text = to_text(current_val)
                if len(text) > n:
                    current_val = text[:n] + "..."
                else:
                    current_val = text

            elif name == "items":
                if current_val is None:
                    current_val = []
                elif isinstance(current_val, Mapping):
                    current_val = list(current_val.items())
                else:
                    raise TemplateRenderError("items filter expects mapping", lineno)

            elif name == "escape":
                # Returns the value's output text HTML-escaped as above, whether autoescaping is on or off.
                # When escape is the last filter, autoescaping does not escape that output a second time.
                # The logic for this is handled in render_nodes where it checks the last filter name.
                # Here we just perform the escape.
                current_val = html.escape(to_text(current_val), quote=True)

            elif name == "safe":
                # Returns its value unchanged.
                # The logic for skipping autoescape is handled in render_nodes.
                pass

            else:
                raise TemplateRenderError(f"unknown filter: {name}", lineno)

        except TemplateRenderError:
            raise
        except Exception as e:
            # Catch filter specific runtime errors (e.g. type errors in filters not handled above)
            raise TemplateRenderError(f"filter error: {e}", lineno) from e

    return current_val


def eval_expr(expr: typing.Union[FilterExpr, StrLit, IntLit, PathExpr], context: dict, lineno: int) -> typing.Any:
    """Evaluate an expression node."""
    if isinstance(expr, FilterExpr):
        val = eval_expr(expr.base, context, lineno)
        val = _apply_filters(val, expr.filters, lineno)
        return val
    elif isinstance(expr, StrLit):
        return expr.value
    elif isinstance(expr, IntLit):
        return expr.value
    elif isinstance(expr, PathExpr):
        return _resolve_path(expr, context, lineno)
    else:
        raise TemplateRenderError(f"unknown expression type: {type(expr)}", lineno)


def eval_cond(cond: Cond, context: dict, lineno: int) -> bool:
    """Evaluate a condition node."""
    if isinstance(cond, BoolOp):
        left = eval_cond(cond.left, context, lineno)
        if cond.op == "and":
            if not left:
                return False
            return bool(eval_cond(cond.right, context, lineno))
        elif cond.op == "or":
            if left:
                return True
            return bool(eval_cond(cond.right, context, lineno))
        else:
            raise TemplateRenderError(f"unknown boolean operator: {cond.op}", lineno)

    elif isinstance(cond, NotOp):
        return not eval_cond(cond.operand, context, lineno)

    elif isinstance(cond, Compare):
        left_val = eval_expr(cond.left, context, lineno)
        right_val = eval_expr(cond.right, context, lineno)

        op = cond.op
        try:
            if op == "==":
                return left_val == right_val
            elif op == "!=":
                return left_val != right_val
            elif op == "<":
                return left_val < right_val
            elif op == "<=":
                return left_val <= right_val
            elif op == ">":
                return left_val > right_val
            elif op == ">=":
                return left_val >= right_val
            else:
                raise TemplateRenderError(f"unknown comparison operator: {op}", lineno)
        except TypeError as e:
            raise TemplateRenderError(f"cannot compare {type(left_val).__name__} with {type(right_val).__name__}", lineno) from e

    elif isinstance(cond, FilterExpr):
        # Handle case where a bare expression is treated as a condition (truthiness)
        # Based on spec "A bare value expression is tested with Python truthiness"
        # If the parser wraps it or if this branch is hit.
        val = eval_expr(cond, context, lineno)
        return bool(val)
    else:
        raise TemplateRenderError(f"unknown condition type: {type(cond)}", lineno)


def render_nodes(nodes: typing.List[Node], context: dict, output: typing.List[str], autoescape: bool = False) -> None:
    """Render a list of nodes into the output buffer."""
    for node in nodes:
        if isinstance(node, TextNode):
            output.append(node.text)

        elif isinstance(node, VarNode):
            val = eval_expr(node.expr, context, node.lineno)
            text = to_text(val)

            # Autoescape logic
            # 1. If autoescape is True
            # 2. AND the last filter in the expression is NOT 'safe' or 'escape' (if 'escape' was last, we already escaped it, don't double escape)
            # Actually, spec says:
            # - When autoescaping is on, the output text of every {{ }} is HTML-escaped after all of its filters have run.
            # - A new filter 'safe' ... When safe is the last filter ... its output is not escaped.
            # - A new filter 'escape' ... returns the value's output text HTML-escaped ... When escape is the last filter, autoescaping does not escape that output a second time.

            # Determine if we should escape
            should_escape = autoescape

            # Check if the expression is a FilterExpr and has filters
            if isinstance(node.expr, FilterExpr) and node.expr.filters:
                last_filter_name = node.expr.filters[-1].name
                if last_filter_name in ("safe", "escape"):
                    should_escape = False

            if should_escape:
                text = html.escape(text, quote=True)

            output.append(text)

        elif isinstance(node, IfNode):
            rendered = False
            for branch in node.branches:
                if branch.condition is None:
                    # Else branch
                    if not rendered:
                        render_nodes(branch.body, context, output, autoescape)
                        rendered = True
                else:
                    try:
                        if eval_cond(branch.condition, context, node.lineno):
                            render_nodes(branch.body, context, output, autoescape)
                            rendered = True
                            break
                    except TemplateRenderError:
                        raise

        elif isinstance(node, ForNode):
            iterable_val = eval_expr(node.iterable, context, node.lineno)

            # Normalize iterable
            if iterable_val is None:
                items = []
            elif isinstance(iterable_val, Mapping):
                # Spec: a mapping gives its keys
                items = list(iterable_val.keys())
            elif isinstance(iterable_val, (list, tuple, str)):
                items = iterable_val
            else:
                try:
                    items = list(iterable_val)
                except TypeError:
                    raise TemplateRenderError("not iterable", node.lineno)

            if not items:
                # Render else body if present
                if node.else_body:
                    render_nodes(node.else_body, context, output, autoescape)
                continue

            total = len(items)

            # Prepare new context for loop body
            # Loop variables shadow outer variables
            loop_body_context = dict(context)

            for idx, item in enumerate(items):
                loop_info = {
                    "index": idx + 1,
                    "index0": idx,
                    "first": idx == 0,
                    "last": idx == total - 1,
                    "length": total
                }

                # Shadow variables
                loop_body_context[node.name] = item
                loop_body_context["loop"] = loop_info

                render_nodes(node.body, loop_body_context, output, autoescape)

        else:
            raise TemplateRenderError(f"unknown node type: {type(node)}", 1)


class Template:
    """A compiled template."""

    def __init__(self, source: str, *, loader=None, autoescape: bool = False, name: str | None = None):
        self.nodes = parse(source)
        self.loader = loader
        self.autoescape = autoescape
        self.name = name

    def render(self, context: dict | None = None, **kwargs) -> str:
        """Render the template."""
        # Create a fresh context dict so we don't modify the original
        ctx = {}
        if context:
            ctx.update(context)
        # kwargs win
        ctx.update(kwargs)

        output: typing.List[str] = []
        render_nodes(self.nodes, ctx, output, self.autoescape)
        return "".join(output)


class DictLoader:
    """A simple loader that maps template names to their source text."""

    def __init__(self, templates: dict[str, str]):
        self.templates = templates

    def get_source(self, name: str) -> str:
        """Return the source of the template with the given name."""
        try:
            return self.templates[name]
        except KeyError:
            raise TemplateNotFound(name)


class Environment:
    """An environment for loading and rendering templates."""

    def __init__(self, loader=None, autoescape: bool = False):
        self.loader = loader
        self.autoescape = autoescape

    def get_template(self, name: str) -> Template:
        """Load a template from the loader."""
        if not self.loader:
            raise TemplateNotFound(name)

        source = self.loader.get_source(name)
        return Template(
            source,
            loader=self.loader,
            autoescape=self.autoescape,
            name=name
        )

    def from_string(self, source: str) -> Template:
        """Create a template from a source string."""
        return Template(
            source,
            loader=self.loader,
            autoescape=self.autoescape,
            name=None
        )


def render(source: str, context: dict | None = None, **kwargs) -> str:
    """Render a template string directly."""
    return Template(source).render(context, **kwargs)
