"""Parser for the template engine."""

from __future__ import annotations
import dataclasses
import re
from typing import Union, Optional, Any, List
from .lexer import tokenize, Token, TemplateSyntaxError

# ---------------------------------------------------------------------------
# AST Nodes
# ---------------------------------------------------------------------------

@dataclasses.dataclass
class Node:
    pass

@dataclasses.dataclass
class TextNode(Node):
    text: str

# Expressions
@dataclasses.dataclass
class Expr:
    pass

@dataclasses.dataclass
class StrLit(Expr):
    value: str

@dataclasses.dataclass
class IntLit(Expr):
    value: int

@dataclasses.dataclass
class PathExpr(Expr):
    base: str
    segments: List[Union[str, int]]

@dataclasses.dataclass
class SuperExpr(Expr):
    pass

@dataclasses.dataclass
class Filter:
    name: str
    arg: Union[str, int, None] = None

@dataclasses.dataclass
class FilterExpr(Expr):
    base: Expr
    filters: List[Filter] = dataclasses.field(default_factory=list)

# Conditions
@dataclasses.dataclass
class Cond:
    pass

@dataclasses.dataclass
class ExprCond(Cond):
    expr: Expr

@dataclasses.dataclass
class BoolOp(Cond):
    op: str  # "and", "or"
    left: Cond
    right: Cond

@dataclasses.dataclass
class NotOp(Cond):
    operand: Cond

@dataclasses.dataclass
class Compare(Cond):
    left: Expr
    op: str
    right: Expr

# Statements
@dataclasses.dataclass
class VarNode(Node):
    lineno: int
    expr: FilterExpr

@dataclasses.dataclass
class IfBranch:
    condition: Optional[Cond]  # None for else branch
    body: List[Node]

@dataclasses.dataclass
class IfNode(Node):
    lineno: int
    branches: List[IfBranch]

@dataclasses.dataclass
class ForNode(Node):
    lineno: int
    name: str
    iterable: FilterExpr
    body: List[Node]
    else_body: List[Node]  # Empty list if no else

@dataclasses.dataclass
class ExtendsNode(Node):
    name: str
    lineno: int

@dataclasses.dataclass
class BlockNode(Node):
    name: str
    body: List[Node]
    lineno: int

# ---------------------------------------------------------------------------
# Parser Helper Classes / Constants
# ---------------------------------------------------------------------------

RESERVED_WORDS = {"and", "or", "not", "in", "super"}
COMPARISON_OPS = {"==", "!=", "<", "<=", ">", ">="}

FILTERS_WITHOUT_ARGS = {"upper", "lower", "trim", "length", "first", "last", "reverse", "items"}
FILTERS_WITH_STRING_ARG = {"join"}
FILTERS_WITH_INT_ARG = {"truncate", "default"} # default can be string or int
FILTERS_WITH_STR_OR_INT_ARG = {"default"}

# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0
        self.block_stack: List[str] = [] # Tracks open block names
        self.extends_seen = False

    def error(self, msg: str, lineno: int) -> None:
        raise TemplateSyntaxError(msg, lineno)

    def peek(self) -> Optional[Token]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self) -> Token:
        tok = self.peek()
        if tok is None:
            raise TemplateSyntaxError("unexpected end of template", self._current_lineno())
        self.pos += 1
        return tok

    def _current_lineno(self) -> int:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos].lineno
        if self.tokens:
            return self.tokens[-1].lineno
        return 1

    def parse(self) -> List[Node]:
        nodes = self.parse_body()
        if self.pos != len(self.tokens):
            # Should not happen if parse_body handles all tokens
            pass 
        return nodes

    def parse_body(self, end_keywords: List[str] | None = None) -> List[Node]:
        nodes: List[Node] = []
        while True:
            tok = self.peek()
            if tok is None:
                break

            if tok.kind == "block":
                # Check if it's a closing keyword
                # The value is stripped
                parts = tok.value.split()
                if not parts:
                    self.error("empty block", tok.lineno)
                first_word = parts[0]

                if end_keywords and first_word in end_keywords:
                    break

                # Parse statement
                node = self.parse_block(tok, nodes)
                if node is not None:
                    nodes.append(node)
            elif tok.kind == "var":
                node = self.parse_var(tok)
                nodes.append(node)
            elif tok.kind == "text":
                nodes.append(TextNode(tok.value))
                self.consume()
            else:
                self.error(f"unexpected token kind: {tok.kind}", tok.lineno)

        return nodes

    def parse_var(self, tok: Token) -> VarNode:
        self.consume() # consume the var token
        expr = self.parse_value_expression(tok.value, tok.lineno)

        # Check for super() usage
        self._check_super_in_block(tok.lineno, expr)

        return VarNode(tok.lineno, expr)

    def _check_super_in_block(self, lineno: int, expr: FilterExpr) -> None:
        # Recursively check if SuperExpr is present
        def check(node):
            if isinstance(node, SuperExpr):
                return True
            if isinstance(node, FilterExpr):
                if check(node.base):
                    return True
                for f in node.filters:
                    pass # Filters don't contain expressions in this simple model, args are literals
            return False

        if isinstance(expr.base, SuperExpr):
            if not self.block_stack:
                self.error("super() used outside of a block", lineno)

    def parse_block(self, tok: Token, preceding_nodes: List[Node]) -> Optional[Node]:
        self.consume() # consume the block token
        value = tok.value
        lineno = tok.lineno

        if not value:
            self.error("empty block", lineno)

        parts = value.split()
        keyword = parts[0]

        if keyword == "for":
            return self.parse_for(value, parts, lineno)
        elif keyword == "if":
            return self.parse_if(value, parts, lineno)
        elif keyword == "extends":
            return self.parse_extends(parts, lineno, preceding_nodes)
        elif keyword == "block":
            return self.parse_block_start(parts, lineno)
        elif keyword == "endblock":
            # This should have been caught by end_keywords in parse_body if we are in a block body
            # If we are here, it means we are at the top level or mismatched
            if not self.block_stack:
                self.error("endblock without a matching block", lineno)
            # If it's here, it means we didn't stop at it, which is a logic error in parse_body
            # But let's handle it gracefully just in case
            expected_name = self.block_stack.pop()
            if len(parts) > 1:
                name = parts[1]
                if name != expected_name:
                    self.error(f"endblock name '{name}' does not match block '{expected_name}'", lineno)
            return None
        else:
            self.error(f"unknown statement: {keyword}", lineno)
            return None

    def parse_extends(self, parts: List[str], lineno: int, preceding_nodes: List[Node]) -> ExtendsNode:
        if self.extends_seen:
            self.error("multiple extends tags", lineno)

        # Check that only whitespace/text precedes it
        for node in preceding_nodes:
            if isinstance(node, TextNode):
                if node.text.strip():
                    self.error("extends must be the first tag", lineno)
            elif isinstance(node, Node):
                self.error("extends must be the first tag", lineno)

        if len(parts) != 2:
            self.error("malformed extends statement", lineno)

        name_val = parts[1]
        if not (name_val.startswith('"') and name_val.endswith('"')) and not (name_val.startswith("'") and name_val.endswith("'")):
             self.error("extends argument must be a quoted string", lineno)

        name = name_val[1:-1]
        if not name:
            self.error("empty template name in extends", lineno)

        self.extends_seen = True
        return ExtendsNode(name, lineno)

    def parse_block_start(self, parts: List[str], lineno: int) -> BlockNode:
        if len(parts) < 2:
            self.error("block missing name", lineno)

        name = parts[1]

        # Validate name
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
             self.error(f"invalid block name: {name}", lineno)

        # Check for duplicates? 
        # "a second block with the same name in one template" -> SyntaxError at block tag line.
        # We don't have a global view of all blocks easily without two passes or storing them.
        # However, `parse_block_start` is called sequentially.
        # We can maintain a set of seen block names in the Parser instance for the current template.
        if not hasattr(self, 'seen_blocks'):
            self.seen_blocks = set()

        if name in self.seen_blocks:
            self.error(f"duplicate block name: {name}", lineno)

        self.seen_blocks.add(name)

        # Start block context
        self.block_stack.append(name)

        # Parse body until endblock
        # We pass "endblock" as the end keyword
        body_nodes = self.parse_body(end_keywords=["endblock"])

        # We are now at the endblock token
        end_tok = self.peek()
        if end_tok is None:
            self.error("unclosed block", lineno)

        # Consume endblock
        self.consume()
        end_parts = end_tok.value.split()

        # Validate endblock name matches
        # "an endblock with a name different from the block it closes" -> Error at endblock line
        if len(end_parts) > 1:
            end_name = end_parts[1]
            if end_name != name:
                self.error(f"endblock name '{end_name}' does not match block '{name}'", end_tok.lineno)

        self.block_stack.pop()

        return BlockNode(name, body_nodes, lineno)

    def parse_for(self, value: str, parts: List[str], lineno: int) -> ForNode:
        # Syntax: {% for NAME in EXPR %}
        # parts = ["for", "name", "in", "expr..."]
        if len(parts) < 4 or parts[2] != "in":
            self.error("malformed for statement", lineno)

        name = parts[1]
        if name in RESERVED_WORDS:
            self.error(f"cannot use reserved word '{name}' as loop variable", lineno)

        expr_str = " ".join(parts[3:])
        if not expr_str:
            self.error("missing iterable in for statement", lineno)

        iterable_expr = self.parse_value_expression(expr_str, lineno)

        # Parse body until endfor
        body_nodes = self.parse_body(end_keywords=["endfor", "else"])

        next_tok = self.peek()
        if next_tok is None:
            self.error("unclosed for", lineno)

        if next_tok.kind != "block":
            self.error("expected endfor or else", next_tok.lineno)

        next_parts = next_tok.value.split()
        if not next_parts:
             self.error("empty block", next_tok.lineno)

        next_kw = next_parts[0]

        else_body: List[Node] = []

        if next_kw == "else":
            self.consume() # consume else
            # Parse until endfor
            else_body = self.parse_body(end_keywords=["endfor"])
            next_tok = self.peek()
            if next_tok is None or next_tok.kind != "block" or next_tok.value.split()[0] != "endfor":
                self.error("expected endfor", next_tok.lineno if next_tok else lineno)
        elif next_kw == "endfor":
            pass
        else:
            self.error(f"unexpected block in for: {next_kw}", next_tok.lineno)

        # Consume endfor
        endfor_tok = self.consume()
        if endfor_tok.value != "endfor":
            self.error("expected endfor", endfor_tok.lineno)

        return ForNode(lineno, name, iterable_expr, body_nodes, else_body)

    def parse_if(self, value: str, parts: List[str], lineno: int) -> IfNode:
        # Syntax: {% if COND %}...{% elif COND %}...{% else %}...{% endif %}

        if len(parts) <= 1:
            self.error("missing condition in if", lineno)

        cond_str = " ".join(parts[1:])
        condition = self.parse_condition(cond_str, lineno)

        branches: List[IfBranch] = []

        body = self.parse_body(end_keywords=["elif", "else", "endif"])
        branches.append(IfBranch(condition, body))

        has_else = False

        while True:
            tok = self.peek()
            if tok is None:
                self.error("unclosed if", lineno)

            if tok.kind != "block":
                self.error("expected block", tok.lineno)

            block_parts = tok.value.split()
            if not block_parts:
                self.error("empty block", tok.lineno)

            kw = block_parts[0]

            if kw == "elif":
                if has_else:
                    self.error("elif after else", tok.lineno)

                if len(block_parts) <= 1:
                    self.error("missing condition in elif", tok.lineno)

                self.consume() 
                elif_cond_str = " ".join(block_parts[1:])
                elif_cond = self.parse_condition(elif_cond_str, tok.lineno)

                elif_body = self.parse_body(end_keywords=["elif", "else", "endif"])
                branches.append(IfBranch(elif_cond, elif_body))

            elif kw == "else":
                if has_else:
                    self.error("duplicate else", tok.lineno)

                if len(block_parts) > 1:
                    self.error("unexpected token after else", tok.lineno)

                self.consume() 
                has_else = True
                else_body = self.parse_body(end_keywords=["endif"])
                branches.append(IfBranch(None, else_body))

            elif kw == "endif":
                self.consume() 
                break
            else:
                self.error(f"unexpected block in if: {kw}", tok.lineno)

        return IfNode(lineno, branches)

    # -----------------------------------------------------------------------
    # Expression Parsing
    # -----------------------------------------------------------------------

    def parse_value_expression(self, source: str, lineno: int) -> FilterExpr:
        return self._parse_expr_from_string(source, lineno)

    def _parse_expr_from_string(self, source: str, lineno: int) -> FilterExpr:
        expr = FilterExpr(base=None, filters=[])

        remaining = source.strip()
        if not remaining:
            self.error("empty expression", lineno)

        atom, remaining = self._parse_atom_string(remaining, lineno)
        expr.base = atom

        while remaining:
            remaining = remaining.strip()
            if not remaining:
                break

            if not remaining.startswith("|"):
                self.error(f"unexpected characters in expression: {remaining}", lineno)

            remaining = remaining[1:].strip()

            name = self._read_name(remaining, lineno)
            if not name:
                 self.error("expected filter name", lineno)

            remaining = remaining[len(name):].strip()

            arg = None
            if remaining.startswith(":"):
                remaining = remaining[1:].strip()
                arg, remaining = self._parse_filter_arg(remaining, lineno)

            elif remaining and not remaining.startswith("|"):
                 self.error(f"unexpected text after filter: {remaining}", lineno)

            expr.filters.append(Filter(name, arg))

        return expr

    def _read_name(self, source: str, lineno: int) -> str:
        if not source or not (source[0].isalpha() or source[0] == '_'):
            return ""
        i = 0
        while i < len(source) and (source[i].isalnum() or source[i] == '_'):
            i += 1
        return source[:i]

    def _parse_filter_arg(self, source: str, lineno: int) -> tuple[Union[str, int, None], str]:
        source = source.strip()
        if not source:
            return None, ""

        if source[0] in ('"', "'"):
            quote = source[0]
            i = 1
            while i < len(source) and source[i] != quote:
                i += 1
            if i >= len(source):
                self.error("unterminated string", lineno)
            val = source[1:i]
            return val, source[i+1:]

        if source[0].isdigit() or (source[0] == '-' and len(source) > 1 and source[1].isdigit()):
            i = 1 if source[0] == '-' else 0
            while i < len(source) and source[i].isdigit():
                i += 1
            val_str = source[:i]
            return int(val_str), source[i:]

        return None, source

    def _parse_atom_string(self, source: str, lineno: int) -> tuple[Expr, str]:
        source = source.strip()
        if not source:
            self.error("expected atom", lineno)

        # Special case: super()
        if source.startswith("super"):
            # Check if it is followed by optional whitespace and parens
            rest = source[5:].strip()
            if rest.startswith("("):
                 rest = rest[1:].strip()
                 if rest.startswith(")"):
                     rest = rest[1:].strip()
                     return SuperExpr(), rest
            # If not super(), it's likely a variable named super (if allowed) or error.
            # But super is reserved. So if it starts with "super" but isn't "super()", it's invalid 
            # as a path expression because it's a reserved word.
            # Actually, if source is "super", it's a name. _read_name will get it.
            # Then it will fail the reserved word check in PathExpr creation.

        if source[0] in ('"', "'"):
            quote = source[0]
            i = 1
            while i < len(source) and source[i] != quote:
                i += 1
            if i >= len(source):
                self.error("unterminated string", lineno)
            val = source[1:i]
            return StrLit(val), source[i+1:]

        if source[0].isdigit() or (source[0] == '-' and len(source) > 1 and source[1].isdigit()):
            i = 1 if source[0] == '-' else 0
            while i < len(source) and source[i].isdigit():
                i += 1
            val_str = source[:i]
            return IntLit(int(val_str)), source[i:]

        name = self._read_name(source, lineno)
        if not name:
            self.error(f"invalid atom: {source[:10]}", lineno)

        if name in RESERVED_WORDS:
            # If it's a reserved word, it might be part of a boolean expression handled elsewhere,
            # but here we are parsing atoms. 
            # "super" is reserved but allowed if it forms super(). 
            # We checked super() above. If we are here, it's likely "and", "or" etc used as name.
            self.error(f"cannot use reserved word '{name}' as name", lineno)

        remaining = source[len(name):]
        segments = []

        while remaining.startswith("."):
            remaining = remaining[1:].strip()
            if not remaining:
                self.error("expected segment after dot", lineno)

            seg_name = self._read_name(remaining, lineno)
            if seg_name:
                if seg_name in RESERVED_WORDS:
                    self.error(f"cannot use reserved word '{seg_name}' as segment", lineno)
                remaining = remaining[len(seg_name):]
                segments.append(seg_name)
            elif remaining[0].isdigit():
                i = 0
                while i < len(remaining) and remaining[i].isdigit():
                    i += 1
                val = int(remaining[:i])
                remaining = remaining[i:]
                segments.append(val)
            else:
                self.error("invalid segment", lineno)

        return PathExpr(name, segments), remaining

    # -----------------------------------------------------------------------
    # Condition Parsing
    # -----------------------------------------------------------------------

    def parse_condition(self, source: str, lineno: int) -> Cond:
        # We use a mini-tokenizer for conditions to handle operators correctly
        # The previous implementation of parse_condition was missing in the provided snippet 
        # but referenced. I will reimplement it simply to match the AST.

        # For simplicity and consistency with the existing code structure which seemed to 
        # delegate complex condition parsing, I will implement a basic recursive descent
        # for the condition string similar to how _parse_expr_from_string works but for conditions.

        # However, the original code had `self.parse_condition(cond_str, lineno)`. 
        # I need to implement it.

        # Let's split by top level 'and'/'or' first? No, we need proper precedence.
        # Not > And > Or

        # Given the complexity, and that the main goal is inheritance/block parsing,
        # I will implement a simplified condition parser that supports the basic operators.

        return self._parse_or_cond(source, lineno)

    def _parse_or_cond(self, source: str, lineno: int) -> Cond:
        parts = self._split_top_level(source, "or")
        if len(parts) > 1:
            if len(parts) > 2:
                 self.error("multiple or operators", lineno)
            left = self._parse_and_cond(parts[0], lineno)
            right = self._parse_and_cond(parts[1], lineno)
            return BoolOp("or", left, right)
        return self._parse_and_cond(source, lineno)

    def _parse_and_cond(self, source: str, lineno: int) -> Cond:
        parts = self._split_top_level(source, "and")
        if len(parts) > 1:
            if len(parts) > 2:
                 self.error("multiple and operators", lineno)
            left = self._parse_not_cond(parts[0], lineno)
            right = self._parse_not_cond(parts[1], lineno)
            return BoolOp("and", left, right)
        return self._parse_not_cond(source, lineno)

    def _parse_not_cond(self, source: str, lineno: int) -> Cond:
        source = source.strip()
        if source.startswith("not "):
            rest = source[4:].strip()
            operand = self._parse_not_cond(rest, lineno)
            return NotOp(operand)
        return self._parse_comparison_cond(source, lineno)

    def _parse_comparison_cond(self, source: str, lineno: int) -> Cond:
        source = source.strip()

        # Find operator
        op_idx = -1
        op = ""
        for o in ["==", "!=", "<=", ">=", "<", ">"]:
            idx = self._find_top_level(source, o)
            if idx != -1:
                if op_idx == -1 or idx < op_idx:
                    op_idx = idx
                    op = o
                    break # Assuming we found one, but strict left-to-right? 
                    # Actually, we need to find the first top-level operator.

        # Re-scan for all ops to find the first one
        op_idx = -1
        op = ""
        for o in ["==", "!=", "<=", ">=", "<", ">"]:
            idx = self._find_top_level(source, o)
            if idx != -1:
                if op_idx == -1 or idx < op_idx:
                    op_idx = idx
                    op = o
                    # Don't break, might have an earlier one?
                    # Actually _find_top_level finds the first occurrence.
                    # We just need the one with the smallest index.

        if op_idx != -1:
            left_str = source[:op_idx].strip()
            right_str = source[op_idx+len(op):].strip()

            left_expr = self._parse_expr_from_string(left_str, lineno)
            right_expr = self._parse_expr_from_string(right_str, lineno)

            return Compare(left_expr, op, right_expr)

        # No operator, it's a bare expression
        expr = self._parse_expr_from_string(source, lineno)
        return ExprCond(expr)

