from .tokens import SQLError
from .parser import (Select, Column, Literal, Compare, And, Or, Not, IsNull, parse)


class SQLExecutionError(SQLError):
    """Raised when an execution error occurs (e.g. type mismatch, unknown table)."""
    pass


def _kind(v):
    """Determine the kind of a value for comparison purposes."""
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'bool'
    if isinstance(v, (int, float)):
        return 'number'
    if isinstance(v, str):
        return 'string'
    # Should not happen in this simple SQL subset
    return 'unknown'


def _value_of(node, row):
    """Evaluate an operand (Column or Literal) against a row."""
    if isinstance(node, Column):
        return row.get(node.name)
    elif isinstance(node, Literal):
        return node.value
    raise SQLExecutionError(f"Invalid operand type: {type(node)}")


def _eval_condition(cond, row):
    """Evaluate a condition against a row using three-valued logic."""
    if isinstance(cond, IsNull):
        v = _value_of(cond.operand, row)
        res = v is None
        return not res if cond.negated else res

    if isinstance(cond, Not):
        res = _eval_condition(cond.operand, row)
        return None if res is None else not res

    if isinstance(cond, And):
        left = _eval_condition(cond.left, row)
        if left is False:
            return False
        right = _eval_condition(cond.right, row)
        if right is False:
            return False
        if left is None or right is None:
            return None
        return True

    if isinstance(cond, Or):
        left = _eval_condition(cond.left, row)
        if left is True:
            return True
        right = _eval_condition(cond.right, row)
        if right is True:
            return True
        if left is None or right is None:
            return None
        return False

    if isinstance(cond, Compare):
        l_val = _value_of(cond.left, row)
        r_val = _value_of(cond.right, row)

        k_l = _kind(l_val)
        k_r = _kind(r_val)

        # If either is NULL, result is unknown (None)
        if k_l == 'null' or k_r == 'null':
            return None

        # If kinds are different
        if k_l != k_r:
            if cond.op == '=':
                return False
            if cond.op == '!=':
                return True
            raise SQLExecutionError(
                f"Cannot compare values of different types: {k_l} vs {k_r}"
            )

        # Same kind, perform comparison
        try:
            if cond.op == '=':
                return l_val == r_val
            if cond.op == '!=':
                return l_val != r_val
            if cond.op == '<':
                return l_val < r_val
            if cond.op == '<=':
                return l_val <= r_val
            if cond.op == '>':
                return l_val > r_val
            if cond.op == '>=':
                return l_val >= r_val
        except TypeError:
            raise SQLExecutionError(f"Incomparable values: {l_val} and {r_val}")

    raise SQLExecutionError(f"Invalid condition type: {type(cond)}")


class _SortWrapper:
    """Helper class to implement custom sorting logic with NULLs and directions."""
    def __init__(self, val, desc):
        self.val = val
        self.desc = desc
        self.is_null = val is None

    def __eq__(self, other):
        if isinstance(other, _SortWrapper):
            return self.val == other.val
        return NotImplemented

    def __lt__(self, other):
        if not isinstance(other, _SortWrapper):
            return NotImplemented

        # Handle NULLs first based on direction
        if self.is_null and other.is_null:
            return False

        if self.is_null:
            # NULL vs Value
            # ASC (desc=False): NULL < Value -> True (NULLs first)
            # DESC (desc=True): NULL > Value -> False (NULLs last)
            return not self.desc

        if other.is_null:
            # Value vs NULL
            # ASC (desc=False): Value < NULL -> False (Values after NULLs)
            # DESC (desc=True): Value < NULL -> True (Values before NULLs)
            return self.desc

        # Both are values (non-null)
        # Types are guaranteed consistent per column by earlier check
        if self.desc:
            # Reverse order
            return self.val > other.val
        else:
            # Normal order
            return self.val < other.val


def execute(stmt: Select, tables: dict[str, list[dict]]) -> list[dict]:
    """Execute a parsed SELECT statement against in-memory tables."""
    if stmt.table not in tables:
        raise SQLExecutionError(f"Table not found: {stmt.table}")

    table = tables[stmt.table]

    # 1. Filter (WHERE)
    if stmt.where:
        filtered_rows = []
        for row in table:
            if _eval_condition(stmt.where, row) is True:
                filtered_rows.append(row)
    else:
        filtered_rows = table

    # 2. Sort (ORDER BY)
    if stmt.order_by:
        # Validate type consistency for each ORDER BY column among non-null values
        for name, _ in stmt.order_by:
            kinds = set()
            for row in filtered_rows:
                val = row.get(name)
                if val is not None:
                    kinds.add(_kind(val))
            if len(kinds) > 1:
                raise SQLExecutionError(
                    f"Mixed types in ORDER BY column: {name}"
                )

        # Define key function using _SortWrapper
        def sort_key(row):
            return tuple(
                _SortWrapper(row.get(name), desc)
                for name, desc in stmt.order_by
            )

        # Stable sort
        filtered_rows.sort(key=sort_key)

    # 3. Limit
    if stmt.limit is not None:
        filtered_rows = filtered_rows[:stmt.limit]

    # 4. Project (SELECT)
    result = []
    if stmt.columns is None:
        # Select *: shallow copy of all keys
        for row in filtered_rows:
            result.append(dict(row))
    else:
        # Select list: exactly these keys, in order
        for row in filtered_rows:
            new_row = {}
            for name in stmt.columns:
                new_row[name] = row.get(name)
            result.append(new_row)

    return result


def query(sql: str, tables: dict[str, list[dict]]) -> list[dict]:
    """Parse and execute a SQL query."""
    return execute(parse(sql), tables)
