# minisql/tokens.py
from dataclasses import dataclass
from typing import Any


class SQLError(Exception):
    """Base exception for all SQL errors."""
    pass


class SQLSyntaxError(SQLError):
    """Raised when a syntax error is detected during tokenization or parsing."""
    def __init__(self, message: str, pos: int):
        super().__init__(message)
        self.pos = pos


@dataclass(frozen=True)
class Token:
    kind: str
    value: Any
    pos: int


KEYWORDS = {
    "SELECT", "FROM", "WHERE", "AND", "OR", "NOT", "ORDER", "BY",
    "ASC", "DESC", "LIMIT", "IS", "NULL", "TRUE", "FALSE"
}


def tokenize(sql: str) -> list[Token]:
    tokens: list[Token] = []
    i = 0
    n = len(sql)

    while i < n:
        ch = sql[i]

        # Skip whitespace
        if ch.isspace():
            i += 1
            continue

        # Check for numbers (with optional negative sign)
        # A number starts with a digit, or '-' followed by a digit or '.'
        if ch.isdigit() or (ch == '-' and i + 1 < n and (sql[i + 1].isdigit() or sql[i + 1] == '.')):
            start = i
            if ch == '-':
                i += 1
            # Parse integer part
            if i < n and sql[i].isdigit():
                while i < n and sql[i].isdigit():
                    i += 1
            # Check for fractional part
            if i < n and sql[i] == '.':
                dot_pos = i
                i += 1
                if i >= n or not sql[i].isdigit():
                    raise SQLSyntaxError("Invalid number: '.' must be followed by digits", dot_pos)
                while i < n and sql[i].isdigit():
                    i += 1
            num_str = sql[start:i]
            if '.' in num_str:
                value = float(num_str)
            else:
                value = int(num_str)
            tokens.append(Token("NUMBER", value, start))
            continue

        # Check for identifiers and keywords
        if ch.isalpha() or ch == '_':
            start = i
            while i < n and (sql[i].isalnum() or sql[i] == '_'):
                i += 1
            word = sql[start:i]
            upper_word = word.upper()
            if upper_word in KEYWORDS:
                tokens.append(Token("KEYWORD", upper_word, start))
            else:
                tokens.append(Token("IDENT", word, start))
            continue

        # Check for strings
        if ch == "'":
            start = i
            i += 1
            buf: list[str] = []
            terminated = False
            while i < n:
                if sql[i] == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        buf.append("'")
                        i += 2
                    else:
                        terminated = True
                        i += 1
                        break
                else:
                    buf.append(sql[i])
                    i += 1
            if not terminated:
                raise SQLSyntaxError("Unterminated string literal", start)
            tokens.append(Token("STRING", "".join(buf), start))
            continue

        # Check for operators and symbols
        if ch == '=':
            tokens.append(Token("OP", "=", i))
            i += 1
            continue
        if ch == '!' and i + 1 < n and sql[i + 1] == '=':
            tokens.append(Token("OP", "!=", i))
            i += 2
            continue
        if ch == '<':
            if i + 1 < n:
                if sql[i + 1] == '>':
                    tokens.append(Token("OP", "!=", i))
                    i += 2
                    continue
                if sql[i + 1] == '=':
                    tokens.append(Token("OP", "<=", i))
                    i += 2
                    continue
            tokens.append(Token("OP", "<", i))
            i += 1
            continue
        if ch == '>':
            if i + 1 < n and sql[i + 1] == '=':
                tokens.append(Token("OP", ">=", i))
                i += 2
                continue
            tokens.append(Token("OP", ">", i))
            i += 1
            continue
        if ch == '*':
            tokens.append(Token("STAR", "*", i))
            i += 1
            continue
        if ch == ',':
            tokens.append(Token("COMMA", ",", i))
            i += 1
            continue
        if ch == '(':
            tokens.append(Token("LPAREN", "(", i))
            i += 1
            continue
        if ch == ')':
            tokens.append(Token("RPAREN", ")", i))
            i += 1
            continue

        # Any other character is an error
        raise SQLSyntaxError(f"Unexpected character: {ch!r}", i)

    tokens.append(Token("EOF", None, n))
    return tokens

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Optional, Union

from .tokens import Token, SQLSyntaxError, tokenize

# AST Nodes

@dataclass(frozen=True)
class Column:
    name: str

@dataclass(frozen=True)
class Literal:
    value: Any  # int, float, str, bool, or None

@dataclass(frozen=True)
class Compare:
    op: str  # '=', '!=', '<', '<=', '>', '>='
    left: Any  # Column or Literal
    right: Any  # Column or Literal

@dataclass(frozen=True)
class And:
    left: Any
    right: Any

@dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclass(frozen=True)
class Not:
    operand: Any

@dataclass(frozen=True)
class IsNull:
    operand: Any  # Column or Literal
    negated: bool

@dataclass(frozen=True)
class Select:
    columns: Optional[list[str]]  # None for *
    table: str
    where: Optional[Any]
    order_by: list[tuple[str, bool]]  # (name, descending)
    limit: Optional[int]


# Parser

class _Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def current(self) -> Token:
        return self.tokens[self.pos]

    def peek(self, offset: int = 1) -> Token:
        idx = self.pos + offset
        if idx < len(self.tokens):
            return self.tokens[idx]
        return self.tokens[-1]  # EOF

    def advance(self) -> Token:
        tok = self.current()
        if tok.kind != 'EOF':
            self.pos += 1
        return tok

    def expect(self, kind: str, value: Optional[Any] = None, msg: Optional[str] = None) -> Token:
        tok = self.current()
        if tok.kind != kind or (value is not None and tok.value != value):
            if msg is None:
                msg = f"Expected {kind}"
                if value is not None:
                    msg += f" {value!r}"
                else:
                    msg += f", got {tok.kind} {tok.value!r}"
            raise SQLSyntaxError(msg, tok.pos)
        return self.advance()

    def match(self, kind: str, value: Optional[Any] = None) -> Optional[Token]:
        tok = self.current()
        if tok.kind == kind and (value is None or tok.value == value):
            return self.advance()
        return None

    def parse(self) -> Select:
        self.expect('KEYWORD', 'SELECT')
        columns = self.parse_select_list()
        self.expect('KEYWORD', 'FROM')
        table_tok = self.expect('IDENT')
        table = table_tok.value

        where = None
        if self.match('KEYWORD', 'WHERE'):
            where = self.parse_condition()

        order_by = []
        if self.match('KEYWORD', 'ORDER'):
            self.expect('KEYWORD', 'BY')
            order_by = self.parse_order_by()

        limit = None
        if self.match('KEYWORD', 'LIMIT'):
            limit_tok = self.expect('NUMBER')
            if not isinstance(limit_tok.value, int) or limit_tok.value < 0:
                raise SQLSyntaxError("LIMIT must be a non-negative integer", limit_tok.pos)
            limit = limit_tok.value

        if self.current().kind != 'EOF':
            raise SQLSyntaxError(f"Unexpected token {self.current().value!r}", self.current().pos)

        return Select(columns, table, where, order_by, limit)

    def parse_select_list(self) -> Optional[list[str]]:
        if self.match('STAR'):
            if self.match('COMMA'):
                # Star must be alone if present? The grammar says `* | name {, name}`. So * is alone.
                # If we see comma after star, it's invalid.
                raise SQLSyntaxError("Cannot mix * with named columns", self.current().pos)
            return None

        names = []
        while True:
            name_tok = self.expect('IDENT')
            name = name_tok.value
            if name in names:
                raise SQLSyntaxError(f"Duplicate column name: {name}", name_tok.pos)
            names.append(name)
            if not self.match('COMMA'):
                break
        return names

    def parse_order_by(self) -> list[tuple[str, bool]]:
        items = []
        while True:
            name_tok = self.expect('IDENT')
            descending = False
            if self.match('KEYWORD', 'ASC'):
                descending = False
            elif self.match('KEYWORD', 'DESC'):
                descending = True
            items.append((name_tok.value, descending))
            if not self.match('COMMA'):
                break
        return items

    # Precedence: OR < AND < NOT < Comparison/IsNull < Parenthesized
    # Grammar:
    # condition := condition OR condition | condition AND condition | NOT condition | ( condition ) | operand op operand | operand IS [NOT] NULL
    # Note: NOT binds tighter than AND. AND binds tighter than OR.
    # Associativity: AND/OR left-associative.

    def parse_condition(self) -> Any:
        # Parse OR level (lowest precedence)
        left = self.parse_and()
        while self.match('KEYWORD', 'OR'):
            right = self.parse_and()
            left = Or(left, right)
        return left

    def parse_and(self) -> Any:
        # Parse AND level
        left = self.parse_not()
        while self.match('KEYWORD', 'AND'):
            right = self.parse_not()
            left = And(left, right)
        return left

    def parse_not(self) -> Any:
        # Parse NOT level (highest among logical ops)
        if self.match('KEYWORD', 'NOT'):
            return Not(self.parse_not())
        return self.parse_comparison_or_null()

    def parse_comparison_or_null(self) -> Any:
        # Parse atomic conditions: operand op operand | operand IS [NOT] NULL | ( condition )
        if self.match('LPAREN'):
            inner = self.parse_condition()
            self.expect('RPAREN')
            return inner

        operand = self.parse_operand()

        if self.match('KEYWORD', 'IS'):
            negated = False
            if self.match('KEYWORD', 'NOT'):
                negated = True
            self.expect('KEYWORD', 'NULL')
            return IsNull(operand, negated)

        # Must be a comparison operator
        op_tok = self.current()
        if op_tok.kind == 'OP':
            self.advance()
            right = self.parse_operand()
            return Compare(op_tok.value, operand, right)

        raise SQLSyntaxError(f"Expected comparison operator or IS NULL, got {op_tok.value!r}", op_tok.pos)

    def parse_operand(self) -> Any:
        # operand := name | number | string | NULL | TRUE | FALSE
        tok = self.current()
        if tok.kind == 'IDENT':
            self.advance()
            return Column(tok.value)
        elif tok.kind == 'NUMBER':
            self.advance()
            return Literal(tok.value)
        elif tok.kind == 'STRING':
            self.advance()
            return Literal(tok.value)
        elif tok.kind == 'KEYWORD':
            if tok.value == 'NULL':
                self.advance()
                return Literal(None)
            elif tok.value == 'TRUE':
                self.advance()
                return Literal(True)
            elif tok.value == 'FALSE':
                self.advance()
                return Literal(False)

        raise SQLSyntaxError(f"Expected operand, got {tok.kind} {tok.value!r}", tok.pos)


def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    parser = _Parser(tokens)
    return parser.parse()

