from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Optional

from .tokens import Token, SQLSyntaxError, tokenize

# AST Nodes

@dataclass(frozen=True)
class Column:
    name: str

@dataclass(frozen=True)
class Literal:
    value: Any  # int, float, str, bool, or None

@dataclass(frozen=True)
class Aggregate:
    func: str  # COUNT, SUM, AVG, MIN, MAX (upper case)
    arg: Optional[Column]  # None for COUNT(*)

@dataclass(frozen=True)
class Join:
    table: str
    left: Column
    right: Column

@dataclass(frozen=True)
class Compare:
    op: str  # '=', '!=', '<', '<=', '>', '>='
    left: Any  # Column or Literal
    right: Any  # Column or Literal

@dataclass(frozen=True)
class And:
    left: Any
    right: Any

@dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclass(frozen=True)
class Not:
    operand: Any

@dataclass(frozen=True)
class IsNull:
    operand: Any  # Column or Literal
    negated: bool

@dataclass(frozen=True)
class Select:
    items: list = field(default_factory=list)  # list of (expr, key)
    columns: Optional[list[str]] = None  # None for *
    table: str = ""
    join: Optional[Join] = None
    where: Optional[Any] = None
    group_by: list[str] = field(default_factory=list)
    order_by: list[tuple[str, bool]] = field(default_factory=list)  # (text, descending)
    limit: Optional[int] = None

# Parser

AGGREGATE_KEYWORDS = {'COUNT', 'SUM', 'AVG', 'MIN', 'MAX'}

class _Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def current(self) -> Token:
        return self.tokens[self.pos]

    def peek(self, offset: int = 1) -> Token:
        idx = self.pos + offset
        if idx < len(self.tokens):
            return self.tokens[idx]
        return self.tokens[-1]  # EOF

    def advance(self) -> Token:
        tok = self.current()
        if tok.kind != 'EOF':
            self.pos += 1
        return tok

    def expect(self, kind: str, value: Optional[Any] = None, msg: Optional[str] = None) -> Token:
        tok = self.current()
        if tok.kind != kind or (value is not None and tok.value != value):
            if msg is None:
                msg = f"Expected {kind}"
                if value is not None:
                    msg += f" {value!r}"
                else:
                    msg += f", got {tok.kind} {tok.value!r}"
            raise SQLSyntaxError(msg, tok.pos)
        return self.advance()

    def match(self, kind: str, value: Optional[Any] = None) -> Optional[Token]:
        tok = self.current()
        if tok.kind == kind and (value is None or tok.value == value):
            return self.advance()
        return None

    def parse(self) -> Select:
        self.expect('KEYWORD', 'SELECT')

        items = []
        columns = None
        star_pos = None
        has_aggregate_in_select = False
        item_positions = [] # Track start pos of each item for validation

        if self.match('STAR'):
            columns = None
            items = []
            star_pos = self.current().pos - 1 # Position of * token
            # Check for duplicate keys logic: * is alone.
            if self.match('COMMA'):
                 raise SQLSyntaxError("Cannot mix * with named columns", self.current().pos)
        else:
            columns = []
            while True:
                item_start_tok = self.current()
                item_positions.append(item_start_tok.pos)
                expr, key = self.parse_item()

                # Check for duplicate output key among items
                for _, existing_key in items:
                    if existing_key == key:
                        raise SQLSyntaxError(f"Duplicate output key: {key}", item_start_tok.pos)

                items.append((expr, key))
                columns.append(key)

                if isinstance(expr, Aggregate):
                    has_aggregate_in_select = True

                if not self.match('COMMA'):
                    break

        self.expect('KEYWORD', 'FROM')
        table_tok = self.expect('IDENT')
        table = table_tok.value

        join = None
        if self.match('KEYWORD', 'JOIN'):
            join = self.parse_join()

        where = None
        if self.match('KEYWORD', 'WHERE'):
            where = self.parse_condition()

        group_by = []
        if self.match('KEYWORD', 'GROUP'):
            self.expect('KEYWORD', 'BY')
            group_by = self.parse_group_by()

        order_by = []
        order_by_positions = [] # Track pos of order by items for aggregate check
        if self.match('KEYWORD', 'ORDER'):
            self.expect('KEYWORD', 'BY')
            order_by, order_by_positions = self.parse_order_by()

        limit = None
        if self.match('KEYWORD', 'LIMIT'):
            limit_tok = self.expect('NUMBER')
            if not isinstance(limit_tok.value, int) or limit_tok.value < 0:
                raise SQLSyntaxError("LIMIT must be a non-negative integer", limit_tok.pos)
            limit = limit_tok.value

        if self.current().kind != 'EOF':
            raise SQLSyntaxError(f"Unexpected token {self.current().value!r}", self.current().pos)

        # Validation phase
        is_grouped = has_aggregate_in_select or bool(group_by)

        # 1. * in grouped query
        if is_grouped and star_pos is not None:
            raise SQLSyntaxError("Cannot use * in grouped query", star_pos)

        # 2. Plain ref in grouped query not in GROUP BY
        if is_grouped:
            group_by_set = set(group_by)
            for i, (expr, key) in enumerate(items):
                if isinstance(expr, Column):
                    if expr.name not in group_by_set:
                        raise SQLSyntaxError(f"Column {expr.name} not in GROUP BY", item_positions[i])
                elif isinstance(expr, Aggregate):
                    pass # Aggregates allowed

        # 3. Aggregate in ORDER BY of non-grouped query
        if not is_grouped:
            for text, pos in zip(order_by, order_by_positions):
                if '(' in text and text.startswith(('COUNT(', 'SUM(', 'AVG(', 'MIN(', 'MAX(')):
                    raise SQLSyntaxError("Aggregate not allowed in ORDER BY without GROUP BY", pos)

        # 4. Validate ORDER BY items in grouped query (must match select item)
        if is_grouped:
            valid_keys = {k for _, k in items}
            for text, _ in order_by:
                if text not in valid_keys:
                    # The spec says: "each ORDER BY text must equal the alias or the canonical text of a select item"
                    # Anything else raises SQLExecutionError. 
                    # Wait, syntax error vs execution error? 
                    # "In a grouped query, each ORDER BY text must equal the alias or the canonical text of a select item... Anything else raises SQLExecutionError."
                    # So this is an EXECUTION error, not syntax. Parser should allow it.
                    pass

        return Select(items, columns, table, join, where, group_by, order_by, limit)

    def parse_item(self):
        """Parse a select item: (ref | aggregate) [AS name]"""
        expr = self.parse_expr()
        key = self.get_canonical_text(expr)

        if self.match('KEYWORD', 'AS'):
            alias_tok = self.expect('IDENT')
            key = alias_tok.value

        return expr, key

    def parse_expr(self):
        """Parse Column or Aggregate"""
        tok = self.current()
        if tok.kind == 'KEYWORD' and tok.value.upper() in AGGREGATE_KEYWORDS:
            return self.parse_aggregate()
        elif tok.kind == 'IDENT':
            return self.parse_ref()
        else:
            raise SQLSyntaxError(f"Expected column or aggregate, got {tok.kind} {tok.value!r}", tok.pos)

    def parse_ref(self) -> Column:
        """Parse name or table.name"""
        tok = self.expect('IDENT')
        name = tok.value

        # Check for DOT
        if self.match('DOT'):
            table_tok = self.expect('IDENT')
            # Canonical text is table.name without spaces
            # The spec says: Column(name) holds reference's canonical text: name or table.name
            # Wait, if it's table.name, the value is 'table.name'. 
            # But wait, if query is `p.id`, canonical is `p.id`.
            # The spec says "p . id is p.id". So space is removed.
            # However, my parser expects `IDENT DOT IDENT`. 
            # The first IDENT is table, second is column.
            # Result: Column(f"{name}.{table_tok.value}")
            return Column(f"{name}.{table_tok.value}")

        return Column(name)

    def parse_aggregate(self) -> Aggregate:
        """Parse COUNT(*), SUM(ref), etc."""
        func_tok = self.expect('KEYWORD')
        func = func_tok.value.upper()

        self.expect('LPAREN')

        arg = None
        if self.match('STAR'):
            arg = None
        else:
            arg = self.parse_ref()

        self.expect('RPAREN')
        return Aggregate(func, arg)

    def get_canonical_text(self, expr) -> str:
        if isinstance(expr, Column):
            return expr.name
        elif isinstance(expr, Aggregate):
            if expr.arg:
                return f"{expr.func}({expr.arg.name})"
            else:
                return f"{expr.func}(*)"
        raise ValueError("Invalid expression")

    def parse_join(self) -> Join:
        """Parse JOIN table ON ref = ref"""
        table_tok = self.expect('IDENT')
        table = table_tok.value

        self.expect('KEYWORD', 'ON')

        left = self.parse_ref()

        op_tok = self.expect('OP', '=')

        right = self.parse_ref()

        return Join(table, left, right)

    def parse_group_by(self) -> list[str]:
        refs = []
        while True:
            col = self.parse_ref()
            refs.append(col.name)
            if not self.match('COMMA'):
                break
        return refs

    def parse_order_by(self) -> tuple[list[tuple[str, bool]], list[int]]:
        items = []
        positions = []
        while True:
            expr_start_pos = self.current().pos
            expr = self.parse_expr()
            text = self.get_canonical_text(expr)

            descending = False
            if self.match('KEYWORD', 'ASC'):
                descending = False
            elif self.match('KEYWORD', 'DESC'):
                descending = True

            items.append((text, descending))
            positions.append(expr_start_pos)
            if not self.match('COMMA'):
                break
        return items, positions

    # Precedence: OR < AND < NOT < Comparison/IsNull < Parenthesized

    def parse_condition(self) -> Any:
        left = self.parse_and()
        while self.match('KEYWORD', 'OR'):
            right = self.parse_and()
            left = Or(left, right)
        return left

    def parse_and(self) -> Any:
        left = self.parse_not()
        while self.match('KEYWORD', 'AND'):
            right = self.parse_not()
            left = And(left, right)
        return left

    def parse_not(self) -> Any:
        if self.match('KEYWORD', 'NOT'):
            return Not(self.parse_not())
        return self.parse_comparison_or_null()

    def parse_comparison_or_null(self) -> Any:
        if self.match('LPAREN'):
            inner = self.parse_condition()
            self.expect('RPAREN')
            return inner

        operand = self.parse_operand()

        if self.match('KEYWORD', 'IS'):
            negated = False
            if self.match('KEYWORD', 'NOT'):
                negated = True
            self.expect('KEYWORD', 'NULL')
            return IsNull(operand, negated)

        op_tok = self.current()
        if op_tok.kind == 'OP':
            self.advance()
            right = self.parse_operand()
            return Compare(op_tok.value, operand, right)

        raise SQLSyntaxError(f"Expected comparison operator or IS NULL, got {op_tok.value!r}", op_tok.pos)

    def parse_operand(self) -> Any:
        tok = self.current()
        if tok.kind == 'IDENT':
            return self.parse_ref()
        elif tok.kind == 'NUMBER':
            self.advance()
            return Literal(tok.value)
        elif tok.kind == 'STRING':
            self.advance()
            return Literal(tok.value)
        elif tok.kind == 'KEYWORD':
            if tok.value == 'NULL':
                self.advance()
                return Literal(None)
            elif tok.value == 'TRUE':
                self.advance()
                return Literal(True)
            elif tok.value == 'FALSE':
                self.advance()
                return Literal(False)

        raise SQLSyntaxError(f"Expected operand, got {tok.kind} {tok.value!r}", tok.pos)


def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    parser = _Parser(tokens)
    return parser.parse()
