from .tokens import SQLError
from .parser import (Select, Column, Literal, Compare, And, Or, Not, IsNull, Aggregate, Join, parse)


class SQLExecutionError(SQLError):
    """Raised when an execution error occurs (e.g. type mismatch, unknown table)."""
    pass


def _kind(v):
    """Determine the kind of a value for comparison purposes."""
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'bool'
    if isinstance(v, (int, float)):
        return 'number'
    if isinstance(v, str):
        return 'string'
    # Should not happen in this simple SQL subset
    return 'unknown'


def _value_of(node, row):
    """Evaluate an operand (Column or Literal) against a row."""
    if isinstance(node, Column):
        return row.get(node.name)
    elif isinstance(node, Literal):
        return node.value
    raise SQLExecutionError(f"Invalid operand type: {type(node)}")


def _eval_condition(cond, row):
    """Evaluate a condition against a row using three-valued logic."""
    if isinstance(cond, IsNull):
        v = _value_of(cond.operand, row)
        res = v is None
        return not res if cond.negated else res

    if isinstance(cond, Not):
        res = _eval_condition(cond.operand, row)
        return None if res is None else not res

    if isinstance(cond, And):
        left = _eval_condition(cond.left, row)
        if left is False:
            return False
        right = _eval_condition(cond.right, row)
        if right is False:
            return False
        if left is None or right is None:
            return None
        return True

    if isinstance(cond, Or):
        left = _eval_condition(cond.left, row)
        if left is True:
            return True
        right = _eval_condition(cond.right, row)
        if right is True:
            return True
        if left is None or right is None:
            return None
        return False

    if isinstance(cond, Compare):
        l_val = _value_of(cond.left, row)
        r_val = _value_of(cond.right, row)

        k_l = _kind(l_val)
        k_r = _kind(r_val)

        # If either is NULL, result is unknown (None)
        if k_l == 'null' or k_r == 'null':
            return None

        # If kinds are different
        if k_l != k_r:
            if cond.op == '=':
                return False
            if cond.op == '!=':
                return True
            raise SQLExecutionError(
                f"Cannot compare values of different types: {k_l} vs {k_r}"
            )

        # Same kind, perform comparison
        try:
            if cond.op == '=':
                return l_val == r_val
            if cond.op == '!=':
                return l_val != r_val
            if cond.op == '<':
                return l_val < r_val
            if cond.op == '<=':
                return l_val <= r_val
            if cond.op == '>':
                return l_val > r_val
            if cond.op == '>=':
                return l_val >= r_val
        except TypeError:
            raise SQLExecutionError(f"Incomparable values: {l_val} and {r_val}")

    raise SQLExecutionError(f"Invalid condition type: {type(cond)}")


def _get_qualifiers(stmt: Select) -> set[str]:
    """Get valid qualifiers for the query context."""
    if stmt.join:
        return {stmt.table, stmt.join.table}
    return {stmt.table}


def _check_qualifier(ref_text: str, qualifiers: set[str], context: str):
    """Validate a reference string (canonical form) against allowed qualifiers."""
    if '.' not in ref_text:
        # Unqualified
        if len(qualifiers) > 1:
            raise SQLExecutionError(f"Ambiguous unqualified reference: {ref_text}")
        # If single table, it's fine, but we might need to check if column exists? 
        # Spec: "Without JOIN, name and table.name both read column name... any other qualifier raises Error"
        # "With JOIN, every reference... must be qualified... an unqualified reference... raises Error"
        pass 
    else:
        # Qualified
        qual, _ = ref_text.split('.', 1)
        if qual not in qualifiers:
            raise SQLExecutionError(f"Invalid qualifier {qual} in {ref_text}")


def _resolve_ref(row: dict, col: Column, qualifiers: set[str]):
    """Resolve a column reference against a row."""
    # The row keys are already canonicalized in the join step or come from tables.
    # In single table: keys are 'name'. Column is 'name'.
    # In join: keys are 't1.name'. Column is 't1.name'.

    # Validation of qualifier vs row structure is implicitly handled by key lookup 
    # if we ensure columns in AST match row keys.
    # However, explicit checks for "unknown columns" might be needed? 
    # Spec: "unknown tables are SQLExecutionError as before". Unknown columns? 
    "   # Spec doesn't explicitly say unknown column is execution error, but if row.get returns None, 
    # it might be ambiguous with actual NULL. However, usually SQL raises error on unknown column.
    # The previous implementation used row.get(name). 
    # Let's stick to row.get(name) but raise if not in keys? 
    # Spec: "one of p and q must name a column of a... otherwise SQLExecutionError".
    # This implies we should check existence.

    if col.name not in row:
        # Could be missing column. 
        # But if it's a derived value or something? No, refs are from tables.
        # If it's a valid ref but not in row, it's an error.
        raise SQLExecutionError(f"Unknown column: {col.name}")

    return row[col.name]


def _perform_join(table_a: list[dict], join: Join, tables: dict) -> list[dict]:
    """Perform an inner join and return rows with qualified keys."""
    table_b_name = join.table
    if table_b_name not in tables:
        raise SQLExecutionError(f"Table not found: {table_b_name}")

    table_b = tables[table_b_name]

    # Determine left/right join columns
    # join.left and join.right are Columns.
    # One must be in table_a, one in table_b.

    # We need to know which column belongs to which table to match values.
    # Spec: "One of p and q must name a column of a and the other a column of b, in either order"

    # Check if join columns exist in respective tables
    # We assume first row defines keys? Or check union of keys? 
    # Standard behavior: check against table schema. 
    # Since we have list of dicts, we can check keys of first row or scan.

    def get_keys(table):
        if not table:
            return set()
        return set(table[0].keys())

    keys_a = get_keys(table_a)
    keys_b = get_keys(table_b)

    # Identify which is which
    # If left column name is in keys_a, it's A.col. Else it's B.col?
    # Actually, we must validate that exactly one is in A and one is in B.

    left_name = join.left.name
    right_name = join.right.name

    left_in_a = left_name in keys_a
    right_in_a = right_name in keys_a
    left_in_b = left_name in keys_b
    right_in_b = right_name in keys_b

    # Validate: One and only one of left/right is in A, the other in B.
    # And they must NOT be in the wrong table? 
    # Spec: "One of p and q must name a column of a and the other a column of b"

    if left_in_a and right_in_b:
        col_a = left_name
        col_b = right_name
    elif right_in_a and left_in_b:
        col_a = right_name
        col_b = left_name
    else:
        raise SQLExecutionError("Join ON condition requires one column from each table")

    # Check that col_a is NOT in B and col_b is NOT in A? 
    # "otherwise SQLExecutionError". If both in A, it's invalid.

    # Perform cross product and filter
    result = []
    for row_a in table_a:
        val_a = row_a.get(col_a)
        for row_b in table_b:
            val_b = row_b.get(col_b)

            # Check equality
            if val_a is None or val_b is None:
                continue

            k_a = _kind(val_a)
            k_b = _kind(val_b)

            if k_a != k_b:
                continue

            if val_a != val_b:
                continue

            # Construct joined row
            # Keys: a.k and b.k. 
            # Spec: "A joined row is a dict with the keys a.k for each key of the a row, in its order, 
            # followed by b.k for each key of the b row."
            # Note: table_a name is stmt.table, table_b name is join.table.

            joined_row = {}
            for k, v in row_a.items():
                joined_row[f"{stmt_table_name}.{k}"] = v # Need stmt_table_name passed?

            for k, v in row_b.items():
                joined_row[f"{table_b_name}.{k}"] = v

            result.append(joined_row)

    return result


# We need stmt.table name inside _perform_join or pass it.
# Refactoring _perform_join to take table_name_a

def _perform_join_impl(table_name_a: str, table_a: list[dict], join: Join, table_b: list[dict], table_name_b: str) -> list[dict]:
    keys_a = set(table_a[0].keys()) if table_a else set()
    keys_b = set(table_b[0].keys()) if table_b else set()

    left_name = join.left.name
    right_name = join.right.name

    left_in_a = left_name in keys_a
    right_in_a = right_name in keys_a
    left_in_b = left_name in keys_b
    right_in_b = right_name in keys_b

    if left_in_a and right_in_b:
        col_a = left_name
        col_b = right_name
    elif right_in_a and left_in_b:
        col_a = right_name
        col_b = left_name
    else:
        raise SQLExecutionError("Invalid join column pairing")

    result = []
    for row_a in table_a:
        val_a = row_a.get(col_a)
        if val_a is None: continue
        k_a = _kind(val_a)

        for row_b in table_b:
            val_b = row_b.get(col_b)
            if val_b is None: continue
            k_b = _kind(val_b)

            if k_a == k_b and val_a == val_b:
                joined_row = {}
                for k, v in row_a.items():
                    joined_row[f"{table_name_a}.{k}"] = v
                for k, v in row_b.items():
                    joined_row[f"{table_name_b}.{k}"] = v
                result.append(joined_row)
    return result


class _SortWrapper:
    """Helper class to implement custom sorting logic with NULLs and directions."""
    def __init__(self, val, desc):
        self.val = val
        self.desc = desc
        self.is_null = val is None

    def __eq__(self, other):
        if isinstance(other, _SortWrapper):
            return self.val == other.val
        return NotImplemented

    def __lt__(self, other):
        if not isinstance(other, _SortWrapper):
            return NotImplemented

        if self.is_null and other.is_null:
            return False

        if self.is_null:
            return not self.desc

        if other.is_null:
            return self.desc

        if self.desc:
            return self.val > other.val
        else:
            return self.val < other.val


def _compute_aggregate(func: str, arg: Column | None, rows: list[dict]) -> any:
    """Compute aggregate value for a group of rows."""
    if func == 'COUNT':
        if arg is None:
            return len(rows)
        else:
            return sum(1 for row in rows if _value_of(arg, row) is not None)

    if func == 'SUM':
        if arg is None:
            raise SQLExecutionError("SUM requires an argument")
        vals = [_value_of(arg, row) for row in rows]
        vals = [v for v in vals if v is not None]
        if not vals:
            return None

        all_int = True
        total = 0
        for v in vals:
            if _kind(v) != 'number':
                raise SQLExecutionError(f"Cannot SUM non-numeric value: {v}")
            if not isinstance(v, int):
                all_int = False
            total += v

        return total if all_int else float(total)

    if func == 'AVG':
        if arg is None:
            raise SQLExecutionError("AVG requires an argument")
        vals = [_value_of(arg, row) for row in rows]
        vals = [v for v in vals if v is not None]
        if not vals:
            return None

        total = 0
        for v in vals:
            if _kind(v) != 'number':
                raise SQLExecutionError(f"Cannot AVG non-numeric value: {v}")
            total += v

        return total / len(vals)

    if func == 'MIN' or func == 'MAX':
        if arg is None:
            raise SQLExecutionError(f"{func} requires an argument")
        vals = [_value_of(arg, row) for row in rows]
        vals = [v for v in vals if v is not None]
        if not vals:
            return None

        # Check kinds
        kinds = set(_kind(v) for v in vals)
        if len(kinds) > 1:
            raise SQLExecutionError(f"Cannot {func} mixed types")

        if func == 'MIN':
            return min(vals)
        else:
            return max(vals)

    raise SQLExecutionError(f"Unknown aggregate function: {func}")


def execute(stmt: Select, tables: dict[str, list[dict]]) -> list[dict]:
    """Execute a parsed SELECT statement against in-memory tables."""

    # 0. Validate Tables
    if stmt.table not in tables:
        raise SQLExecutionError(f"Table not found: {stmt.table}")

    table_a_name = stmt.table
    table_a = tables[table_a_name]

    # 1. Source Rows (From + Join)
    if stmt.join:
        if stmt.join.table not in tables:
            raise SQLExecutionError(f"Table not found: {stmt.join.table}")
        if stmt.join.table == table_a_name:
            raise SQLExecutionError("Cannot join table to itself")

        table_b_name = stmt.join.table
        table_b = tables[table_b_name]

        rows = _perform_join_impl(table_a_name, table_a, stmt.join, table_b, table_b_name)
        qualifiers = {table_a_name, table_b_name}
    else:
        rows = table_a
        qualifiers = {table_a_name}

    # Validate all references in stmt have valid qualifiers?
    # We rely on _resolve_ref to fail if keys are wrong. 
    # But spec says: "every reference... must be qualified... qualifier neither table raises Error"
    # Let's do a pre-scan or rely on resolution? 
    # Resolution is safer.

    # 2. Where
    if stmt.where:
        filtered_rows = []
        for row in rows:
            if _eval_condition(stmt.where, row) is True:
                filtered_rows.append(row)
        rows = filtered_rows

    # Determine if grouped
    is_grouped = bool(stmt.group_by) or any(isinstance(e, Aggregate) for e, _ in stmt.items)

    # 3. Grouping and Aggregation
    if is_grouped:
        # Group rows
        groups = {} # key: tuple of group_by vals, value: list of rows

        # Define group key function
        def get_group_key(row):
            key_vals = []
            for gb_ref in stmt.group_by:
                # gb_ref is canonical text string
                val = row.get(gb_ref)
                key_vals.append(val)
            return tuple(key_vals)

        # If no group by, all rows in one group
        if not stmt.group_by:
            groups[(None,)] = rows # Dummy key for single group
        else:
            for row in rows:
                k = get_group_key(row)
                if k not in groups:
                    groups[k] = []
                groups[k].append(row)

        # Compute output rows from groups
        output_rows = []
        # Preserve order of groups by first row? 
        # "Groups come out in the order of their first row."
        # dict in python 3.7+ preserves insertion order. So iterating groups.items() preserves order of first encounter.

        for _, group_rows in groups.items():
            output_row = {}
            for expr, key in stmt.items:
                if isinstance(expr, Aggregate):
                    val = _compute_aggregate(expr.func, expr.arg, group_rows)
                elif isinstance(expr, Column):
                    # Must be in group_by. 
                    # Spec: "In a grouped query, a select item that is a plain ref but is not one of the GROUP BY refs... SyntaxError"
                    # So it IS in group_by. Value is constant in group.
                    # Just take from first row.
                    if group_rows:
                        val = group_rows[0].get(expr.name)
                    else:
                        val = None # Empty group shouldn't happen in loop if generated from rows
                else:
                    raise SQLExecutionError("Invalid select item type")
                output_row[key] = val
            output_rows.append(output_row)

        rows = output_rows

    # 4. Order By
    if stmt.order_by:
        # Sort key function depends on whether grouped or not for validation of refs? 
        # No, sorting is on the current rows (which are either raw filtered rows or aggregated group rows).
        # Values to sort by are determined by the ORDER BY text.

        # In grouped query, ORDER BY text must match select item alias/key.
        # In non-grouped, text is column name or alias.

        # Validate types for ORDER BY columns? 
        # Spec: "Stability, NULL placement and the mixed-kind error are as before." 
        # Previous code checked mixed kinds.

        # Define key function
        # Need to evaluate the ORDER BY text to get the sort value.
        # The text might be an alias or a column name. 
        # If it's an aggregate or complex expr, it's already computed in output_row if grouped.

        # If NOT grouped:
        # rows are raw table rows. ORDER BY text might be `p.id` or `name`.
        # We need to extract `row[ORDER_BY_TEXT]`.

        # If GROUPED:
        # rows are aggregated rows. ORDER BY text must match `output_row` keys.

        # Helper to get sort value
        def get_sort_val(row):
            # row is dict.
            # Find value corresponding to ORDER BY text.
            # In grouped, text == key in row.
            # In non-grouped, text == column name in row (or alias if we projected aliases? No, projection happens AFTER sort in old code? 
            # Old code: Sort THEN Project.
            # Spec: "Then WHERE filters, then grouping, then ORDER BY, then LIMIT." 
            # So Project happens AFTER ORDER BY? 
            # "Output keys... give keys p.name and n". 
            # "SELECT p.name, COUNT(*) AS n ... " -> Grouping creates row {"p.name": val, "n": count}.
            # Then Sort.

            # If NOT grouped: 
            # We have raw rows. 
            # ORDER BY `name` -> row[name].
            # But what if ORDER BY alias? `SELECT name AS n ... ORDER BY n`.
            # Spec: "In a query that is not grouped, a name equal to a select alias sorts by that item's value".
            # This implies we need to know the mapping from alias to expression? 
            # Or does the row already contain the alias? No, raw rows don't.
            # We must evaluate the select item expression for the row to get the sort value? 
            # OR, we project aliases into the working rows before sorting? 
            # Easiest: If alias matches, find the expr, evaluate it for the row.

            # This is complex for non-grouped. 
            # Let's look at old code. Old code just did `row.get(name)`.
            # But now we have aliases.
            # If `stmt.columns` is None (*), no aliases. 
            # If `stmt.columns` is list, we have aliases.

            # Strategy: 
            # Build a map from text to value getter for the current row context.

            pass

        # Let's refine. 
        # If grouped, rows are dicts with keys = select aliases. 
        # ORDER BY text must be one of these keys. 
        # So `row.get(text)` works.

        # If not grouped, rows are dicts with keys = table column names.
        # ORDER BY text might be an alias.
        # If text is an alias, we must evaluate the corresponding expression.
        # If text is a column, we get it.

        # Create map: alias -> expr
        alias_to_expr = {}
        for expr, key in stmt.items:
            if key != getattr(expr, 'name', None): # If key is not the natural name, it's an alias
                alias_to_expr[key] = expr

        def sort_key(row):
            keys = []
            for text, desc in stmt.order_by:
                # Check if text is an alias
                if text in alias_to_expr:
                    expr = alias_to_expr[text]
                    val = _value_of(expr, row) # Assumes expr is Column/Literal, not Aggregate in non-grouped? 
                    # Spec: Aggregate in ORDER BY of non-grouped is Syntax Error. So no aggregates here.
                else:
                    val = row.get(text)
                keys.append(_SortWrapper(val, desc))
            return tuple(keys)

        # Validate mixed types
        for text, _ in stmt.order_by:
            kinds = set()
            for row in rows:
                if text in alias_to_expr:
                    val = _value_of(alias_to_expr[text], row)
                else:
                    val = row.get(text)
                if val is not None:
                    kinds.add(_kind(val))
            if len(kinds) > 1:
                 raise SQLExecutionError(f"Mixed types in ORDER BY column: {text}")

        rows.sort(key=sort_key)

    # 5. Limit
    if stmt.limit is not None:
        rows = rows[:stmt.limit]

    # 6. Project
    result = []
    if stmt.columns is None:
        # Select *: shallow copy
        for row in rows:
            result.append(dict(row))
    else:
        # Select list: exactly these keys, in order
        for row in rows:
            new_row = {}
            for name in stmt.columns:
                new_row[name] = row.get(name)
            result.append(new_row)

    return result


def query(sql: str, tables: dict[str, list[dict]]) -> list[dict]:
    """Parse and execute a SQL query."""
    return execute(parse(sql), tables)
