```python
"""The main Sheet engine managing cell storage and recalculation."""

from __future__ import annotations

import re
from typing import Any

from sheet.formula import (
    parse_formula,
    references,
    evaluate,
    FormulaError,
    ErrorValue,
    ERROR_VALUE,
    CYCLE_VALUE,
)
from sheet.graph import DependencyGraph

_CELL_NAME_RE = re.compile(r"^([A-Z])(\d+)$")
_NUMBER_RE = re.compile(r"^-?(\d+)(\.\d+)?$")


def _validate_cell_name(name: str) -> str:
    """Validate and normalize a cell name. Raises ValueError if invalid."""
    if not isinstance(name, str):
        raise ValueError(f"Cell name must be a string, got {type(name).__name__}")

    upper_name = name.upper()
    match = _CELL_NAME_RE.match(upper_name)
    if not match:
        raise ValueError(f"Invalid cell name {name!r}")

    row_str = match.group(2)
    # Leading zeros check for row (unless it's a single digit 0-9)
    if len(row_str) > 1 and row_str[0] == '0':
        raise ValueError(f"Invalid cell name {name!r} (leading zero in row)")

    row = int(row_str)
    if row < 1 or row > 999:
        raise ValueError(f"Invalid cell name {name!r} (row out of range 1-999)")

    return upper_name


def _parse_row_major_key(name: str) -> tuple[int, str]:
    """Returns (row, column) for sorting in row-major order."""
    col, row_str = name[0], name[1:]
    return (int(row_str), col)


class Sheet:
    def __init__(self):
        self._raw: dict[str, str] = {}
        self._values: dict[str, Any] = {}  # cell -> value
        self._trees: dict[str, Any] = {}   # cell -> ASTNode (only for formulas)
        self._graph = DependencyGraph()
        self.evaluations: int = 0

    def _lookup(self, name: str) -> Any:
        """Lookup value for formula evaluation."""
        return self._values.get(name)

    def set(self, name: str, raw: str) -> list[str]:
        """Set the input for a cell and recalculate affected cells.

        Args:
            name: The cell name (e.g. 'A1').
            raw: The raw input string.

        Returns:
            List of cell names whose values changed, in row-major order.

        Raises:
            ValueError: If name is invalid.
            TypeError: If raw is not a string.
            FormulaError: If raw is a formula with syntax errors.
        """
        if not isinstance(raw, str):
            raise TypeError(f"Input must be a string, got {type(raw).__name__}")

        cell = _validate_cell_name(name)

        old_raw = self._raw.get(cell)

        # 1. Parse and store new input
        if raw == '':
            new_tree = None
            new_value = None
            new_precs = set()
            self._raw.pop(cell, None)
            self._values.pop(cell, None)
            self._trees.pop(cell, None)
            self._graph.set_dependencies(cell, set())
        elif raw.startswith('='):
            formula_text = raw[1:]
            try:
                tree = parse_formula(formula_text)
            except FormulaError:
                # On error, sheet is unchanged
                raise

            precs = references(tree)
            self._raw[cell] = raw
            self._trees[cell] = tree
            # Value will be computed later
            self._graph.set_dependencies(cell, precs)
            # Keep old value until recalculation confirms? No, set immediately to None or keep? 
            # Spec: "set ... left completely unchanged" on parse error. So we don't touch graph/raw.
            # If we are here, parse succeeded.
            # We store tree and raw. Value is pending.
        else:
            # Check if number
            stripped = raw.strip()
            if _NUMBER_RE.match(stripped):
                # It's a number literal in text
                # We store raw exactly as given? Spec: "stored exactly as given (spaces included)" applies to text.
                # "If raw with surrounding whitespace removed is ... number ... value is that number"
                # Does raw store stripped or original?
                # "Anything else is text, stored exactly as given (spaces included)."
                # For numbers, it says "If raw ... is an optional '-' followed by digits ..., the value is that number".
                # It doesn't explicitly say how raw is stored for numbers. 
                # Usually raw preserves input. But if it's a number, maybe it's just the number string?
                # Let's assume raw stores original string.
                # However, for evaluation, we treat it as a number.
                pass

            # Determine value
            stripped = raw.strip()
            if _NUMBER_RE.match(stripped):
                num_str = stripped
                is_float = '.' in num_str
                if is_float:
                    val = float(num_str)
                else:
                    val = int(num_str)
            else:
                val = raw

            new_tree = None
            new_precs = set()
            self._raw[cell] = raw
            self._values[cell] = val
            self._trees.pop(cell, None)
            self._graph.set_dependencies(cell, set())

        # If raw is empty string handled above.

        # 2. Recalculate
        # Identify affected cells: the cell itself + all transitive dependents
        affected = self._graph.all_dependents(cell)
        affected.add(cell)

        # Get all cells on cycles to exclude from evaluation (assign #CYCLE! instead)
        cycle_cells = self._graph.cycle_cells()

        # We need to evaluate non-cycle formula cells in topological order.
        # Topological sort of affected cells based on precedents within the set.
        # Simple approach: Iterative pass until stable or use Kahn's algorithm.
        # Given constraints, Kahn's on the subgraph of affected cells is robust.

        # Build subgraph for affected cells
        # Nodes: affected
        # Edges: If cell C depends on P, and both in affected, edge P -> C.
        # Wait, precedents are inputs. Dependents are outputs.
        # If C has precedent P, P must be evaluated before C.

        # Filter out cycle cells from evaluation set. 
        # Cells on cycles get #CYCLE!.

        cells_to_eval = []
        cells_on_cycle = set()

        for c in affected:
            if c in cycle_cells:
                # If a cell is on a cycle, it is #CYCLE!
                # Note: A cell might be on a cycle but not have a formula? 
                # Only formula cells can be part of cycles in the graph logic usually.
                # If a non-formula cell is reported in cycle_cells, that would be weird.
                # Let's assume only formula cells in graph matter for cycles.
                # If a cell is on a cycle, its value is #CYCLE!.
                cells_on_cycle.add(c)
            else:
                cells_to_eval.append(c)

        # Assign #CYCLE! to cells on cycles in the affected set
        for c in cells_on_cycle:
            # Only if it's a formula cell? Or any cell?
            # If a cell is on a cycle, it refers to itself eventually.
            # If it's not a formula, it can't be on a cycle (no deps).
            # So it must be a formula cell.
            self._values[c] = CYCLE_VALUE

        # Sort cells_to_eval topologically
        # We can use a simple priority queue or just sort by depth?
        # Let's use Kahn's algorithm on the subset.

        # Precedents within affected non-cycle set
        indegree = {c: 0 for c in cells_to_eval}
        adj = {c: set() for c in cells_to_eval}

        for c in cells_to_eval:
            precs = self._graph.precedents(c)
            for p in precs:
                if p in indegree:
                    # Edge p -> c
                    adj[p].add(c)
                    indegree[c] += 1

        queue = [c for c in cells_to_eval if indegree[c] == 0]
        sorted_to_eval = []

        while queue:
            u = queue.pop(0)
            sorted_to_eval.append(u)
            for v in adj[u]:
                indegree[v] -= 1
                if indegree[v] == 0:
                    queue.append(v)

        # If there are nodes left, it means there's a cycle NOT detected by cycle_cells?
        # cycle_cells should catch all cycles. If any remain, they are part of cycles not caught?
        # Or just handle leftovers by assigning #CYCLE!?
        # The spec says cycle_cells gives every cell on a cycle.
        # So any remaining in indegree > 0 implies inconsistency or missed cycle.
        # We'll assume all are processed.

        changed_cells = set(affected)

        # Evaluate in order
        for c in sorted_to_eval:
            if c in self._trees:
                tree = self._trees[c]
                # Evaluate
                # Note: self._values might contain old values for precedents not in affected set? 
                # No, precedents are either in affected set (and updated) or not affected (so they are correct).
                val = evaluate(tree, self._lookup)
                self._values[c] = val
                self.evaluations += 1

        # Cells that are NOT formulas in the affected set (e.g. the cell being set to a number)
        # have already been updated via self._values[cell] = val in the 'else' block.

        # Prepare return list: changed cells in row-major order
        # "the cells whose value may have changed" -> The spec says return the list of cells 
        # that were evaluated/changed. 
        # "set ... returns the cells whose value may have changed ... the cell itself plus every cell in its all_dependents"
        # So we return sorted(affected).

        # Sort by row then col
        result_list = sorted(affected, key=_parse_row_major_key)

        return result_list

    def get(self, name: str) -> Any:
        """Get the current value of a cell."""
        cell = _validate_cell_name(name)
        return self._values.get(cell)

    def raw(self, name: str) -> str:
        """Get the raw input of a cell."""
        cell = _validate_cell_name(name)
        return self._raw.get(cell, '')

    def cells(self) -> list[str]:
        """Get all non-empty cells in row-major order."""
        return sorted(self._raw.keys(), key=_parse_row_major_key)
