# sheet/formula.py
"""Formula parsing and evaluation for the sheet engine."""

from __future__ import annotations

import re
from typing import Any, Callable


class FormulaError(ValueError):
    """Raised when a formula cannot be parsed."""
    pass


class ErrorValue(str):
    """An error value that compares equal to its text representation."""
    pass


# Singleton error values
ERROR_VALUE = ErrorValue("#ERROR!")
CYCLE_VALUE = ErrorValue("#CYCLE!")


# ---------------------------------------------------------------------------
# AST node definitions
# ---------------------------------------------------------------------------

class ASTNode:
    """Base class for AST nodes."""
    pass


class NumberNode(ASTNode):
    """A numeric literal."""
    __slots__ = ("value",)

    def __init__(self, value: int | float):
        self.value = value

    def __repr__(self):
        return f"NumberNode({self.value!r})"


class RefNode(ASTNode):
    """A cell reference."""
    __slots__ = ("name",)

    def __init__(self, name: str):
        self.name = name  # always upper-case

    def __repr__(self):
        return f"RefNode({self.name!r})"


class UnaryNode(ASTNode):
    """A unary + or - applied to an operand."""
    __slots__ = ("op", "operand")

    def __init__(self, op: str, operand: ASTNode):
        self.op = op
        self.operand = operand

    def __repr__(self):
        return f"UnaryNode({self.op!r}, {self.operand!r})"


class BinaryNode(ASTNode):
    """A binary operation."""
    __slots__ = ("op", "left", "right")

    def __init__(self, op: str, left: ASTNode, right: ASTNode):
        self.op = op
        self.left = left
        self.right = right

    def __repr__(self):
        return f"BinaryNode({self.op!r}, {self.left!r}, {self.right!r})"


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(
    r"""
    \s+                      # whitespace (skip)
    |
    (?P<NUM>\d+(?:\.\d+)?)   # number literal
    |
    (?P<REF>[A-Za-z]+\d+)    # cell reference (letters followed by digits)
    |
    (?P<OP>[+\-*/()])        # operator or parenthesis
    |
    (?P<UNKNOWN>.)           # any other character -> error
    """,
    re.VERBOSE,
)


def _tokenize(source: str) -> list[tuple[str, str]]:
    """Return a list of (kind, text) tuples. Raises FormulaError on unknown chars."""
    tokens: list[tuple[str, str]] = []
    for match in _TOKEN_RE.finditer(source):
        if match.group("UNKNOWN") is not None:
            raise FormulaError(f"Unexpected character {match.group('UNKNOWN')!r}")
        if match.group("NUM") is not None:
            tokens.append(("NUM", match.group("NUM")))
        elif match.group("REF") is not None:
            tokens.append(("REF", match.group("REF").upper()))
        elif match.group("OP") is not None:
            tokens.append(("OP", match.group("OP")))
        # whitespace is skipped
    # Verify we covered the entire input (no leftover chars)
    # finditer should cover everything; UNKNOWN catches leftovers
    return tokens


# ---------------------------------------------------------------------------
# Parser (recursive descent)
# ---------------------------------------------------------------------------

_CELL_NAME_RE = re.compile(r"^([A-Za-z])(\d+)$")


def _validate_ref(name: str) -> None:
    """Validate that a cell reference is within A1:Z999 and properly formatted."""
    m = _CELL_NAME_RE.match(name)
    if not m:
        raise FormulaError(f"Invalid cell reference {name!r}")
    col, row_str = m.group(1), m.group(2)
    # Row must not have leading zeros (unless it's just "0", but 0 is invalid)
    if len(row_str) > 1 and row_str[0] == '0':
        raise FormulaError(f"Invalid cell reference {name!r} (leading zero in row)")
    row = int(row_str)
    if row < 1 or row > 999:
        raise FormulaError(f"Invalid cell reference {name!r} (row out of range)")
    # Column must be single letter A-Z (already enforced by regex match on single letter)
    # Actually our regex only allows single letter for col, but REF token could be multi-letter
    # Let's re-check: _CELL_NAME_RE enforces single letter. But REF token can be AA1 etc.
    # We need to handle multi-letter refs in the token check.
    pass


def _validate_ref_from_token(text: str) -> str:
    """Validate a REF token string and return upper-case name. Raise FormulaError if invalid."""
    upper = text.upper()
    # Check format: letters followed by digits
    if not re.match(r"^[A-Z]+\d+$", upper):
        raise FormulaError(f"Invalid reference format {upper!r}")
    # Extract column and row
    m = re.match(r"^([A-Z]+)(\d+)$", upper)
    if not m:
        raise FormulaError(f"Invalid reference {upper!r}")
    col_str, row_str = m.group(1), m.group(2)
    # Column must be exactly one letter
    if len(col_str) != 1:
        raise FormulaError(f"Invalid reference {upper!r} (column must be single letter)")
    # Row validation
    if len(row_str) > 1 and row_str[0] == '0':
        raise FormulaError(f"Invalid reference {upper!r} (leading zero in row)")
    row = int(row_str)
    if row < 1 or row > 999:
        raise FormulaError(f"Invalid reference {upper!r} (row out of range)")
    return upper


class _Parser:
    """Recursive descent parser for formula expressions."""

    def __init__(self, tokens: list[tuple[str, str]]):
        self.tokens = tokens
        self.pos = 0

    def _peek(self) -> tuple[str, str] | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _consume(self) -> tuple[str, str]:
        tok = self._peek()
        if tok is None:
            raise FormulaError("Unexpected end of input")
        self.pos += 1
        return tok

    def parse(self) -> ASTNode:
        if not self.tokens:
            raise FormulaError("Empty formula")
        tree = self._parse_expr()
        if self.pos < len(self.tokens):
            raise FormulaError("Unexpected trailing tokens")
        return tree

    def _parse_expr(self) -> ASTNode:
        """expr := term {(+ | -) term}"""
        node = self._parse_term()
        while True:
            tok = self._peek()
            if tok and tok == ("OP", "+") or tok == ("OP", "-"):
                self._consume()
                right = self._parse_term()
                node = BinaryNode(tok[1], node, right)
            else:
                break
        return node

    def _parse_term(self) -> ASTNode:
        """term := unary {(* | /) unary}"""
        node = self._parse_unary()
        while True:
            tok = self._peek()
            if tok and (tok == ("OP", "*") or tok == ("OP", "/")):
                self._consume()
                right = self._parse_unary()
                node = BinaryNode(tok[1], node, right)
            else:
                break
        return node

    def _parse_unary(self) -> ASTNode:
        """unary := (+ | -) unary | number | ref | ( expr )"""
        tok = self._peek()
        if tok is None:
            raise FormulaError("Unexpected end of input")
        kind, text = tok
        if kind == "OP" and text in ("+", "-"):
            self._consume()
            operand = self._parse_unary()
            return UnaryNode(text, operand)
        elif kind == "NUM":
            self._consume()
            if "." in text:
                value = float(text)
            else:
                value = int(text)
            return NumberNode(value)
        elif kind == "REF":
            self._consume()
            upper = _validate_ref_from_token(text)
            return RefNode(upper)
        elif kind == "OP" and text == "(":
            self._consume()
            node = self._parse_expr()
            # Expect closing paren
            tok2 = self._peek()
            if tok2 is None or tok2 != ("OP", ")"):
                raise FormulaError("Unbalanced parentheses")
            self._consume()
            return node
        else:
            raise FormulaError(f"Unexpected token {text!r}")


def parse_formula(source: str) -> ASTNode:
    """Parse a formula string (the text after '=') into an AST.

    Raises:
        FormulaError: if the source is empty, contains invalid characters,
                      is an incomplete expression, has unbalanced parens,
                      or contains a reference outside the sheet.
    """
    if not source or not source.strip():
        raise FormulaError("Empty formula")
    tokens = _tokenize(source)
    if not tokens:
        raise FormulaError("Empty formula")
    parser = _Parser(tokens)
    return parser.parse()


# ---------------------------------------------------------------------------
# references
# ---------------------------------------------------------------------------

def references(tree: ASTNode) -> set[str]:
    """Return the set of upper-case cell names referenced by the AST."""
    result: set[str] = set()
    _collect_refs(tree, result)
    return result


def _collect_refs(node: ASTNode, out: set[str]) -> None:
    if isinstance(node, RefNode):
        out.add(node.name)
    elif isinstance(node, UnaryNode):
        _collect_refs(node.operand, out)
    elif isinstance(node, BinaryNode):
        _collect_refs(node.left, out)
        _collect_refs(node.right, out)
    # NumberNode has no refs


# ---------------------------------------------------------------------------
# evaluate
# ---------------------------------------------------------------------------

def _is_error(value: Any) -> bool:
    """Check if a value is an ErrorValue."""
    return isinstance(value, ErrorValue)


def _is_int(value: Any) -> bool:
    """Check if value is an int (not bool)."""
    return isinstance(value, int) and not isinstance(value, bool)


def _is_float(value: Any) -> bool:
    """Check if value is a float."""
    return isinstance(value, float)


def _is_numeric(value: Any) -> bool:
    """Check if value is int or float."""
    return _is_int(value) or _is_float(value)


def _is_text(value: Any) -> bool:
    """Check if value is a plain string (not ErrorValue)."""
    return isinstance(value, str) and not isinstance(value, ErrorValue)


def _binary_arith(left_val: Any, right_val: Any, op: str) -> Any:
    """Apply a binary arithmetic operator to two already-resolved operand values.

    Returns int, float, or ErrorValue.
    """
    # If either is an error, propagate (already handled by caller for left-to-right,
    # but here we handle the case where both are non-error)
    if op == "+":
        return left_val + right_val
    elif op == "-":
        return left_val - right_val
    elif op == "*":
        return left_val * right_val
    elif op == "/":
        if right_val == 0:
            return ERROR_VALUE
        return left_val / right_val
    else:
        raise FormulaError(f"Unknown binary operator {op!r}")


def evaluate(tree: ASTNode, lookup: Callable[[str], Any]) -> Any:
    """Evaluate an AST node given a cell lookup function.

    Args:
        tree: The AST to evaluate.
        lookup: A callable that takes an upper-case cell name and returns
                the cell's current value (int, float, str, None, or ErrorValue).

    Returns:
        The computed value: int, float, str, or ErrorValue.
    """
    return _eval_node(tree, lookup)


def _eval_node(node: ASTNode, lookup: Callable[[str], Any]) -> Any:
    if isinstance(node, NumberNode):
        return node.value

    if isinstance(node, RefNode):
        val = lookup(node.name)
        # Empty cell (None) becomes 0
        if val is None:
            return 0
        return val

    if isinstance(node, UnaryNode):
        operand_val = _eval_node(node.operand, lookup)
        # If operand is an error, propagate it
        if _is_error(operand_val):
            return operand_val
        # If operand is text (non-error string), it's an error
        if _is_text(operand_val):
            return ERROR_VALUE
        # Apply unary sign
        if node.op == "-":
            return -operand_val
        elif node.op == "+":
            return operand_val
        else:
            raise FormulaError(f"Unknown unary operator {node.op!r}")

    if isinstance(node, BinaryNode):
        # Evaluate left operand first
        left_val = _eval_node(node.left, lookup)
        # Check left for error or text
        if _is_error(left_val):
            # Left is error; we still need to evaluate right to detect if it's also error
            right_val = _eval_node(node.right, lookup)
            if _is_error(right_val):
                return left_val  # left error wins
            # Left error dominates
            return left_val

        # Right operand
        right_val = _eval_node(node.right, lookup)
        if _is_error(right_val):
            return right_val

        # Both non-error: check for text
        if _is_text(left_val) or _is_text(right_val):
            return ERROR_VALUE

        # Both numeric (int or float)
        # Determine result type: / always float; others int if both int
        if node.op == "/":
            return _binary_arith(left_val, right_val, node.op)
        else:
            # For +, -, *: if both ints, result is int; if any float, result is float
            # Python's operators already do this naturally for int/float
            return _binary_arith(left_val, right_val, node.op)

    raise FormulaError(f"Unknown AST node type {type(node)}")

