from __future__ import annotations
import re
from typing import Any, Dict, Optional, Set
from .formula import parse_formula, evaluate, references, FormulaError, ErrorValue, DIV0, VALUE, REF, CYCLE
from .graph import DependencyGraph

CELL_PATTERN = re.compile(r'^([A-Z]+)(\d+)$')

class Sheet:
    def __init__(self, max_rows: int, max_cols: int):
        self.max_row = max_rows
        self.max_col = max_cols
        self.cells: Dict[str, Any] = {}
        self.formulas: Dict[str, Any] = {} # AST nodes
        self.graph = DependencyGraph()

    def is_inside(self, name: str) -> bool:
        """Check if a cell name is within the sheet dimensions."""
        if not CELL_PATTERN.match(name):
            return False
        col_str, row_str = CELL_PATTERN.match(name).groups()
        row = int(row_str)
        # Convert col to number
        col_num = 0
        for c in col_str:
            col_num = col_num * 26 + (ord(c) - ord('A') + 1)

        return 1 <= row <= self.max_row and 1 <= col_num <= self.max_col

    def _normalize_cell(self, name: str) -> str:
        """Validate and normalize cell name. Raise ValueError if invalid."""
        if not CELL_PATTERN.match(name):
            raise ValueError(f"Invalid cell name: {name}")
        name = name.upper()
        if not self.is_inside(name):
            raise ValueError(f"Cell out of bounds: {name}")
        return name

    def set_cell(self, name: str, value: Any) -> None:
        """Set the value or formula of a cell."""
        cell = self._normalize_cell(name)

        if isinstance(value, str) and value.startswith('='):
            try:
                ast = parse_formula(value[1:])
                self.formulas[cell] = ast
                # Get dependencies
                refs = references(ast)
                # Filter refs that are inside the sheet
                valid_refs = {r for r in refs if self.is_inside(r)}
                # Note: If a ref is outside, it's not a dependency in the graph 
                # (it will always be #REF! or ignored in evaluation?)
                # The prompt says "references returns only cells inside the sheet". 
                # So we only depend on valid cells.
                self.graph.set_dependencies(cell, valid_refs)
            except FormulaError:
                # If formula is invalid syntax, store as error?
                # Usually set_cell might raise FormulaError or store error.
                # Prompt doesn't specify behavior for setting invalid formula string on cell.
                # I'll assume it raises FormulaError to the caller.
                raise
        else:
            # Plain value (number, text, or error value?)
            self.formulas[cell] = None # No formula
            self.cells[cell] = value
            self.graph.set_dependencies(cell, set())

        self.recalculate()

