"""Formula parsing and evaluation for the sheet engine."""

from __future__ import annotations

import re
from typing import Any, Callable, Optional


class FormulaError(ValueError):
    """Raised when a formula cannot be parsed."""
    pass


class ErrorValue(str):
    """An error value that compares equal to its text representation."""
    pass


# Singleton error values
DIV0_VALUE = ErrorValue("#DIV/0!")
VALUE_VALUE = ErrorValue("#VALUE!")
REF_VALUE = ErrorValue("#REF!")
CYCLE_VALUE = ErrorValue("#CYCLE!")

# Function names set
FUNCTION_NAMES = {"SUM", "AVG", "MIN", "MAX"}


# ---------------------------------------------------------------------------
# AST node definitions
# ---------------------------------------------------------------------------

class ASTNode:
    """Base class for AST nodes."""
    pass


class NumberNode(ASTNode):
    """A numeric literal."""
    __slots__ = ("value",)

    def __init__(self, value: int | float):
        self.value = value

    def __repr__(self):
        return f"NumberNode({self.value!r})"


class RefNode(ASTNode):
    """A cell reference."""
    __slots__ = ("name",)

    def __init__(self, name: str):
        self.name = name  # always upper-case

    def __repr__(self):
        return f"RefNode({self.name!r})"


class UnaryNode(ASTNode):
    """A unary + or - applied to an operand."""
    __slots__ = ("op", "operand")

    def __init__(self, op: str, operand: ASTNode):
        self.op = op
        self.operand = operand

    def __repr__(self):
        return f"UnaryNode({self.op!r}, {self.operand!r})"


class BinaryNode(ASTNode):
    """A binary operation."""
    __slots__ = ("op", "left", "right")

    def __init__(self, op: str, left: ASTNode, right: ASTNode):
        self.op = op
        self.left = left
        self.right = right

    def __repr__(self):
        return f"BinaryNode({self.op!r}, {self.left!r}, {self.right!r})"


class CallNode(ASTNode):
    """A function call."""
    __slots__ = ("name", "args")

    def __init__(self, name: str, args: list[ASTNode]):
        self.name = name  # Upper-case function name
        self.args = args

    def __repr__(self):
        return f"CallNode({self.name!r}, {self.args!r})"


class RangeNode(ASTNode):
    """A range between two references."""
    __slots__ = ("start", "end")

    def __init__(self, start: RefNode, end: RefNode):
        self.start = start
        self.end = end

    def __repr__(self):
        return f"RangeNode({self.start!r}, {self.end!r})"


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(
    r"""
    \s+  # whitespace (skip)
    |
    (?P<NUM>\d+(?:\.\d+)?)   # number literal
    |
    (?P<REF>[A-Za-z]+\d+)    # cell reference
    |
    (?P<IDENT>[A-Za-z]+)     # identifier (potential function name)
    |
    (?P<OP>[+\-*/(),:])      # operator or parenthesis
    |
    (?P<UNKNOWN>.)           # any other character -> error
    """,
    re.VERBOSE,
)


def _tokenize(source: str) -> list[tuple[str, str]]:
    """Return a list of (kind, text) tuples. Raises FormulaError on unknown chars."""
    tokens: list[tuple[str, str]] = []
    for match in _TOKEN_RE.finditer(source):
        if match.group("UNKNOWN") is not None:
            raise FormulaError(f"Unexpected character {match.group('UNKNOWN')!r}")
        if match.group("NUM") is not None:
            tokens.append(("NUM", match.group("NUM")))
        elif match.group("REF") is not None:
            tokens.append(("REF", match.group("REF").upper()))
        elif match.group("IDENT") is not None:
            tokens.append(("IDENT", match.group("IDENT").upper()))
        elif match.group("OP") is not None:
            tokens.append(("OP", match.group("OP")))
        # whitespace is skipped
    return tokens


# ---------------------------------------------------------------------------
# Parser (recursive descent)
# ---------------------------------------------------------------------------

class _Parser:
    """Recursive descent parser for formula expressions."""

    def __init__(self, tokens: list[tuple[str, str]]):
        self.tokens = tokens
        self.pos = 0

    def _peek(self) -> tuple[str, str] | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _consume(self) -> tuple[str, str]:
        tok = self._peek()
        if tok is None:
            raise FormulaError("Unexpected end of input")
        self.pos += 1
        return tok

    def parse(self) -> ASTNode:
        if not self.tokens:
            raise FormulaError("Empty formula")
        tree = self._parse_expr()
        if self.pos < len(self.tokens):
            raise FormulaError("Unexpected trailing tokens")
        return tree

    def _parse_expr(self) -> ASTNode:
        """expr := term {(+ | -) term}"""
        node = self._parse_term()
        while True:
            tok = self._peek()
            if tok and tok[0] == "OP" and tok[1] in ("+", "-"):
                self._consume()
                right = self._parse_term()
                node = BinaryNode(tok[1], node, right)
            else:
                break
        return node

    def _parse_term(self) -> ASTNode:
        """term := unary {(* | /) unary}"""
        node = self._parse_unary()
        while True:
            tok = self._peek()
            if tok and tok[0] == "OP" and tok[1] in ("*", "/"):
                self._consume()
                right = self._parse_unary()
                node = BinaryNode(tok[1], node, right)
            else:
                break
        return node

    def _parse_unary(self) -> ASTNode:
        """unary := (+ | -) unary | number | ref | call | ( expr )"""
        tok = self._peek()
        if tok is None:
            raise FormulaError("Unexpected end of input")
        kind, text = tok

        if kind == "OP" and text in ("+", "-"):
            self._consume()
            operand = self._parse_unary()
            return UnaryNode(text, operand)

        elif kind == "NUM":
            self._consume()
            if "." in text:
                value = float(text)
            else:
                value = int(text)
            return NumberNode(value)

        elif kind == "IDENT":
            # Potential function call
            func_name = text.upper()
            if func_name not in FUNCTION_NAMES:
                raise FormulaError(f"Unknown function name {text!r}")

            # Consume function name
            self._consume()

            # Expect '('
            tok2 = self._peek()
            if tok2 is None or tok2 != ("OP", "("):
                raise FormulaError(f"Expected '(' after function name {text!r}")
            self._consume()

            args = self._parse_args()

            # Expect ')'
            tok3 = self._peek()
            if tok3 is None or tok3 != ("OP", ")"):
                raise FormulaError("Unbalanced parentheses")
            self._consume()

            return CallNode(func_name, args)

        elif kind == "REF":
            self._consume()
            return RefNode(text)

        elif kind == "OP" and text == "(":
            self._consume()
            node = self._parse_expr()
            # Expect closing paren
            tok2 = self._peek()
            if tok2 is None or tok2 != ("OP", ")"):
                raise FormulaError("Unbalanced parentheses")
            self._consume()
            return node

        else:
            raise FormulaError(f"Unexpected token {text!r}")

    def _parse_args(self) -> list[ASTNode]:
        """arg_list := arg {, arg}"""
        args = []

        # Check for empty args
        tok = self._peek()
        if tok and tok[0] == "OP" and tok[1] == ")":
            raise FormulaError("Function call requires at least one argument")

        while True:
            arg = self._parse_arg()
            args.append(arg)

            tok = self._peek()
            if tok and tok[0] == "OP" and tok[1] == ",":
                self._consume()
                continue
            else:
                break

        return args

    def _parse_arg(self) -> ASTNode:
        """arg := ref : ref | expr"""
        tok = self._peek()
        # Check for Range: REF : REF
        if tok and tok[0] == "REF":
            # Peek ahead to see if there is a ':'
            if self.pos + 1 < len(self.tokens):
                next_tok = self.tokens[self.pos + 1]
                if next_tok[0] == "OP" and next_tok[1] == ":":
                    # Parse range
                    start_tok = self._consume() # REF
                    start_ref = RefNode(start_tok[1])
                    self._consume() # : 
                    end_tok = self._peek()
                    if end_tok is None or end_tok[0] != "REF":
                        raise FormulaError("Expected reference after ':'")
                    self._consume() # REF
                    end_ref = RefNode(end_tok[1])
                    return RangeNode(start_ref, end_ref)

        # Otherwise, parse as expression
        return self._parse_expr()


def parse_formula(source: str) -> ASTNode:
    """Parse a formula string (the text after '=') into an AST.

    Raises:
        FormulaError: if the source is empty, contains invalid characters,
                      is an incomplete expression, has unbalanced parens,
                      or contains a syntax violation.
    """
    if not source or not source.strip():
        raise FormulaError("Empty formula")
    tokens = _tokenize(source)
    if not tokens:
        raise FormulaError("Empty formula")
    parser = _Parser(tokens)
    return parser.parse()


# ---------------------------------------------------------------------------
# Helper: Column/Letter Conversion
# ---------------------------------------------------------------------------

def _col_to_num(col: str) -> int:
    """Convert column letters to number (A=1, Z=26, AA=27)."""
    result = 0
    for char in col:
        result = result * 26 + (ord(char) - ord('A') + 1)
    return result

def _num_to_col(num: int) -> str:
    """Convert number to column letters."""
    result = []
    while num > 0:
        num, rem = divmod(num - 1, 26)
        result.append(chr(rem + ord('A')))
    return "".join(reversed(result))

def _parse_ref(ref: str) -> tuple[int, int]:
    """Parse 'AB12' into (col_num, row_num). Returns None if invalid structure for range."""
    match = re.match(r"^([A-Z]+)(\d+)$", ref)
    if not match:
        return None
    return _col_to_num(match.group(1)), int(match.group(2))

def _expand_range(start: str, end: str) -> list[str]:
    """Expand range A1:B2 to ['A1', 'A2', 'B1', 'B2'] (row-major)."""
    p1 = _parse_ref(start)
    p2 = _parse_ref(end)
    if not p1 or not p2:
        return []

    c1, r1 = p1
    c2, r2 = p2

    min_c, max_c = min(c1, c2), max(c1, c2)
    min_r, max_r = min(r1, r2), max(r1, r2)

    cells = []
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            cells.append(f"{_num_to_col(c)}{r}")
    return cells

# ---------------------------------------------------------------------------
# references
# ---------------------------------------------------------------------------

def references(tree: ASTNode) -> set[str]:
    """Return the set of upper-case cell names referenced by the AST.

    Note: This implementation expands ranges to include all cells in them.
    Filtering for 'inside the sheet' must be done by the caller (Sheet) if 
    strict bounds are required, or by passing dimensions if the signature allowed.
    """
    result: set[str] = set()
    _collect_refs(tree, result)
    return result


def _collect_refs(node: ASTNode, out: set[str]) -> None:
    if isinstance(node, RefNode):
        out.add(node.name)
    elif isinstance(node, RangeNode):
        # Expand range
        cells = _expand_range(node.start.name, node.end.name)
        out.update(cells)
    elif isinstance(node, UnaryNode):
        _collect_refs(node.operand, out)
    elif isinstance(node, BinaryNode):
        _collect_refs(node.left, out)
        _collect_refs(node.right, out)
    elif isinstance(node, CallNode):
        for arg in node.args:
            _collect_refs(arg, out)
    # NumberNode has no refs


# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------

# Type hint for the cell getter: takes (sheet_context, name) -> value
# sheet_context must provide dimensions for #REF! checks
CellGetter = Callable[[Any, str], Any]

def evaluate(tree: ASTNode, get_cell: CellGetter, sheet_ctx: Any) -> Any:
    """Evaluate the AST tree using the provided cell getter and sheet context.

    sheet_ctx should have 'max_row' and 'max_col' (1-based) for #REF! checks.
    If sheet_ctx is None, #REF! checks might be skipped or assumed valid.
    """
    return _eval_node(tree, get_cell, sheet_ctx)

def _check_ref_valid(name: str, sheet_ctx: Any) -> bool:
    if sheet_ctx is None:
        return True # Assume valid if no context provided (backward compat)
    if not re.match(r"^[A-Z]+\d+$", name):
        return False

    match = re.match(r"^([A-Z]+)(\d+)$", name)
    if not match:
        return False

    col_str, row_str = match.group(1), match.group(2)
    row = int(row_str)
    col = _col_to_num(col_str)

    # Check bounds
    if row < 1 or row > sheet_ctx.max_row:
        return False
    if col < 1 or col > sheet_ctx.max_col:
        return False

    return True

def _eval_node(node: ASTNode, get_cell: CellGetter, sheet_ctx: Any) -> Any:
    if isinstance(node, NumberNode):
        return node.value

    elif isinstance(node, RefNode):
        # Check for #REF!
        if not _check_ref_valid(node.name, sheet_ctx):
            return REF_VALUE
        val = get_cell(sheet_ctx, node.name)
        # If cell itself is an error, propagate it (usually)
        # If cell is None/Empty, how is it treated? 
        # Prompt: "A cell holding a number is collected... text cell is skipped... error value makes that error the call's result."
        # For binary ops: "if any is an error value the result is the leftmost error".
        # If cell is empty/None, in arithmetic it's often 0 or #VALUE!. 
        # Standard: Empty cell is 0 in arithmetic. 
        if val is None:
            return 0
        return val

    elif isinstance(node, UnaryNode):
        val = _eval_node(node.operand, get_cell, sheet_ctx)
        if isinstance(val, ErrorValue):
            return val
        if not isinstance(val, (int, float)):
            return VALUE_VALUE

        if node.op == '-':
            return -val
        else: # '+'
            return val

    elif isinstance(node, BinaryNode):
        left = _eval_node(node.left, get_cell, sheet_ctx)

        # Left-to-right evaluation: check left first
        if isinstance(left, ErrorValue):
            # We still need to evaluate right? 
            # Prompt: "operands are evaluated left to right... if any is an error... result is leftmost"
            # If left is error, result is that error. We technically don't need right value for result, 
            # but side effects? No side effects. But strict spec might require evaluating right for cycles? 
            # "errors propagate... left to right". Usually short-circuit is okay if no side effects, 
            # but for cycle detection in dependencies, we already have the graph. 
            # However, if right is also error, leftmost wins. So we can return left immediately IF left is not #VALUE! derived from text? 
            # No, if left is #VALUE! (text), we return it. 
            # But what if left is #REF! and right is #DIV/0!? Left wins. Return Left.
            # What if left is number, right is error? Return Right.
            return left

        right = _eval_node(node.right, get_cell, sheet_ctx)

        if isinstance(right, ErrorValue):
            return right

        if not isinstance(left, (int, float)) or not isinstance(right, (int, float)):
            return VALUE_VALUE

        try:
            if node.op == '+':
                return left + right
            elif node.op == '-':
                return left - right
            elif node.op == '*':
                return left * right
            elif node.op == '/':
                if right == 0:
                    return DIV0_VALUE
                return left / right
        except ZeroDivisionError:
            return DIV0_VALUE

    elif isinstance(node, RangeNode):
        # Ranges are only allowed as arguments to functions.
        # If we hit a range in normal eval context, it's an error? 
        # Grammar: arg := ref : ref | expr. 
        # So RangeNode is an argument type.
        # If it appears elsewhere, it's invalid syntax handled by parser? 
        # Parser only allows RangeNode in args. 
        # But if we eval it standalone? 
        # The spec says "Ranges are allowed only as function arguments."
        # If this is reached, it's likely via CallNode evaluation path. 
        # If reached via direct eval of a range expression (not in call), it's ambiguous. 
        # Assuming we are inside a call argument evaluation.
        # For a single ref arg or range arg, we return a special list/marker? 
        # No, CallNode eval handles args specifically.
        # If we evaluate a RangeNode directly as an expression (e.g. in binary op), it's #VALUE! or similar.
        return VALUE_VALUE

    elif isinstance(node, CallNode):
        return _eval_call(node, get_cell, sheet_ctx)

    raise FormulaError(f"Unknown node type: {type(node)}")

def _eval_call(node: CallNode, get_cell: CellGetter, sheet_ctx: Any) -> Any:
    numbers = []

    for arg in node.args:
        if isinstance(arg, RangeNode):
            # Expand range
            refs = _expand_range(arg.start.name, arg.end.name)

            for ref_name in refs:
                # Check bounds for each cell in range? 
                # "A range with a corner outside the sheet gives #REF!" 
                # Strictly: if the *range definition* has a corner outside, the whole call fails with #REF!?
                # "A range whose corners are both inside... contributes cells... A range with a corner outside... gives #REF!"
                if not _check_ref_valid(arg.start.name, sheet_ctx) or not _check_ref_valid(arg.end.name, sheet_ctx):
                    return REF_VALUE

                val = get_cell(sheet_ctx, ref_name)
                if val is None:
                    continue # Skip empty
                if isinstance(val, ErrorValue):
                    return val # Error propagates immediately?
                    # Prompt: "a cell holding an error value makes that error the call's result."
                    # This implies we return that error immediately.
                if isinstance(val, str):
                    # Text cells are skipped
                    continue
                if isinstance(val, (int, float)):
                    numbers.append(val)
                else:
                    # Unexpected type? Treat as skipped or error?
                    # "text... is skipped". Other types? Probably skipped or error.
                    continue

        else:
            # Evaluate as expression
            val = _eval_node(arg, get_cell, sheet_ctx)

            if isinstance(val, ErrorValue):
                return val
            if isinstance(val, str):
                # Text in argument expression -> #VALUE!
                return VALUE_VALUE
            if isinstance(val, (int, float)):
                numbers.append(val)
            else:
                return VALUE_VALUE

    # Compute function result
    if not numbers:
        if node.name == "SUM":
            return 0
        elif node.name == "AVG":
            return DIV0_VALUE
        elif node.name == "MIN":
            return 0
        elif node.name == "MAX":
            return 0

    if node.name == "SUM":
        # Int sum if all int, else float
        has_float = any(isinstance(n, float) for n in numbers)
        total = sum(numbers)
        if has_float:
            return float(total)
        return int(total)

    elif node.name == "AVG":
        return float(sum(numbers)) / len(numbers)

    elif node.name == "MIN":
        return min(numbers)

    elif node.name == "MAX":
        return max(numbers)

    return VALUE_VALUE
