```python
from __future__ import annotations
import re
from typing import Any, List, Union, Optional

# Error classes and instances
class ErrorValue(str):
    """Represents an error value in the spreadsheet."""
    pass

DIV0 = ErrorValue("#DIV/0!")
VALUE = ErrorValue("#VALUE!")
REF = ErrorValue("#REF!")
CYCLE = ErrorValue("#CYCLE!")

class FormulaError(Exception):
    """Raised when a formula cannot be parsed."""
    pass

# AST Nodes
class ASTNode:
    pass

class NumberNode(ASTNode):
    def __init__(self, value: float):
        self.value = value

class StringNode(ASTNode):
    def __init__(self, value: str):
        self.value = value

class RefNode(ASTNode):
    def __init__(self, name: str):
        self.name = name # e.g. "A1"

class UnaryNode(ASTNode):
    def __init__(self, op: str, operand: ASTNode):
        self.op = op
        self.operand = operand

class BinaryNode(ASTNode):
    def __init__(self, op: str, left: ASTNode, right: ASTNode):
        self.op = op
        self.left = left
        self.right = right

class CallNode(ASTNode):
    def __init__(self, name: str, args: List[ASTNode]):
        self.name = name
        self.args = args

class RangeNode(ASTNode):
    def __init__(self, start: RefNode, end: RefNode):
        self.start = start
        self.end = end

# Regex patterns
REF_PATTERN = re.compile(r'^([A-Za-z]+)(\d+)$')

# Helper for column letters
def _col_to_num(col: str) -> int:
    result = 0
    for char in col:
        result = result * 26 + (ord(char) - ord('A') + 1)
    return result

def _num_to_col(num: int) -> str:
    result = []
    while num > 0:
        num, rem = divmod(num - 1, 26)
        result.append(chr(rem + ord('A')))
    return "".join(reversed(result))

def _parse_ref(ref: str) -> Optional[tuple[int, int]]:
    """Parse 'AB12' into (col_num, row_num)."""
    match = REF_PATTERN.match(ref)
    if not match:
        return None
    return _col_to_num(match.group(1).upper()), int(match.group(2))

def _expand_range(start: str, end: str) -> List[str]:
    """Expand range A1:B2 to ['A1', 'B1', 'A2', 'B2'] (row-major)."""
    p1 = _parse_ref(start)
    p2 = _parse_ref(end)
    if not p1 or not p2:
        return []

    c1, r1 = p1
    c2, r2 = p2

    min_c, max_c = min(c1, c2), max(c1, c2)
    min_r, max_r = min(r1, r2), max(r1, r2)

    cells = []
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            cells.append(f"{_num_to_col(c)}{r}")
    return cells

def parse_formula(text: str) -> ASTNode:
    class Parser:
        def __init__(self, text: str):
            self.text = text
            self.pos = 0
            self.length = len(text)

        def parse(self) -> ASTNode:
            node = self.parse_expression()
            self.skip_ws()
            if self.pos < self.length:
                raise FormulaError("Unexpected characters")
            return node

        def skip_ws(self):
            while self.pos < self.length and self.text[self.pos].isspace():
                self.pos += 1

        def parse_expression(self) -> ASTNode:
            return self.parse_binary()

        def parse_binary(self) -> ASTNode:
            left = self.parse_unary()
            while True:
                self.skip_ws()
                if self.pos >= self.length:
                    break
                char = self.text[self.pos]
                if char in ('+', '-', '*', '/'):
                    op = char
                    self.pos += 1
                    right = self.parse_unary()
                    left = BinaryNode(op, left, right)
                else:
                    break
            return left

        def parse_unary(self) -> ASTNode:
            self.skip_ws()
            if self.pos >= self.length:
                raise FormulaError("Unexpected end of formula")
            char = self.text[self.pos]
            if char in ('+', '-'):
                op = char
                self.pos += 1
                operand = self.parse_unary()
                return UnaryNode(op, operand)
            else:
                return self.parse_primary()

        def parse_primary(self) -> ASTNode:
            self.skip_ws()
            if self.pos >= self.length:
                raise FormulaError("Unexpected end of formula")

            if self.text[self.pos] == '(':
                self.pos += 1
                node = self.parse_expression()
                self.skip_ws()
                if self.pos >= self.length or self.text[self.pos] != ')':
                    raise FormulaError("Expected )")
                self.pos += 1
                return node

            # Check for String
            if self.text[self.pos] == '"':
                self.pos += 1
                start = self.pos
                while self.pos < self.length and self.text[self.pos] != '"':
                    self.pos += 1
                if self.pos >= self.length:
                    raise FormulaError("Unterminated string")
                val = self.text[start:self.pos]
                self.pos += 1 
                return StringNode(val)

            # Tokenize alphanumeric part for Ref or Function or Number
            start_pos = self.pos
            while self.pos < self.length:
                c = self.text[self.pos]
                if c.isalnum() or c == '.':
                    self.pos += 1
                else:
                    break

            token = self.text[start_pos:self.pos]
            if not token:
                raise FormulaError("Invalid syntax")

            # Check for Function Name
            self.skip_ws()
            if self.pos < self.length and self.text[self.pos] == '(':
                fname = token.upper()
                if fname not in ('SUM', 'AVG', 'MIN', 'MAX'):
                    raise FormulaError(f"Unknown function {fname}")
                self.pos += 1 # skip (
                args = self.parse_args()
                self.skip_ws()
                if self.pos >= self.length or self.text[self.pos] != ')':
                    raise FormulaError("Expected )")
                self.pos += 1 # skip )
                return CallNode(fname, args)

            # Check for Reference or Number
            # Ref pattern: letters then digits
            match = REF_PATTERN.match(token)
            if match:
                return RefNode(token.upper())

            # Try number
            try:
                if '.' in token:
                    return NumberNode(float(token))
                else:
                    # Prompt implies int if no dot? But sheet usually handles floats.
                    # Let's stick to float for numbers unless strictly int needed.
                    # "SUM gives their sum: an int when all are ints"
                    # So we need to track if it was int.
                    return NumberNode(int(token) if token.isdigit() else float(token))
            except ValueError:
                raise FormulaError(f"Invalid token {token}")

        def parse_args(self) -> List[ASTNode]:
            args = []
            self.skip_ws()
            if self.pos < self.length and self.text[self.pos] == ')':
                raise FormulaError("Call with no arguments")

            while True:
                self.skip_ws()
                arg = self.parse_arg()
                args.append(arg)

                self.skip_ws()
                if self.pos < self.length and self.text[self.pos] == ',':
                    self.pos += 1
                    continue
                else:
                    break
            return args

        def parse_arg(self) -> ASTNode:
            self.skip_ws()
            # Check for Range: Ref : Ref
            start_pos = self.pos

            # Peek for Ref pattern
            m = REF_PATTERN.match(self.text[self.pos:])
            if m:
                ref1_text = m.group(0)
                next_pos = self.pos + len(ref1_text)

                # Skip whitespace
                while next_pos < self.length and self.text[next_pos] == ' ':
                    next_pos += 1

                if next_pos < self.length and self.text[next_pos] == ':':
                    # It is a range!
                    self.pos = next_pos + 1 # skip :
                    self.skip_ws()

                    m2 = REF_PATTERN.match(self.text[self.pos:])
                    if not m2:
                        raise FormulaError("Invalid range argument")

                    ref2_text = m2.group(0)
                    self.pos += len(ref2_text)

                    return RangeNode(RefNode(ref1_text.upper()), RefNode(ref2_text.upper()))

            # Not a range, parse as expression
            return self.parse_expression()

    return Parser(text).parse()

def references(node: ASTNode) -> List[str]:
    """Return list of cell references (expanded ranges). Does not filter bounds."""
    refs = []
    def walk(n):
        if isinstance(n, RefNode):
            refs.append(n.name)
        elif isinstance(n, RangeNode):
            refs.extend(_expand_range(n.start.name, n.end.name))
        elif isinstance(n, UnaryNode):
            walk(n.operand)
        elif isinstance(n, BinaryNode):
            walk(n.left)
            walk(n.right)
        elif isinstance(n, CallNode):
            for arg in n.args:
                walk(arg)
        # StringNode, NumberNode do nothing

    walk(node)
    # Unique and sorted? "row-major order" is handled by expansion, but multiple refs might overlap.
    # Usually unique list is expected for dependencies.
    return list(dict.fromkeys(refs))


def evaluate(node: ASTNode, sheet) -> Any:
    """Evaluate the AST. sheet provides cell values and dimensions."""

    if isinstance(node, NumberNode):
        return node.value

    if isinstance(node, StringNode):
        return node.value

    if isinstance(node, RefNode):
        name = node.name
        if not sheet.is_inside(name):
            return REF
        val = sheet.get_raw(name)
        if isinstance(val, ErrorValue):
            return val
        if val is None:
            return 0 # Empty cell is 0 in arithmetic
        if isinstance(val, str):
            return VALUE # Text is #VALUE! in general expression
        return val

    if isinstance(node, UnaryNode):
        val = evaluate(node.operand, sheet)
        if isinstance(val, ErrorValue):
            return val
        if isinstance(val, str):
            return VALUE
        if node.op == '-':
            return -val
        return val

    if isinstance(node, BinaryNode):
        left_val = evaluate(node.left, sheet)
        # Evaluate left first. If error, return it.
        if isinstance(left_val, ErrorValue):
            return left_val

        right_val = evaluate(node.right, sheet)
        if isinstance(right_val, ErrorValue):
            return right_val

        # If either is string -> #VALUE! (Prompt: "text used where a number is needed")
        # But wait, if left was error, we returned. 
        # If left is string? "an operand of + - * / ... gives #VALUE!".
        # So if left_val is str, return VALUE.
        if isinstance(left_val, str):
            return VALUE
        if isinstance(right_val, str):
            return VALUE

        # Division by zero
        if node.op == '/' and right_val == 0:
            return DIV0

        if node.op == '+':
            return left_val + right_val
        if node.op == '-':
            return left_val - right_val
        if node.op == '*':
            return left_val * right_val
        if node.op == '/':
            return left_val / right_val

    if isinstance(node, RangeNode):
        # Ranges outside of function calls are invalid syntax? 
        # Prompt: "Ranges are allowed only as function arguments." 
        # If parse formula allows it, it might reach here. But parser should restrict.
        # If it does, treat as error? Or #REF? 
        # The parser implementation above restricts it inside parse_arg. 
        # So we might not hit this unless there's a bug or I missed a path.
        # But if we do, maybe #VALUE!?
        return VALUE

    if isinstance(node, CallNode):
        fname = node.name
        collected_numbers = []
        first_error = None

        # Process arguments in order
        for arg in node.args:
            # If arg is RefNode or RangeNode, it's a "range-like" arg.
            # "An argument that is a single reference ... is treated as a one-cell range, so text in it is skipped."
            # "Any other argument is evaluated as an expression. ... text gives #VALUE!"

            if isinstance(arg, RefNode):
                cells = [arg.name]
            elif isinstance(arg, RangeNode):
                cells = _expand_range(arg.start.name, arg.end.name)
                # Check if corners are inside? 
                # "A range with a corner outside the sheet gives #REF!"
                # So we check corners first. If outside, return REF immediately?
                # Or does evaluation proceed? "The call's result is the first error met in this order."
                # So if corner outside, #REF! is the error met for this arg.
                if not sheet.is_inside(arg.start.name) or not sheet.is_inside(arg.end.name):
                    return REF
            else:
                # Other expression arg
                val = evaluate(arg, sheet)
                if isinstance(val, ErrorValue):
                    return val
                if isinstance(val, str):
                    return VALUE
                # It's a number
                collected_numbers.append(val)
                continue

            # Process cells for Ref or Range arg
            for cell_name in cells:
                if not sheet.is_inside(cell_name):
                    # Should have been caught by corner check for ranges? 
                    # For single refs, RefNode check happens in evaluate()? 
                    # No, in the loop above I handled RefNode as cells=[name]. 
                    # I should check is_inside for each cell?
                    # Actually for RefNode, I didn't check bounds in the 'if isinstance(arg, RefNode)' block. 
                    # I only added cells. The bounds check happens in the loop below.
                    pass

                val = sheet.get_raw(cell_name)

                # Skip empty
                if val is None:
                    continue

                # Error?
                if isinstance(val, ErrorValue):
                    return val

                # Text? "an empty cell or a text cell is skipped"
                if isinstance(val, str):
                    continue

                # Number?
                if isinstance(val, (int, float)):
                    collected_numbers.append(val)
                else:
                    # Should not happen in standard types
                    pass

        # Compute result
        if fname == 'SUM':
            if not collected_numbers:
                return 0
            # Sum of numbers. Int if all int.
            s = sum(collected_numbers)
            # Check if all were int? Python sum of ints is int. If float present, float.
            # But if they were 1.0, 2.0 (floats) -> 3.0. 
            # Prompt: "int when all are ints, else a float"
            # My collector added values from sheet.get_raw which could be int or float.
            # So sum() works.
            return s

        elif fname == 'AVG':
            if not collected_numbers:
                return DIV0
            return sum(collected_numbers) / len(collected_numbers)

        elif fname == 'MIN':
            if not collected_numbers:
                return 0
            return min(collected_numbers)

        elif fname == 'MAX':
            if not collected_numbers:
                return 0
            return max(collected_numbers)

    return 0
