from __future__ import annotations
from typing import Dict, Set, List, Optional

class DependencyGraph:
    """Tracks cell dependencies and calculates recalculation order and cycles."""

    def __init__(self):
        self._prec: Dict[str, Set[str]] = {}  # cell -> set of precedents
        self._dep: Dict[str, Set[str]] = {}   # cell -> set of dependents

    def set_dependencies(self, cell: str, precedents: Set[str]) -> None:
        """Update dependencies for a cell."""
        # Remove old links
        old_prec = self._prec.get(cell, set())
        for p in old_prec:
            if p in self._dep:
                self._dep[p].discard(cell)

        self._prec[cell] = precedents
        for p in precedents:
            if p not in self._dep:
                self._dep[p] = set()
            self._dep[p].add(cell)

    def precedents(self, cell: str) -> Set[str]:
        """Return cells that this cell depends on."""
        return set(self._prec.get(cell, set()))

    def dependents(self, cell: str) -> Set[str]:
        """Return cells that depend on this cell."""
        return set(self._dep.get(cell, set()))

    def all_dependents(self, cell: str) -> Set[str]:
        """Return all cells that depend on this cell (transitive)."""
        # This method is useful for triggering updates, but Sheet might use
        # a topological sort for recalculation. 
        visited = set()
        queue = [cell]
        while queue:
            c = queue.pop(0)
            for d in self._dep.get(c, set()):
                if d not in visited:
                    visited.add(d)
                    queue.append(d)
        return visited

    def topological_sort(self) -> List[str]:
        """Return cells in a valid evaluation order (Kahn's algorithm)."""
        in_degree = {cell: 0 for cell in self._prec}
        for deps in self._dep.values():
            for d in deps:
                in_degree[d] = in_degree.get(d, 0) + 1

        # Only consider cells that exist in the graph structure
        # But _prec keys are all cells with formulas. 
        # We need to ensure we process cells that might be leaves (only in _dep?) 
        # Actually, if a cell has no precedents, it's in _prec with empty set? 
        # Yes, set_dependencies always sets _prec[cell].

        queue = [c for c in self._prec if in_degree[c] == 0]
        order = []

        while queue:
            c = queue.pop(0)
            order.append(c)
            for d in self._dep.get(c, set()):
                if d in in_degree:
                    in_degree[d] -= 1
                    if in_degree[d] == 0:
                        queue.append(d)

        return order

    def cycle_cells(self) -> Set[str]:
        """Find all cells involved in cycles (including self-loops)."""
        # Use Tarjan's or simple DFS coloring
        WHITE, GRAY, BLACK = 0, 1, 2
        color = {cell: WHITE for cell in self._prec}
        cycle_nodes = set()

        def dfs(u):
            color[u] = GRAY
            for v in self._prec.get(u, set()):
                # If v is not in _prec (e.g. a constant cell), it has no deps, so no cycle back
                if v not in color:
                    continue
                if color[v] == GRAY:
                    # Back edge
                    cycle_nodes.add(u)
                    cycle_nodes.add(v)
                elif color[v] == WHITE:
                    dfs(v)
            color[u] = BLACK

        for cell in self._prec:
            if color[cell] == WHITE:
                dfs(cell)

        # Note: The above detects nodes in cycles. 
        # A simple back-edge detection marks the nodes on the cycle.
        # To be safe, we can also check self-dependency explicitly.
        for cell in self._prec:
            if cell in self._prec.get(cell, set()):
                cycle_nodes.add(cell)

        return cycle_nodes
