                if c == cell:
                    found_cycle_back_to_self = True
                    continue
                if c not in visited:
                    visited.add(c)
                    result.add(c)
                    next_current.update(self._dep.get(c, set()))
            current = next_current

        if found_cycle_back_to_self:
            result.add(cell)

        return result

    def cycle_cells(self) -> set[str]:
        # Collect all unique nodes in the graph
        all_nodes = set(self._prec.keys())
        for deps in self._dep.values():
            all_nodes.update(deps)

        indices = {}
        lowlink = {}
        stack = []
        on_stack = set()
        index_counter = 0
        sccs = []

        def strongconnect(v):
            nonlocal index_counter
            indices[v] = index_counter
            lowlink[v] = index_counter
            index_counter += 1
            stack.append(v)
            on_stack.add(v)

            for w in self._prec.get(v, set()):
                if w not in indices:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif w in on_stack:
                    lowlink[v] = min(lowlink[v], indices[w])

            if lowlink[v] == indices[v]:
                scc = []
                while True:
                    w = stack.pop()
                    on_stack.remove(w)
                    scc.append(w)
                    if w == v:
                        break
                sccs.append(scc)

        for v in all_nodes:
            if v not in indices:
                strongconnect(v)

        result = set()
        for scc in sccs:
            if len(scc) > 1:
                result.update(scc)
            elif len(scc) == 1:
                cell = scc[0]
                if cell in self._prec.get(cell, set()):
                    result.add(cell)

        return result
