# Evaluation
# ---------------------------------------------------------------------------

# Type hint for the cell getter: takes (sheet_context, name) -> value
# sheet_context must provide dimensions for #REF! checks
CellGetter = Callable[[Any, str], Any]

def evaluate(tree: ASTNode, get_cell: CellGetter, sheet_ctx: Any) -> Any:
    """Evaluate the AST tree using the provided cell getter and sheet context.

    sheet_ctx should have 'max_row' and 'max_col' (1-based) for #REF! checks.
    If sheet_ctx is None, #REF! checks might be skipped or assumed valid.
    """
    return _eval_node(tree, get_cell, sheet_ctx)

def _check_ref_valid(name: str, sheet_ctx: Any) -> bool:
    if sheet_ctx is None:
        return True # Assume valid if no context provided (backward compat)
    if not re.match(r"^[A-Z]+\d+$", name):
        return False

    match = re.match(r"^([A-Z]+)(\d+)$", name)
    if not match:
        return False

    col_str, row_str = match.group(1), match.group(2)
    row = int(row_str)
    col = _col_to_num(col_str)

    # Check bounds
    if row < 1 or row > sheet_ctx.max_row:
        return False
    if col < 1 or col > sheet_ctx.max_col:
        return False

    return True

def _eval_node(node: ASTNode, get_cell: CellGetter, sheet_ctx: Any) -> Any:
    if isinstance(node, NumberNode):
        return node.value

    elif isinstance(node, RefNode):
        # Check for #REF!
        if not _check_ref_valid(node.name, sheet_ctx):
            return REF_VALUE
