        # If cell itself is an error, propagate it (usually)
        # If cell is None/Empty, how is it treated? 
        # Prompt: "A cell holding a number is collected... text cell is skipped... error value makes that error the call's result."
        # For binary ops: "if any is an error value the result is the leftmost error".
        # If cell is empty/None, in arithmetic it's often 0 or #VALUE!. 
        # Standard: Empty cell is 0 in arithmetic. 
        if val is None:
            return 0
        return val

    elif isinstance(node, UnaryNode):
        val = _eval_node(node.operand, get_cell, sheet_ctx)
        if isinstance(val, ErrorValue):
            return val
        if not isinstance(val, (int, float)):
            return VALUE_VALUE

        if node.op == '-':
            return -val
        else: # '+'
            return val

    elif isinstance(node, BinaryNode):
        left = _eval_node(node.left, get_cell, sheet_ctx)

        # Left-to-right evaluation: check left first
        if isinstance(left, ErrorValue):
            # We still need to evaluate right? 
            # Prompt: "operands are evaluated left to right... if any is an error... result is leftmost"
            # If left is error, result is that error. We technically don't need right value for result, 
            # but side effects? No side effects. But strict spec might require evaluating right for cycles? 
            # "errors propagate... left to right". Usually short-circuit is okay if no side effects, 
            # but for cycle detection in dependencies, we already have the graph. 
            # However, if right is also error, leftmost wins. So we can return left immediately IF left is not #VALUE! derived from text? 
            # No, if left is #VALUE! (text), we return it. 
            # But what if left is #REF! and right is #DIV/0!? Left wins. Return Left.
            # What if left is number, right is error? Return Right.
            return left

        right = _eval_node(node.right, get_cell, sheet_ctx)

        if isinstance(right, ErrorValue):
            return right

        if not isinstance(left, (int, float)) or not isinstance(right, (int, float)):
            return VALUE_VALUE

        try:
            if node.op == '+':
                return left + right
            elif node.op == '-':
                return left - right
            elif node.op == '*':
                return left * right
            elif node.op == '/':
                if right == 0:
                    return DIV0_VALUE
                return left / right
        except ZeroDivisionError:
            return DIV0_VALUE

    elif isinstance(node, RangeNode):
        # Ranges are only allowed as arguments to functions.
        # If we hit a range in normal eval context, it's an error? 
        # Grammar: arg := ref : ref | expr. 
        # So RangeNode is an argument type.
        # If it appears elsewhere, it's invalid syntax handled by parser? 
        # Parser only allows RangeNode in args. 
        # But if we eval it standalone? 
        # The spec says "Ranges are allowed only as function arguments."
        # If this is reached, it's likely via CallNode evaluation path. 
        # If reached via direct eval of a range expression (not in call), it's ambiguous. 
        # Assuming we are inside a call argument evaluation.
        # For a single ref arg or range arg, we return a special list/marker? 
        # No, CallNode eval handles args specifically.
        # If we evaluate a RangeNode directly as an expression (e.g. in binary op), it's #VALUE! or similar.
        return VALUE_VALUE

    elif isinstance(node, CallNode):
        return _eval_call(node, get_cell, sheet_ctx)

    raise FormulaError(f"Unknown node type: {type(node)}")

def _eval_call(node: CallNode, get_cell: CellGetter, sheet_ctx: Any) -> Any:
    numbers = []

    for arg in node.args:
        if isinstance(arg, RangeNode):
            # Expand range
            refs = _expand_range(arg.start.name, arg.end.name)

            for ref_name in refs:
                # Check bounds for each cell in range? 
                # "A range with a corner outside the sheet gives #REF!" 
                # Strictly: if the *range definition* has a corner outside, the whole call fails with #REF!?
                # "A range whose corners are both inside... contributes cells... A range with a corner outside... gives #REF!"
                if not _check_ref_valid(arg.start.name, sheet_ctx) or not _check_ref_valid(arg.end.name, sheet_ctx):
                    return REF_VALUE

                val = get_cell(sheet_ctx, ref_name)
                if val is None:
                    continue # Skip empty
                if isinstance(val, ErrorValue):
                    return val # Error propagates immediately?
                    # Prompt: "a cell holding an error value makes that error the call's result."
                    # This implies we return that error immediately.
                if isinstance(val, str):
                    # Text cells are skipped
                    continue
                if isinstance(val, (int, float)):
                    numbers.append(val)
                else:
                    # Unexpected type? Treat as skipped or error?
                    # "text... is skipped". Other types? Probably skipped or error.
                    continue

        else:
            # Evaluate as expression
            val = _eval_node(arg, get_cell, sheet_ctx)

            if isinstance(val, ErrorValue):
                return val
            if isinstance(val, str):
                # Text in argument expression -> #VALUE!
                return VALUE_VALUE
            if isinstance(val, (int, float)):
                numbers.append(val)
            else:
                return VALUE_VALUE

    # Compute function result
    if not numbers:
        if node.name == "SUM":
            return 0
        elif node.name == "AVG":
            return DIV0_VALUE
        elif node.name == "MIN":
            return 0
        elif node.name == "MAX":
            return 0

    if node.name == "SUM":
        # Int sum if all int, else float
        has_float = any(isinstance(n, float) for n in numbers)
        total = sum(numbers)
        if has_float:
            return float(total)
        return int(total)

    elif node.name == "AVG":
        return float(sum(numbers)) / len(numbers)

    elif node.name == "MIN":
        return min(numbers)

    elif node.name == "MAX":
        return max(numbers)

    return VALUE_VALUE
