from __future__ import annotations


class ConnectFour:
    def __init__(self, columns: int = 7, rows: int = 6, board: tuple | None = None, player: str | None = None):
        if columns < 1 or rows < 1:
            raise ValueError("Dimensions must be at least 1x1")

        self.columns = columns
        self.rows = rows

        if board is None:
            self._board = tuple(tuple('.' for _ in range(columns)) for _ in range(rows))
            self._move_count = 0
            self._winner = None
            self._player = 'X'
        else:
            self._board = board
            self._move_count = sum(1 for row in self._board for cell in row if cell != '.')
            # Determine winner based on board, if needed, or assume valid state passed
            # We compute winner lazily or eagerly? Eager is safer for immutability checks if needed,
            # but usually we compute once in init if board is provided externally.
            # However, to match interface, we can compute winner now.
            self._winner = self._compute_winner()

            # Determine player to move
            if self._winner is not None:
                 # Game over, player doesn't strictly matter for moves, but interface expects a string
                 # Usually we can keep the one who would have moved or the last one. 
                 # The prompt implies `player` is 'the player to move'. If over, it's ambiguous but 
                 # search handles `moves()` returning [] and `play` raising error.
                 # Let's keep alternating logic for consistency
                 self._player = 'X' if self._move_count % 2 == 0 else 'O'
            else:
                 self._player = 'X' if self._move_count % 2 == 0 else 'O'

    def _compute_winner(self):
        """Check entire board for a winner."""
        directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
        for r in range(self.rows):
            for c in range(self.columns):
                if self._board[r][c] == '.':
                    continue
                player = self._board[r][c]
                for dc, dr in directions:
                    if self._check_line(r, c, dc, dr, player):
                        return player
        return None

    def _check_line(self, start_r, start_c, dc, dr, player):
        """Check if a line of 4 starts at (start_c, start_r) in direction (dc, dr) and belongs to player."""
        for k in range(4):
            r = start_r + k * dr
            c = start_c + k * dc
            if 0 <= c < self.columns and 0 <= r < self.rows:
                if self._board[r][c] != player:
                    return False
            else:
                return False
        return True

    def _drop_row(self, col):
        """Return the row index where a piece dropped in col lands, or None if full."""
        for r in range(self.rows):
            if self._board[r][col] == '.':
                return r
        return None

    def _check_win_from_move(self, r, c, player):
        """Check if the move at (r, c) creates a win for player."""
        directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
        for dc, dr in directions:
            count = 1
            # Forward
            for k in range(1, 4):
                nr, nc = r + k * dr, c + k * dc
                if 0 <= nr < self.rows and 0 <= nc < self.columns and self._board[nr][nc] == player:
                    count += 1
                else:
                    break
            # Backward
            for k in range(1, 4):
                nr, nc = r - k * dr, c - k * dc
                if 0 <= nr < self.rows and 0 <= nc < self.columns and self._board[nr][nc] == player:
                    count += 1
                else:
                    break
            if count >= 4:
                return True
        return False

    @property
    def player(self):
        return self._player

    def moves(self):
        if self.is_over():
            return []
        return [c for c in range(self.columns) if self._drop_row(c) is not None]

    def play(self, move):
        if self.is_over():
            raise ValueError("Game is over")
        if not isinstance(move, int) or move < 0 or move >= self.columns:
            raise ValueError("Move out of bounds")

        drop_r = self._drop_row(move)
        if drop_r is None:
            raise ValueError("Column is full")

        # Create new board
        board_list = [list(row) for row in self._board]
        board_list[drop_r][move] = self._player
        new_board = tuple(tuple(row) for row in board_list)

        # Check for winner
        winner = None
        if self._check_win_from_move(drop_r, move, self._player):
            winner = self._player

        # Determine next player
        next_player = 'X' if (self._move_count + 1) % 2 == 0 else 'O'

        return ConnectFour(self.columns, self.rows, new_board, next_player)

    def winner(self):
        return self._winner

    def is_over(self):
        if self._winner is not None:
            return True
        # Check if board is full
        for row in self._board:
            if '.' in row:
                return False
        return True

    def cell(self, column, row):
        if 0 <= row < self.rows and 0 <= column < self.columns:
            return self._board[row][column]
        raise IndexError("Cell outside the board")

    def __str__(self):
        # Top row first
        lines = []
        for r in range(self.rows - 1, -1, -1):
            lines.append(''.join(self._board[r]))
        return '\n'.join(lines)

    def __eq__(self, other):
        if not isinstance(other, ConnectFour):
            return False
        return (self.columns == other.columns and 
                self.rows == other.rows and 
                self._board == other._board)

    def __hash__(self):
        return hash((self.columns, self.rows, self._board))

    @classmethod
    def from_moves(cls, moves, columns=7, rows=6):
        state = cls(columns, rows)
        for move in moves:
            state = state.play(move)
        return state


def evaluate(state):
    """Heuristic evaluation for Connect Four."""
    if state.is_over():
        # Heuristic usually returns 0 or specific values for terminal states, 
        # but spec says "scored for state.player" and defined by window sum.
        # If the game is over, search handles scoring (win/loss/draw). 
        # Evaluate is typically for non-terminal or leaf nodes in limited depth.
        # Spec says: "Empty windows, windows holding both players' pieces and windows with four pieces are worth 0."
        # It doesn't explicitly exclude terminal states from the sum logic, 
        # but typically evaluation is not called on finished games in negamax if is_over is checked first.
        # We calculate the sum regardless.
        pass

    score = 0
    player = state.player

    # Directions: Horizontal, Vertical, Diagonal Up-Right, Diagonal Up-Left
    directions = [(1, 0), (0, 1), (1, 1), (1, -1)]

    for r in range(state.rows):
        for c in range(state.columns):
            for dc, dr in directions:
                # Check if window fits
                end_c = c + 3 * dc
                end_r = r + 3 * dr

                if 0 <= end_c < state.columns and 0 <= end_r < state.rows:
                    counts = {'X': 0, 'O': 0, '.': 0}
                    for k in range(4):
                        cell_val = state.cell(c + k * dc, r + k * dr)
                        counts[cell_val] += 1

                    if counts['X'] > 0 and counts['O'] == 0 and counts['.'] > 0:
                        val = counts['X'] ** 2
                        if player == 'X':
                            score += val
                        else:
                            score -= val
                    elif counts['O'] > 0 and counts['X'] == 0 and counts['.'] > 0:
                        val = counts['O'] ** 2
                        if player == 'O':
                            score += val
                        else:
                            score -= val
                    # Else: Empty, Mixed, or Full(4) -> 0 contribution

    return score
