# NFA States

class State:
    """Base class for NFA states."""
    def __repr__(self):
        return f"<{self.__class__.__name__}>"


class AcceptState(State):
    """The accepting state."""
    pass


class EpsilonState(State):
    """A state with an epsilon transition to a target."""
    def __init__(self, target: State):
        self.target = target


class SplitState(State):
    """A state with two epsilon transitions (for branching)."""
    def __init__(self, s1: State, s2: State):
        self.s1 = s1
        self.s2 = s2


class CharState(State):
    """A state that consumes a specific character."""
    def __init__(self, char: str, target: State):
        self.char = char
        self.target = target


class AnyState(State):
    """A state that consumes any character except newline."""
    def __init__(self, target: State):
        self.target = target


class ClassState(State):
    """A state that consumes a character within a class."""
    def __init__(self, items: tuple, negated: bool, target: State):
        self.items = items
        self.negated = negated
        self.target = target


# Epsilon Closure Helpers

def _add_closure(state: State, visited: Set[State]):
    """Recursively add state and its epsilon-reachable states to visited."""
    if state in visited:
        return
    visited.add(state)
    if isinstance(state, EpsilonState):
        _add_closure(state.target, visited)
    elif isinstance(state, SplitState):
        _add_closure(state.s1, visited)
        _add_closure(state.s2, visited)


def _epsilon_closure(states: Set[State]) -> Set[State]:
    """Compute the epsilon closure of a set of states."""
    closure = set()
    for s in states:
        _add_closure(s, closure)
    return closure


def _step(state: State, char: str) -> Optional[State]:
    """Check if the state consumes the character, returning the target state if so."""
    if isinstance(state, CharState):
        if state.char == char:
            return state.target
    elif isinstance(state, AnyState):
        if char != '\n':
            return state.target
    elif isinstance(state, ClassState):
        is_in = False
        for low, high in state.items:
            if low <= char <= high:
                is_in = True
                break
        if state.negated:
            is_in = not is_in
        if is_in:
            return state.target
    return None


