    def __init__(self, start_state: State, accept_state: AcceptState):
        self.start_state = start_state
        self.accept_state = accept_state

    def _match_at(self, text: str, pos: int) -> Optional[int]:
        """Attempt to match text starting at pos. Returns end index if successful, else None.
        """
        # Initial states: epsilon closure of start state
        current_states = _epsilon_closure({self.start_state})

        # If start state leads directly to accept (empty match)
        best_end = -1
        if self.accept_state in current_states:
            best_end = pos

        # We need to find the LONGEST match starting at pos.
        # We must simulate until no more transitions are possible.

        for i in range(pos, len(text)):
            char = text[i]
            next_states = set()

            # Step: find all states that can consume this character
            for s in current_states:
                target = _step(s, char)
                if target is not None:
                    next_states.add(target)

            if not next_states:
                break

