            current_states = _epsilon_closure(next_states)

            # Check if we've reached an accepting state
            if self.accept_state in current_states:
                # Update best_end to the current position + 1 (1 past the last consumed char)
                best_end = i + 1

        if best_end == -1:
            return None
        return best_end

