        # Iterate start positions to find the leftmost match
        for i in range(start, len(text) + 1):
            end = self._match_at(text, i)
            if end is not None:
                # If we found a match, and it's empty (i == end), we should check if 
                # there's a longer match? 
                # The spec says: "among the matches beginning at i the longest one".
                # My _match_at finds the longest match starting at i.
                # So if _match_at returns i (empty match), it means there is NO 
                # non-empty match starting at i. Because if there was, best_end would be > i.
                # Wait, does _match_at return the longest?
                # Yes, it updates best_end every time it hits accept. 
                # So if it hits accept at i (empty), best_end = i.
                # Then it continues simulation. If later it hits accept, best_end updates.
                # So _match_at returns the longest match starting at i.
                return (i, end)

