        """Return all non-overlapping matches in the string."""
        results = []
        pos = 0
        while pos <= len(text):
            res = self.search(text, pos)
            if res is None:
                break
            i, j = res
            results.append(text[i:j])
            # If match was empty, advance by 1 to avoid infinite loop
            if i == j:
                pos = j + 1
            else:
