                starts.append(o_start)

            # Now build the Split structure for starts
            # If 2 options: Split(s1, s2)
            # If 3 options: Split(s1, Split(s2, s3))

            def _build_chain_starts(states_list):
                if len(states_list) == 1:
                    return states_list[0]
                # Split first, then rest
                s1 = states_list[0]
                rest = states_list[1:]
                s2 = _build_chain_starts(rest)
                return SplitState(s1, s2)

            if len(starts) == 1:
                return starts[0], final_end

            start = _build_chain_starts(starts)
            return start, final_end

        elif isinstance(node, Star):
            # s_start -> Split(body_start, s_end)
            # body_end -> epsilon -> s_start (to loop)
            # s_end is the Connection for the Star node itself (which goes to next)

            body_start, body_end = _build_node(node.node)

            s_end = Connection()
            # Create the Split
            s_start = SplitState(body_start, s_end)

            # Link body_end back to s_start
            body_end.target = EpsilonState(s_start)

            return s_start, s_end

        elif isinstance(node, Plus):
            # s_start -> body_start
            # body_end -> Split(body_start, s_end)
            # This ensures 1 or more.

            body_start, body_end = _build_node(node.node)
            s_end = Connection()

            s_start = body_start # Start directly into body

            # Link body_end to Split(body_start, s_end)
            loop_split = SplitState(body_start, s_end)
            body_end.target = loop_split

            return s_start, s_end

        elif isinstance(node, Optional):
            # s_start -> Split(body_start, s_end)
            # body_end -> s_end

            body_start, body_end = _build_node(node.node)
            s_end = Connection()

            s_start = SplitState(body_start, s_end)
            body_end.target = s_end

            return s_start, s_end

        else:
            raise ValueError(f"Unknown AST node type: {type(node)}")

    # Build the main NFA
    start_state, end_conn = _build_node(ast)

    # Connect the final end connection to the AcceptState
    end_conn.target = accept_state

    return NFA(start_state, accept_state)

# Module-level convenience functions

def match(pattern: Union[str, object], text: str) -> bool:
    return compile(pattern).match(text)

def search(pattern: Union[str, object], text: str, start: int = 0) -> Optional[Tuple[int, int]]:
    return compile(pattern).search(text, start)

def findall(pattern: Union[str, object], text: str) -> List[str]:
    return compile(pattern).findall(text)
