from __future__ import annotations
from dataclasses import dataclass
from typing import Union, Tuple


# AST Nodes
@dataclass(frozen=True)
class Empty:
    pass


@dataclass(frozen=True)
class Literal:
    char: str


@dataclass(frozen=True)
class AnyChar:
    pass


@dataclass(frozen=True)
class CharClass:
    items: tuple[tuple[str, str], ...]
    negated: bool


@dataclass(frozen=True)
class Concat:
    items: tuple


@dataclass(frozen=True)
class Alt:
    options: tuple


@dataclass(frozen=True)
class Star:
    node: object


@dataclass(frozen=True)
class Plus:
    node: object


@dataclass(frozen=True)
class Optional:
    node: object


@dataclass(frozen=True)
class Group:
    node: object


class RegexError(ValueError):
    def __init__(self, message: str, position: int):
        super().__init__(f"{message} at position {position}")
        self.message = message
        self.position = position


class Parser:
    def __init__(self, pattern: str):
        self.pattern = pattern
        self.pos = 0
        self.len = len(pattern)

    def peek(self) -> str | None:
        if self.pos < self.len:
            return self.pattern[self.pos]
        return None

    def consume(self) -> str:
        if self.pos >= self.len:
            raise RegexError("Unexpected end of pattern", self.pos)
        char = self.pattern[self.pos]
        self.pos += 1
        return char

    def error(self, message: str, pos: int = None) -> None:
        if pos is None:
            pos = self.pos
        raise RegexError(message, pos)

    def parse(self):
        ast = self.parse_alt()
        if self.pos < self.len:
            # Should have been handled by alt/concat, but if there are stray characters
            # like ) without matching ( which should have been caught in group parsing
            # or if we stopped early.
            # If we are here, it's usually an unexpected closing paren or error in logic.
            # However, parse_alt consumes as much as possible via concat.
            # If self.pos is not at end, it means we stopped at | or ).
            # parse_alt handles |. 
            # If we stopped at ), it's because of a group? No, parse() calls parse_alt which
            # calls parse_concat. parse_concat stops at ).
            # If we are at top level, ) is invalid.
            self.error("Unmatched ')'", self.pos)
        return ast

    def parse_alt(self):
        options = []

        while True:
            opt = self.parse_concat()
            options.append(opt)

            if self.pos < self.len and self.peek() == '|':
                self.pos += 1 # consume |
            else:
                break

        if len(options) == 1:
            return options[0]
        return Alt(tuple(options))

    def parse_concat(self):
        items = []

        while self.pos < self.len:
            char = self.peek()
            if char == '|':
                break
            if char == ')':
                break

            item = self.parse_quant()
            items.append(item)

        if not items:
            return Empty()
        if len(items) == 1:
            return items[0]
        return Concat(tuple(items))

    def parse_quant(self):
        atom = self.parse_atom()

        if self.pos < self.len:
            char = self.peek()
            if char == '*':
                self.pos += 1
                return Star(atom)
            elif char == '+':
                self.pos += 1
                return Plus(atom)
            elif char == '?':
                self.pos += 1
                return Optional(atom)

        return atom

    def parse_atom(self):
        if self.pos >= self.len:
            self.error("Unexpected end of pattern", self.pos)

        char = self.peek()

        if char == '(':
            return self.parse_group()
        elif char == '[':
            return self.parse_class()
        elif char == '.':
            self.pos += 1
            return AnyChar()
        elif char == '\\':
            self.pos += 1
            if self.pos >= self.len:
                self.error("Trailing backslash", self.pos - 1)
            escaped = self.consume()
            return Literal(escaped)
        elif char in ('*', '+', '?', '|', ')', ']'):
            # These should have been handled by higher levels or are errors
            if char in ('*', '+', '?'):
                self.error("Quantifier has nothing to repeat", self.pos)
            # If we hit | or ) here, it means parse_concat didn't stop, but parse_atom was called?
            # parse_concat loop condition prevents calling parse_atom on | or ).
            # So if we are here, something is wrong or it's a valid char like ]? 
            # Spec: ] outside class is literal.
            if char == ']':
                self.pos += 1
                return Literal(']')
            # If we reach here with | or ), it's a logic error or unmatched ) caught by group/top?
            # Unmatched ) at top level is caught in parse().
            # But what if we have `a)b`? parse_concat sees `a`, then `)`? No, stops. 
            # parse() sees `)` and errors.
            # What if we have `(...)` inside? parse_group consumes `)`.
            # If we are here, it's likely an error in control flow, but let's treat meta chars as error?
            # Actually `|` and `)` shouldn't reach parse_atom from parse_concat.
            self.error(f"Unexpected character '{char}'", self.pos)
        else:
            self.pos += 1
            return Literal(char)

    def parse_group(self):
        open_pos = self.pos
        self.pos += 1 # consume (

        node = self.parse_alt()

        if self.pos >= self.len:
            self.error("Unclosed group", open_pos)

        if self.peek() != ')':
            self.error("Unmatched ')'", self.pos)

        self.pos += 1 # consume )

        return Group(node)

    def parse_class(self):
        open_pos = self.pos
        self.pos += 1 # consume [

        negated = False
        if self.pos < self.len and self.peek() == '^':
            negated = True
            self.pos += 1

        items = []

        while self.pos < self.len and self.peek() != ']':
            # Parse a single item or range
            # We need to know if the next thing is a range. 
            # Structure: C1 [- C2]
            # If C1 is escape or char. Then check if next is - and if followed by char that is not ].

            # Get C1
            c1_pos = self.pos
            c1 = self.parse_class_char()

            # Check for range
            is_range = False
            if self.pos < self.len and self.peek() == '-':
                # Check if - is the last item
                # Look ahead: if i+1 is ] or end, - is literal
                if self.pos + 1 < self.len and self.pattern[self.pos + 1] != ']':
                    # It is a range
                    is_range = True
                    self.pos += 1 # consume -
                    c2 = self.parse_class_char()

                    if c1 > c2:
                        self.error("Invalid range", c1_pos)

                    items.append((c1, c2))
                    continue

            # If not a range, it's a literal
            # But wait, if we didn't take the range, we didn't consume -.
            # The - will be parsed as the *next* item in the next iteration?
            # No. If we are here, we parsed C1. 
            # If we saw '-' but decided it was literal, we must add C1 as literal, 
            # then the next loop iteration will see '-'. 
            # Is '-' a valid char to parse as literal? Yes.
            # But we need to ensure we don't lose the '-' if it's meant to be literal at the end.

            # Wait, if `pattern[pos] == '-'` and `pattern[pos+1] == ']'`, we decided not to range.
            # We add `(c1, c1)`. 
            # Next iteration: peek() is '-'. It is not ']'. So we enter loop.
            # Parse c1 = '-'. 
            # Then check range. If next is ']', not a range. 
            # Add `('-', '-')`. 
            # Next iteration: peek() is ']'. Loop ends.
            # This works for literal '-' at end.

            # What if `a-z-a`?
            # Item 1: 'a', sees '-', next 'z' != ']' -> Range (a,z). Consume 'z'.
            # Item 2: sees '-', next 'a' != ']' -> Range (-,a)? 
            # Wait. After (a,z), pos is after 'z'. peek() is '-'.
            # Parse c1='-'. 
            # See '-', next 'a' != ']' -> Range (-, a). 
            # This treats '-' as start of range. This is standard behavior for `-` inside.
            # However, if we want `-` to be literal at the end, the next char must be `]`.

            items.append((c1, c1))

        if self.pos >= self.len:
            self.error("Unclosed character class", open_pos)

        # Consume ']'
        self.pos += 1

        if not items:
            self.error("Empty character class", open_pos)

        return CharClass(tuple(items), negated)

    def parse_class_char(self) -> str:
        if self.pos >= self.len:
            # Should be caught by loop condition, but safe guard
            self.error("Unexpected end of class", self.pos)

        char = self.peek()
        if char == '\\':
            self.pos += 1
            if self.pos >= self.len:
                self.error("Trailing backslash in class", self.pos - 1)
            return self.consume()
        else:
            return self.consume()


def parse(pattern: str):
    if not pattern:
        return Empty()
    parser = Parser(pattern)
    return parser.parse()
