import sys

def dumps(obj, *, indent=None, sort_keys=False, ensure_ascii=False):
    """
    Serialize an object to a JSON string.

    Args:
        obj: The object to serialize.
        indent (int, optional): Number of spaces to indent per level. If None, compact output.
        sort_keys (bool): Whether to sort dictionary keys.
        ensure_ascii (bool): If True, escape non-ASCII characters.

    Returns:
        str: JSON string representation of obj.
    """
    # Validate indent
    if indent is not None:
        if not isinstance(indent, int):
             raise ValueError("Indent must be an integer or None")
        if indent < 0:
            raise ValueError("Indent must be non-negative")

    # State for cycle detection
    seen = set()

    def _serialize(value, level):
        # Cycle check for containers
        is_container = isinstance(value, (list, tuple, dict))

        if is_container:
            oid = id(value)
            if oid in seen:
                raise ValueError("Circular reference detected")
            seen.add(oid)

        try:
            # Dispatch based on type
            if value is None:
                return "null"

            if value is True:
                return "true"

            if value is False:
                return "false"

            # Check bool before int because bool is subclass of int
            if isinstance(value, bool):
                return "true" if value else "false"

            if isinstance(value, int):
                return str(value)

            if isinstance(value, float):
                if value != value or value in (float('inf'), float('-inf')):
                    raise ValueError("NaN or Infinity not allowed")
                return repr(value)

            if isinstance(value, str):
                return _escape_string(value, ensure_ascii)

            if isinstance(value, (list, tuple)):
                return _serialize_array(value, level)

            if isinstance(value, dict):
                return _serialize_object(value, level)

            raise TypeError(f"Object of type {type(value).__name__} is not JSON serializable")
        finally:
            if is_container:
                seen.discard(oid)

    def _serialize_array(arr, level):
        if not arr:
            return "[]"

        parts = [_serialize(item, level + 1) for item in arr]

        if indent is None:
            return "[" + ",".join(parts) + "]"
        else:
            # Pretty print
            padding = " " * ((level + 1) * indent)
            closing_padding = " " * (level * indent)

            # Construct lines
            lines = []
            for i, part in enumerate(parts):
                if i < len(parts) - 1:
                    lines.append(padding + part + ",")
                else:
                    lines.append(padding + part)

            return "[\n" + "\n".join(lines) + "\n" + closing_padding + "]"

    def _serialize_object(obj, level):
        if not obj:
            return "{}"

        keys = list(obj.keys())
        if sort_keys:
            keys.sort()

        parts = []
        for key in keys:
            if not isinstance(key, str):
                raise TypeError("Dictionary keys must be strings")
            key_json = _escape_string(key, ensure_ascii)
            value_json = _serialize(obj[key], level + 1)

            if indent is None:
                sep = ":"
            else:
                sep = ": "

            parts.append(f"{key_json}{sep}{value_json}")

        if indent is None:
            return "{" + ",".join(parts) + "}"
        else:
            padding = " " * ((level + 1) * indent)
            closing_padding = " " * (level * indent)

            lines = []
            for i, part in enumerate(parts):
                if i < len(parts) - 1:
                    lines.append(padding + part + ",")
                else:
                    lines.append(padding + part)

            return "{\n" + "\n".join(lines) + "\n" + closing_padding + "}"

    def _escape_string(s, ensure_ascii):
        escaped = []
        for c in s:
            if c == '"':
                escaped.append('\\"')
            elif c == '\\':
                escaped.append('\\\\')
            elif c == '\b':
                escaped.append('\\b')
            elif c == '\f':
                escaped.append('\\f')
            elif c == '\n':
                escaped.append('\\n')
            elif c == '\r':
                escaped.append('\\r')
            elif c == '\t':
                escaped.append('\\t')
            elif ord(c) < 0x20:
                escaped.append(f'\\u{ord(c):04x}')
            elif ensure_ascii and ord(c) > 0x7f:
                if ord(c) <= 0xffff:
                    escaped.append(f'\\u{ord(c):04x}')
                else:
                    # Surrogate pair for chars > U+FFFF
                    codepoint = ord(c) - 0x10000
                    hi = 0xd800 | (codepoint >> 10)
                    lo = 0xdc00 | (codepoint & 0x3ff)
                    escaped.append(f'\\u{hi:04x}\\u{lo:04x}')
            else:
                escaped.append(c)

        return '"' + "".join(escaped) + '"'

    return _serialize(obj, 0)
