import re
from typing import NamedTuple, List, Any, Union


class JSONError(ValueError):
    def __init__(self, msg: str, line: int, column: int):
        super().__init__(f"{msg} at line {line} column {column}")
        self.msg = msg
        self.line = line
        self.column = column

    def __str__(self):
        return f"{self.msg} at line {self.line} column {self.column}"


class Token(NamedTuple):
    kind: str
    value: Any
    line: int
    column: int


def tokenize(text: str, *, allow_nan: bool = False) -> List[Token]:
    tokens: List[Token] = []
    i = 0
    line = 1
    column = 1
    n = len(text)

    def peek(offset: int = 0) -> Union[str, None]:
        """Return char at i+offset or None."""
        idx = i + offset
        if idx < n:
            return text[idx]
        return None

    def advance_char():
        """Move index forward by 1, updating line/col."""
        nonlocal i, line, column
        if i < n:
            if text[i] == '\n':
                line += 1
                column = 1
            else:
                column += 1
            i += 1

    def advance(count: int = 1):
        """Move index forward by count, updating line/col."""
        for _ in range(count):
            advance_char()

    def add_token(kind: str, value: Any, tok_line: int, tok_col: int):
        tokens.append(Token(kind, value, tok_line, tok_col))

    while i < n:
        char = text[i]
        tok_line = line
        tok_col = column

        # Skip whitespace
        if char in ' \t\n\r':
            advance_char()
            continue

        # Structural characters
        if char in '{}[]:,':
            add_token(char, None, tok_line, tok_col)
            advance_char()
            continue

        # String
        if char == '"':
            val, i, line, column = _parse_string_internal(text, i, n, line, column)
            add_token('STRING', val, tok_line, tok_col)
            continue

        # Number or -Infinity
        if char == '-' or '0' <= char <= '9':
            # Special check for -Infinity if allow_nan is True
            if char == '-' and allow_nan:
                # Check if followed by a run of letters
                j = i + 1
                while j < n and text[j].isascii() and text[j].isalpha():
                    j += 1
                if j > i + 1:
                    word = text[i+1:j]
                    if word == 'Infinity':
                        # It's -Infinity
                        add_token('NUMBER', float('-inf'), tok_line, tok_col)
                        # Advance past '-' and the word 'Infinity'
                        count = j - i
                        for _ in range(count):
                            advance_char()
                        continue
                    else:
                        # It's - followed by letters that are not Infinity. Invalid number.
                        # The error is at the '-'
                        raise JSONError("invalid number", tok_line, tok_col)
                # If j == i+1, next char is not a letter (e.g. digit), fall through to standard number parsing

            if char == '-' and not allow_nan:
                 # Check if followed by letters to raise appropriate error? 
                 # Prompt: "With allow_nan=False (the default) ... -Infinity is an invalid number at the -"
                 # So we must handle the case where allow_nan=False explicitly if we hit letters.
                 j = i + 1
                 while j < n and text[j].isascii() and text[j].isalpha():
                     j += 1
                 if j > i + 1:
                     # It is - followed by letters. Since allow_nan is False, -Infinity is not allowed.
                     # And any other -Letters is invalid number.
                     raise JSONError("invalid number", tok_line, tok_col)

            val, i, line, column = _parse_number_internal(text, i, n, line, column)
            add_token('NUMBER', val, tok_line, tok_col)
            continue

        # Literals (true, false, null, NaN, Infinity)
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z':
            # Read whole run of ASCII letters
            j = i
            while j < n and text[j].isascii() and text[j].isalpha():
                j += 1
            literal = text[i:j]

            if literal == 'true':
                val = True
                kind = 'TRUE'
            elif literal == 'false':
                val = False
                kind = 'FALSE'
            elif literal == 'null':
                val = None
                kind = 'NULL'
            elif allow_nan and literal == 'NaN':
                val = float('nan')
                kind = 'NUMBER'
            elif allow_nan and literal == 'Infinity':
                val = float('inf')
                kind = 'NUMBER'
            else:
                raise JSONError("invalid literal", tok_line, tok_col)

            # Advance by the length of the literal
            count = j - i
            for _ in range(count):
                advance_char()
            add_token(kind, val, tok_line, tok_col)
            continue

        # Invalid character
        raise JSONError("unexpected character", tok_line, tok_col)

    # EOF Token
    tokens.append(Token('EOF', None, line, column))
    return tokens


def _parse_string_internal(text: str, i: int, n: int, line: int, column: int) -> tuple[str, int, int, int]:
    """Parse string starting at i. Returns (decoded_string, new_i, new_line, new_col)."""
    # i is at opening quote
    start_line = line
    start_col = column

    # Move past opening quote
    i += 1
    if text[i-1] == '\n':
        line += 1
        column = 1
    else:
        column += 1

    chars: List[str] = []

    while True:
        if i >= n:
            raise JSONError("unterminated string", start_line, start_col)

        char = text[i]

        # Check for control character
        if ord(char) < 0x20:
            raise JSONError("raw control character", line, column)

        if char == '"':
            # End of string
            i += 1
            if text[i-1] == '\n':
                 line += 1
                 column = 1
            else:
                 column += 1
            return ''.join(chars), i, line, column

        if char == '\\':
            # Escape sequence
            esc_line = line
            esc_col = column

            i += 1
            if text[i-1] == '\n':
                line += 1
                column = 1
            else:
                column += 1

            if i >= n:
                raise JSONError("unterminated string", start_line, start_col)

            next_char = text[i]

            if next_char == '"':
                chars.append('"')
                i += 1
                column += 1
            elif next_char == '\\':
                chars.append('\\')
                i += 1
                column += 1
            elif next_char == '/':
                chars.append('/')
                i += 1
                column += 1
            elif next_char == 'b':
                chars.append('\b')
                i += 1
                column += 1
            elif next_char == 'f':
                chars.append('\f')
                i += 1
                column += 1
            elif next_char == 'n':
                chars.append('\n')
                i += 1
                column += 1
            elif next_char == 'r':
                chars.append('\r')
                i += 1
                column += 1
            elif next_char == 't':
                chars.append('\t')
                i += 1
                column += 1
            elif next_char == 'u':
                # \uXXXX
                if i + 4 >= n + 1: 
                    if i + 5 > n: 
                         raise JSONError("invalid escape", esc_line, esc_col)

                hex_digits = text[i+1:i+5]
                if len(hex_digits) != 4 or not all(c in '0123456789abcdefABCDEF' for c in hex_digits):
                    raise JSONError("invalid escape", esc_line, esc_col)

                code = int(hex_digits, 16)

                if 0xD800 <= code <= 0xDBFF:
                    # High surrogate
                    if i + 7 > n: 
                        raise JSONError("invalid escape", esc_line, esc_col)

                    if text[i+5] != '\\' or text[i+6] != 'u':
                        raise JSONError("invalid escape", esc_line, esc_col)

                    low_hex = text[i+7:i+11]
                    if len(low_hex) != 4 or not all(c in '0123456789abcdefABCDEF' for c in low_hex):
                        raise JSONError("invalid escape", esc_line, esc_col)

                    low_code = int(low_hex, 16)
                    if not (0xDC00 <= low_code <= 0xDFFF):
                        raise JSONError("invalid escape", esc_line, esc_col)

                    try:
                        combined = chr((code - 0xD800) * 0x400 + (low_code - 0xDC00) + 0x10000)
                        chars.append(combined)
                    except ValueError:
                         raise JSONError("invalid escape", esc_line, esc_col)

                    for _ in range(10):
                        i += 1
                        column += 1

                else:
                    if 0xDC00 <= code <= 0xDFFF:
                        raise JSONError("invalid escape", esc_line, esc_col)

                    chars.append(chr(code))

                    for _ in range(5):
                        i += 1
                        column += 1
            else:
                raise JSONError("unknown escape", esc_line, esc_col)
        else:
            chars.append(char)
            i += 1
            if char == '\n':
                line += 1
                column = 1
            else:
                column += 1


def _parse_number_internal(text: str, i: int, n: int, line: int, column: int) -> tuple[Union[int, float], int, int, int]:
    """Parse number starting at i. Returns (value, new_i, new_line, new_col)."""
    start_line = line
    start_col = column

    # 1. Scan the maximal run of chars in 0123456789+- . eE
    j = i
    valid_num_chars = set('0123456789+-.eE')
    while j < n and text[j] in valid_num_chars:
        j += 1

    num_str = text[i:j]

    # 2. Validate num_str is a valid JSON number
    # Regex for JSON number:
    # ^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$

    is_float = False

    # Simple manual validation or regex
    import re
    json_num_re = re.compile(r'^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$')

    if not json_num_re.match(num_str):
        raise JSONError("invalid number", start_line, start_col)

    # 3. Convert
    if '.' in num_str or 'e' in num_str or 'E' in num_str:
        try:
            val = float(num_str)
        except ValueError:
            raise JSONError("invalid number", start_line, start_col)
    else:
        try:
            val = int(num_str)
        except ValueError:
            raise JSONError("invalid number", start_line, start_col)

    # 4. Advance state
    # We advanced i to j. Now update line/col.
    # We need to process each char in num_str for line/col
    for k in range(i, j):
        if text[k] == '\n':
            line += 1
            column = 1
        else:
            column += 1

    i = j

    return val, i, line, column

