# js/parser.py
from .scanner import tokenize, Token, JSONError
from typing import List, Any

class Parser:
    def __init__(self, tokens: List[Token], *, duplicate_keys: str = 'last', max_depth: int | None = None):
        self.tokens = tokens
        self.pos = 0
        self.duplicate_keys = duplicate_keys
        self.max_depth = max_depth
        self.current_depth = 0

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind: str) -> Token:
        tok = self.peek()
        if tok.kind != kind:
            raise JSONError(f"expected {kind}, got {tok.kind}", tok.line, tok.column)
        return self.advance()

    def parse(self) -> Any:
        """Parse the top-level value and ensure no trailing content."""
        value = self.parse_value()
        # After parsing the top-level value, the next token must be EOF
        tok = self.peek()
        if tok.kind != 'EOF':
            raise JSONError(f"unexpected trailing content {tok.kind}", tok.line, tok.column)
        return value

    def parse_value(self) -> Any:
        tok = self.peek()
        if tok.kind == '{':
            return self.parse_object()
        elif tok.kind == '[':
            return self.parse_array()
        elif tok.kind == 'STRING':
            self.advance()
            return tok.value
        elif tok.kind == 'NUMBER':
            self.advance()
            return tok.value
        elif tok.kind == 'TRUE':
            self.advance()
            return True
        elif tok.kind == 'FALSE':
            self.advance()
            return False
        elif tok.kind == 'NULL':
            self.advance()
            return None
        elif tok.kind == 'EOF':
            raise JSONError("unexpected end of text", tok.line, tok.column)
        else:
            # Unexpected token like '}', ',', etc. at start of value
            raise JSONError(f"unexpected token {tok.kind}", tok.line, tok.column)

    def parse_object(self) -> dict:
        tok = self.expect('{')

        # Depth check
        if self.max_depth is not None and self.current_depth + 1 > self.max_depth:
            raise JSONError("maximum nesting depth exceeded", tok.line, tok.column)

        self.current_depth += 1
        result = {}

        # Check for empty object
        if self.peek().kind == '}':
            self.advance()
            self.current_depth -= 1
            return result

        while True:
            # Key must be a string
            key_tok = self.peek()
            if key_tok.kind != 'STRING':
                raise JSONError(f"expected string key, got {key_tok.kind}", key_tok.line, key_tok.column)
            key = key_tok.value
            self.advance()

            # Expect colon
            self.expect(':')

            # Handle duplicate keys
            if key in result:
                if self.duplicate_keys == 'error':
                    raise JSONError(f"duplicate key: {key}", key_tok.line, key_tok.column)
                elif self.duplicate_keys == 'first':
                    # Parse and discard the value to consume the stream
                    self.parse_value()
                    # Do not update result
                else: # 'last'
                    # Parse and update value
                    value = self.parse_value()
                    result[key] = value
            else:
                # New key
                value = self.parse_value()
                result[key] = value

            # Check for comma or end
            tok = self.peek()
            if tok.kind == ',':
                self.advance()
                # Check for trailing comma before } (error)
                if self.peek().kind == '}':
                    err_tok = self.peek()
                    raise JSONError("trailing comma in object", err_tok.line, err_tok.column)
            elif tok.kind == '}':
                self.advance()
                self.current_depth -= 1
                return result
            elif tok.kind == 'EOF':
                raise JSONError("unexpected end of text in object", tok.line, tok.column)
            else:
                raise JSONError(f"expected ',' or '}}', got {tok.kind}", tok.line, tok.column)

    def parse_array(self) -> list:
        tok = self.expect('[')

        # Depth check
        if self.max_depth is not None and self.current_depth + 1 > self.max_depth:
            raise JSONError("maximum nesting depth exceeded", tok.line, tok.column)

        self.current_depth += 1
        result = []

        # Check for empty array
        if self.peek().kind == ']':
            self.advance()
            self.current_depth -= 1
            return result

        while True:
            # Parse value
            value = self.parse_value()
            result.append(value)

            # Check for comma or end
            tok = self.peek()
            if tok.kind == ',':
                self.advance()
                # Check for trailing comma before ] (error)
                if self.peek().kind == ']':
                    err_tok = self.peek()
                    raise JSONError("trailing comma in array", err_tok.line, err_tok.column)
            elif tok.kind == ']':
                self.advance()
                self.current_depth -= 1
                return result
            elif tok.kind == 'EOF':
                raise JSONError("unexpected end of text in array", tok.line, tok.column)
            else:
                raise JSONError(f"expected ',' or ']', got {tok.kind}", tok.line, tok.column)


def loads(text: str, *, duplicate_keys: str = 'last', max_depth: int | None = None, allow_nan: bool = False) -> Any:
    if duplicate_keys not in ('first', 'last', 'error'):
        raise ValueError("duplicate_keys must be 'first', 'last', or 'error'")
    if max_depth is not None and (not isinstance(max_depth, int) or max_depth < 1):
        raise ValueError("max_depth must be None or an integer >= 1")

    tokens = tokenize(text, allow_nan=allow_nan)
    parser = Parser(tokens, duplicate_keys=duplicate_keys, max_depth=max_depth)
    return parser.parse()
