import datetime
import decimal
from dataclasses import dataclass
from typing import List, Tuple, Optional

from sales.ingest import Sale

FIELDS = ('month', 'region', 'product')


def parse_month(text: str) -> str:
    """Validate YYYY-MM format and return it unchanged."""
    parts = text.split('-')
    if len(parts) != 2:
        raise ValueError(f"Invalid month format: {text}")
    year_str, month_str = parts

    if len(year_str) != 4 or not year_str.isdigit():
        raise ValueError(f"Invalid month format: {text}")
    if len(month_str) != 2 or not month_str.isdigit():
        raise ValueError(f"Invalid month format: {text}")

    month = int(month_str)
    if not (1 <= month <= 12):
        raise ValueError(f"Month out of range: {text}")

    return text


def filter_months(sales: List[Sale], start: Optional[str] = None, end: Optional[str] = None) -> List[Sale]:
    """Filter sales by month range (inclusive)."""
    if start is not None:
        start = parse_month(start)
    if end is not None:
        end = parse_month(end)

    filtered = []
    for sale in sales:
        month = sale.date.strftime('%Y-%m')
        if start is not None and month < start:
            continue
        if end is not None and month > end:
            continue
        filtered.append(sale)
    return filtered


@dataclass(frozen=True)
class Group:
    key: Tuple[str, ...]
    units: int
    orders: int
    revenue: decimal.Decimal


@dataclass(frozen=True)
class Report:
    by: Tuple[str, ...]
    groups: List[Group]
    total: Group


def aggregate(sales: List[Sale], by: Tuple[str, ...]) -> List[Group]:
    """Group sales by the given fields, calculate totals, and sort by key."""
    # Validation of 'by'
    if not by:
        raise ValueError("'by' must contain at least one field")

    if len(by) != len(set(by)):
        raise ValueError("Duplicate fields in 'by'")

    for field in by:
        if field not in FIELDS:
            raise ValueError(f"Invalid field: {field}")

    groups_dict = {}

    for sale in sales:
        key_parts = []
        for field in by:
            if field == 'month':
                val = sale.date.strftime('%Y-%m')
            elif field == 'region':
                val = sale.region
            elif field == 'product':
                val = sale.product
            else:
                raise ValueError(f"Unsupported field: {field}")
            key_parts.append(val)

        key = tuple(key_parts)

        if key in groups_dict:
            groups_dict[key]['units'] += sale.units
            groups_dict[key]['orders'] += 1
            groups_dict[key]['revenue'] += sale.revenue
        else:
            groups_dict[key] = {
                'key': key,
                'units': sale.units,
                'orders': 1,
                'revenue': sale.revenue
            }

    # Create Group objects and sort
    result = []
    for key, data in groups_dict.items():
        result.append(Group(
            key=key,
            units=data['units'],
            orders=data['orders'],
            revenue=data['revenue']
        ))

    result.sort(key=lambda g: g.key)
    return result


def build_report(sales: List[Sale], by: Tuple[str, ...]) -> Report:
    """Create a Report object including the total row."""
    groups = aggregate(sales, by)

    # Calculate total
    total_units = sum(g.units for g in groups)
    total_orders = sum(g.orders for g in groups)
    total_revenue = sum(g.revenue for g in groups)

    # Sum with empty starting value to handle empty list and preserve Decimal type
    total_revenue = sum((g.revenue for g in groups), decimal.Decimal(0))

    total_group = Group(
        key=(),
        units=total_units,
        orders=total_orders,
        revenue=total_revenue
    )

    return Report(
        by=by,
        groups=groups,
        total=total_group
    )
