import re


class Version:
    """Represents a semantic version MAJOR.MINOR.PATCH."""

    def __init__(self, text: str):
        if not isinstance(text, str):
            raise ValueError("Version text must be a string")

        # Strict parsing: exactly three parts, digits only, no leading zeros unless the part is "0"
        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Invalid version format: '{text}'. Must be MAJOR.MINOR.PATCH")

        nums = []
        for part in parts:
            if not part:
                raise ValueError(f"Invalid version part: empty string in '{text}'")
            if not part.isdigit():
                raise ValueError(f"Invalid version part: '{part}' in '{text}'. Must be digits only")
            # Check for leading zeros: if length > 1 and first char is '0', it's invalid
            if len(part) > 1 and part[0] == '0':
                raise ValueError(f"Invalid version part: '{part}' in '{text}'. No leading zeros allowed")
            nums.append(int(part))

        self.major, self.minor, self.patch = nums
        self._key = (self.major, self.minor, self.patch)

    def __str__(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}"

    def __repr__(self) -> str:
        return f"Version('{self}')"

    def __eq__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._key == other._key

    def __lt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._key < other._key

    def __le__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._key <= other._key

    def __gt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._key > other._key

    def __ge__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._key >= other._key

    def __hash__(self) -> int:
        return hash(self._key)


class Range:
    """Represents a set of version constraints."""

    def __init__(self, spec: str):
        self._spec = spec.strip()
        if not self._spec:
            raise ValueError("Range spec cannot be empty")

        # Split by comma to get individual constraints
        raw_constraints = self._spec.split(',')
        self._constraints = []

        for raw in raw_constraints:
            constraint_str = raw.strip()
            if not constraint_str:
                raise ValueError(f"Empty constraint found in spec: '{spec}'")
            self._constraints.append(self._parse_constraint(constraint_str))

        # Canonical string representation is the spec with whitespace removed
        self._canonical_str = "".join(self._spec.split())

    def _parse_constraint(self, text: str):
        """Parses a single constraint string into a predicate function."""
        # Match operator and version part
        # Operators: ==, !=, >=, <=, ^, ~, >, <
        # Also handle bare version (which implies ==)
        # Also handle *

        if text == '*':
            return lambda v: True

        # Try to find an operator at the beginning
        op = ""
        rest = ""

        # Order matters for matching: check multi-char ops first
        for candidate_op in ["==", "!=", ">=", "<=", "^", "~", ">", "<"]:
            if text.startswith(candidate_op):
                op = candidate_op
                rest = text[len(candidate_op):].strip()
                break

        if not op:
            # If no operator found, treat as bare version (implies ==)
            rest = text
            op = "=="

        if not rest:
            raise ValueError(f"Missing version after operator '{op}' in constraint '{text}'")

        try:
            version = Version(rest)
        except ValueError as e:
            raise ValueError(f"Invalid version in constraint '{text}': {e}")

        # Return a closure that checks the condition
        if op == "==":
            return lambda v, ver=version: v == ver
        elif op == "!=":
            return lambda v, ver=version: v != ver
        elif op == ">=":
            return lambda v, ver=version: v >= ver
        elif op == "<=":
            return lambda v, ver=version: v <= ver
        elif op == ">":
            return lambda v, ver=version: v > ver
        elif op == "<":
            return lambda v, ver=version: v < ver
        elif op == "^":
            # ^1.2.3 -> >=1.2.3, <2.0.0
            # ^0.2.3 -> >=0.2.3, <0.3.0
            # ^0.0.3 -> >=0.0.3, <0.0.4
            # ^0.0.0 -> >=0.0.0, <0.0.1
            lower = version
            if version.major != 0:
                upper = Version(f"{version.major + 1}.0.0")
            elif version.minor != 0:
                upper = Version(f"0.{version.minor + 1}.0")
            elif version.patch != 0:
                upper = Version(f"0.0.{version.patch + 1}")
            else:
                upper = Version("0.0.1")

            return lambda v, low=lower, up=upper: low <= v < up
        elif op == "~":
            # ~1.2.3 -> >=1.2.3, <1.3.0
            lower = version
            # Minor bump
            upper = Version(f"{version.major}.{version.minor + 1}.0")
            return lambda v, low=lower, up=upper: low <= v < up
        else:
            raise ValueError(f"Unknown operator '{op}' in constraint '{text}'")

    def contains(self, version: Version) -> bool:
        """Checks if the version satisfies all constraints in the range."""
        return all(c(version) for c in self._constraints)

    def __contains__(self, version: Version) -> bool:
        return self.contains(version)

    def __str__(self) -> str:
        return self._canonical_str

    def __repr__(self) -> str:
        return f"Range('{self._spec}')"

    def __eq__(self, other) -> bool:
        if not isinstance(other, Range):
            return NotImplemented
        return self._canonical_str == other._canonical_str

    def __hash__(self) -> int:
        return hash(self._canonical_str)
