        elif op == "<=":
            return lambda v, ver=version: v <= ver
        elif op == ">":
            return lambda v, ver=version: v > ver
        elif op == "<":
            return lambda v, ver=version: v < ver
        elif op == "^":
            # ^1.2.3 -> >=1.2.3, <2.0.0
            # ^0.2.3 -> >=0.2.3, <0.3.0
            # ^0.0.3 -> >=0.0.3, <0.0.4
            # ^0.0.0 -> >=0.0.0, <0.0.1
            lower = version
            if version.major != 0:
                upper = Version(f"{version.major + 1}.0.0")
            elif version.minor != 0:
                upper = Version(f"0.{version.minor + 1}.0")
            elif version.patch != 0:
                upper = Version(f"0.0.{version.patch + 1}")
            else:
                upper = Version("0.0.1")

            return lambda v, low=lower, up=upper: low <= v < up
        elif op == "~":
            # ~1.2.3 -> >=1.2.3, <1.3.0
            lower = version
            # Minor bump
            upper = Version(f"{version.major}.{version.minor + 1}.0")
            return lambda v, low=lower, up=upper: low <= v < up
        else:
            raise ValueError(f"Unknown operator '{op}' in constraint '{text}'")

    def contains(self, version: Version) -> bool:
        """Checks if the version satisfies all constraints in the range."""
        return all(c(version) for c in self._constraints)

    def __contains__(self, version: Version) -> bool:
        return self.contains(version)

    def __str__(self) -> str:
        return self._canonical_str

    def __repr__(self) -> str:
        return f"Range('{self._spec}')"

    def __eq__(self, other) -> bool:
        if not isinstance(other, Range):
            return NotImplemented
        return self._canonical_str == other._canonical_str

    def __hash__(self) -> int:
        return hash(self._canonical_str)

