"""Game state management, command execution, and persistence."""

import json
from typing import Dict, List, Optional

from adventure.parser import parse, ParseError
from adventure.world import World, DIRECTIONS, Room, Item


class SaveError(ValueError):
    """Raised when save data is invalid."""
    pass


class Game:
    """Manages dynamic game state and executes commands."""

    def __init__(self, world: World):
        self._world = world
        self._room_id: str = world.start
        self._inventory: List[str] = []
        self._moves: int = 0

        # Deep copy items into state so they can be moved around
        # self._room_items maps room_id -> list of item_ids currently in that room
        self._room_items: Dict[str, List[str]] = {}
        for room_id, room in world.rooms.items():
            self._room_items[room_id] = list(room.items)

    @property
    def room(self) -> str:
        """The current room id."""
        return self._room_id

    @property
    def inventory(self) -> List[str]:
        """A new list of item ids in inventory order."""
        return list(self._inventory)

    @property
    def moves(self) -> int:
        """The number of successful moves."""
        return self._moves

    def items_in(self, room_id: str) -> List[str]:
        """Returns a new list of item ids in the specified room."""
        return list(self._room_items.get(room_id, []))

    def _find_item(self, item_ids: List[str], arg: str) -> Optional[Item]:
        """Find the first item in item_ids that matches arg (id or name lower)."""
        for iid in item_ids:
            item = self._world.items.get(iid)
            if item:
                if item.id == arg or item.name.lower() == arg:
                    return item
        return None

    def _format_look_room(self, room: Room) -> str:
        """Construct the look description for a room."""
        lines = []
        lines.append(room.name)
        lines.append(room.description)

        # Exits
        valid_exits = [d for d in DIRECTIONS if d in room.exits]
        if valid_exits:
            exits_str = ", ".join(valid_exits)
            lines.append(f"Exits: {exits_str}.")
        else:
            lines.append("Exits: none.")

        # Items
        item_ids = self.items_in(room.id)
        if item_ids:
            names = [self._world.items[iid].name for iid in item_ids]
            lines.append(f"You see: {', '.join(names)}.")

        return "\n".join(lines)

    def do(self, line: str) -> str:
        """Run one command and return the response text."""
        try:
            cmd = parse(line)
        except ParseError as e:
            return str(e)

        verb = cmd.verb
        arg = cmd.arg

        current_room = self._world.rooms[self._room_id]

        if verb == "look":
            if arg is None:
                return self._format_look_room(current_room)
            else:
                # Check room first, then inventory
                item = self._find_item(self.items_in(self._room_id), arg)
                if not item:
                    item = self._find_item(self._inventory, arg)

                if item:
                    return item.description
                return f"You see no {arg} here."

        elif verb == "go":
            if arg not in current_room.exits:
                return "You can't go that way."

            target_id = current_room.exits[arg]
            self._room_id = target_id
            self._moves += 1
            target_room = self._world.rooms[target_id]
            return self._format_look_room(target_room)

        elif verb == "take":
            room_items = self.items_in(self._room_id)
            item = self._find_item(room_items, arg)

            if item:
                if not item.portable:
                    return f"You can't take the {item.name}."

                # Remove from room, add to inventory
                self._room_items[self._room_id].remove(item.id)
                self._inventory.append(item.id)
                return f"Taken: {item.name}."

            # Check inventory
            item = self._find_item(self._inventory, arg)
            if item:
                return f"You already have the {item.name}."

            return f"You see no {arg} here."

        elif verb == "drop":
            item = self._find_item(self._inventory, arg)

            if item:
                self._inventory.remove(item.id)
                self._room_items[self._room_id].append(item.id)
                return f"Dropped: {item.name}."

            return "You aren't carrying that."

        elif verb == "inventory":
            if not self._inventory:
                return "You are carrying nothing."

            names = [self._world.items[iid].name for iid in self._inventory]
            return f"You are carrying: {', '.join(names)}."

        else:
            # Should not happen if parser is correct
            return "I don't understand that."

    def save(self) -> str:
        """Returns a JSON string of the game state."""
        state = {
            "version": 1,
            "room": self._room_id,
            "inventory": list(self._inventory),
            "items": {k: list(v) for k, v in self._room_items.items()},
            "moves": self._moves
        }
        return json.dumps(state)

    @classmethod
    def load(cls, world: World, text: str) -> "Game":
        """Load a game from JSON text."""
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON")

        if not isinstance(data, dict):
            raise SaveError("Not an object")

        required_keys = {"version", "room", "inventory", "items", "moves"}
        if not required_keys.issubset(data.keys()):
            raise SaveError("Missing keys")

        if data["version"] != 1:
            raise SaveError("Invalid version")

        room_id = data["room"]
        if room_id not in world.rooms:
            raise SaveError("Invalid room")

        inventory = data["inventory"]
        if not isinstance(inventory, list):
            raise SaveError("Invalid inventory")

        for iid in inventory:
            if iid not in world.items:
                raise SaveError(f"Unknown item {iid} in inventory")

        room_items_data = data["items"]
        if not isinstance(room_items_data, dict):
            raise SaveError("Invalid items mapping")

        # Validate room items
        for r_id, item_list in room_items_data.items():
            if r_id not in world.rooms:
                raise SaveError(f"Unknown room {r_id}")
            if not isinstance(item_list, list):
                raise SaveError(f"Invalid item list for room {r_id}")
            for iid in item_list:
                if iid not in world.items:
                    raise SaveError(f"Unknown item {iid} in room {r_id}")

        # Check for duplicates across inventory and rooms
        all_item_ids = list(inventory)
        for item_list in room_items_data.values():
            all_item_ids.extend(item_list)

        if len(all_item_ids) != len(set(all_item_ids)):
            raise SaveError("Item duplicate found")

        moves = data["moves"]
        if not isinstance(moves, int) or moves < 0:
            raise SaveError("Invalid moves")

        # Initialize game with this state
        game = cls(world)
        game._room_id = room_id
        game._inventory = list(inventory)
        game._moves = moves

        # Reconstruct room items
        new_room_items = {}
        for r_id in world.rooms:
            if r_id in room_items_data:
                new_room_items[r_id] = list(room_items_data[r_id])
            else:
                new_room_items[r_id] = []

        game._room_items = new_room_items

        return game
