    def execute(self, text: str) -> str:
        """Parse and execute a command, returning the response string."""
        try:
            command = parse(text)
        except ParseError as e:
            return str(e)

        verb = command.verb
        arg = command.arg

        if verb == "go":
            return self._do_go(arg)
        elif verb == "look":
            return self._do_look()
        elif verb == "take":
            return self._do_take(arg)
        elif verb == "drop":
            return self._do_drop(arg)
        elif verb == "use":
            return self._do_use(arg)
        elif verb == "score":
            return f"Your score is {self._score}."
        else:
            return "I don't understand that."

    def _do_go(self, direction: str) -> str:
        """Move in the given direction if unlocked and exists."""
        room = self._world.rooms[self._room_id]
        if direction not in room.exits:
            return "You can't go that way."

        # Check if locked
        if direction in room.locks:
            if (self._room_id, direction) not in self._unlocked:
                return f"The way {direction} is locked."

        target_room = room.exits[direction]
        self._room_id = target_room
        self._moves += 1

        # Score for entering new room
        if target_room not in self._visited:
            self._visited.add(target_room)
            self._score += 10

        return "You move " + direction + "."

    def _do_look(self) -> str:
        """Return the description of the current room."""
        room = self._world.rooms[self._room_id]
        lines = [room.description]

        # Items in room
        items_here = self._room_items.get(self._room_id, [])
        if items_here:
            item_names = [self._world.items[iid].name for iid in items_here]
            lines.append("You see: " + ", ".join(item_names) + ".")

        # Exits
        exits_desc = []
        for direction in DIRECTIONS:
            if direction in room.exits:
                if direction in room.locks:
                    if (self._room_id, direction) not in self._unlocked:
                        exits_desc.append(f"{direction} (locked)")
                    else:
                        exits_desc.append(direction)
                else:
                    exits_desc.append(direction)

        if exits_desc:
            lines.append("Exits: " + ", ".join(exits_desc) + ".")

        return "\n".join(lines)

    def _do_take(self, item_name: str) -> str:
        """Take an item if it exists in the room."""
        items_here = self._room_items.get(self._room_id, [])
        found_item_id = None
        for iid in items_here:
            if self._world.items[iid].name.lower() == item_name.lower():
                found_item_id = iid
                break

        if not found_item_id:
            return f"I don't see {item_name} here."

        self._room_items[self._room_id].remove(found_item_id)
        self._inventory.append(found_item_id)

        # Score treasure
        item = self._world.items[found_item_id]
        if item.treasure > 0 and found_item_id not in self._scored:
            self._scored.add(found_item_id)
            self._score += item.treasure

        return f"Taken."

    def _do_drop(self, item_name: str) -> str:
        """Drop an item if it is in inventory."""
        found_item_id = None
        for iid in self._inventory:
            if self._world.items[iid].name.lower() == item_name.lower():
                found_item_id = iid
                break

        if not found_item_id:
            return f"You aren't carrying {item_name}."

        self._inventory.remove(found_item_id)
        self._room_items[self._room_id].append(found_item_id)
        return f"Dropped."

    def _do_use(self, item_name: str) -> str:
        """Use an item (key) to unlock exits."""
        found_item_id = None
        for iid in self._inventory:
            if self._world.items[iid].name.lower() == item_name.lower():
                found_item_id = iid
                break

        if not found_item_id:
            return "You aren't carrying that."

        room = self._world.rooms[self._room_id]
        unlocked_here = []

        # Check all locked exits in this room for this key
        for direction, key_id in room.locks.items():
            if key_id == found_item_id:
                if (self._room_id, direction) not in self._unlocked:
                    self._unlocked.add((self._room_id, direction))
                    unlocked_here.append(direction)

        if not unlocked_here:
            return f"Nothing here to use the {item_name} on."

        # Sort unlocked directions in DIRECTIONS order
        sorted_dirs = [d for d in DIRECTIONS if d in unlocked_here]

        return "Unlocked: " + ", ".join(sorted_dirs) + "."

    def save(self) -> str:
        """Returns a JSON string of the game state."""
        # Prepare unlocked list as sorted list of [room_id, direction]
        unlocked_pairs = [[r, d] for r, d in self._unlocked]
        unlocked_pairs.sort()

        visited_list = sorted(list(self._visited))
        scored_list = sorted(list(self._scored))

        state = {
            "version": 2,
            "room": self._room_id,
            "inventory": list(self._inventory),
            "items": {k: list(v) for k, v in self._room_items.items()},
            "moves": self._moves,
            "unlocked": unlocked_pairs,
            "visited": visited_list,
            "scored": scored_list,
            "score": self._score
        }
        return json.dumps(state)

    @classmethod
    def load(cls, world: World, text: str) -> "Game":
        """Load a game from JSON text."""
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON")

        if not isinstance(data, dict):
            raise SaveError("Not an object")

        required_keys = {"version", "room", "inventory", "items", "moves"}
        if not required_keys.issubset(data.keys()):
            raise SaveError("Missing keys")

        version = data["version"]
        if version not in (1, 2):
            raise SaveError("Invalid version")

        room_id = data["room"]
        if room_id not in world.rooms:
            raise SaveError("Invalid room")

        inventory = data["inventory"]
        if not isinstance(inventory, list):
            raise SaveError("Invalid inventory")

        for iid in inventory:
            if iid not in world.items:
                raise SaveError(f"Unknown item {iid} in inventory")

        room_items_data = data["items"]
        if not isinstance(room_items_data, dict):
            raise SaveError("Invalid items mapping")

        # Validate room items
        for r_id, item_list in room_items_data.items():
            if r_id not in world.rooms:
                raise SaveError(f"Unknown room {r_id}")
            if not isinstance(item_list, list):
                raise SaveError(f"Invalid item list for room {r_id}")
            for iid in item_list:
                if iid not in world.items:
                    raise SaveError(f"Unknown item {iid} in room {r_id}")

        # Check for duplicates across inventory and rooms
        all_item_ids = list(inventory)
        for item_list in room_items_data.values():
            all_item_ids.extend(item_list)

        if len(all_item_ids) != len(set(all_item_ids)):
            raise SaveError("Item duplicate found")

        moves = data["moves"]
        if not isinstance(moves, int) or moves < 0:
            raise SaveError("Invalid moves")

        if version == 1:
            unlocked = []
            visited = [world.start, room_id]
            scored = []
            score = 0
        else:
            # Validate v2 specific keys
            v2_keys = {"unlocked", "visited", "scored", "score"}
            if not v2_keys.issubset(data.keys()):
                raise SaveError("Missing keys")

            # Validate unlocked
            unlocked_data = data["unlocked"]
            if not isinstance(unlocked_data, list):
                raise SaveError("Invalid unlocked")
            for pair in unlocked_data:
                if not isinstance(pair, list) or len(pair) != 2:
                    raise SaveError("Invalid unlocked entry")
                r_id, d = pair
                if r_id not in world.rooms:
                    raise SaveError("Invalid unlocked room")
                if d not in world.rooms[r_id].locks:
                    raise SaveError("Invalid unlocked direction")
            unlocked = unlocked_data

            # Validate visited
            visited_data = data["visited"]
            if not isinstance(visited_data, list):
                raise SaveError("Invalid visited")
            for r_id in visited_data:
                if r_id not in world.rooms:
                    raise SaveError("Invalid visited room")
            visited = visited_data

            # Validate scored
            scored_data = data["scored"]
            if not isinstance(scored_data, list):
                raise SaveError("Invalid scored")
            for iid in scored_data:
                if iid not in world.items:
                    raise SaveError("Invalid scored item")
            scored = scored_data

            # Validate score
            score = data["score"]
            if not isinstance(score, int) or score < 0:
                raise SaveError("Invalid score")

        # Initialize game with this state
        game = cls(world)
        game._room_id = room_id
        game._inventory = list(inventory)
        game._moves = moves

        # Reconstruct room items
        new_room_items = {}
        for r_id in world.rooms:
            if r_id in room_items_data:
                new_room_items[r_id] = list(room_items_data[r_id])
            else:
                new_room_items[r_id] = []

        game._room_items = new_room_items

        # Restore new state
        game._score = score
        game._unlocked = set((pair[0], pair[1]) for pair in unlocked)
        game._visited = set(visited)
        game._scored = set(scored)

        return game
