                    if 'key' not in target:
                        raise WorldError(f"Exit '{direction}' in room '{room_id}' is missing 'key'")

                    target_room_id = target['to']
                    key_item_id = target['key']

                    if target_room_id not in rooms_data:
                        raise WorldError(f"Exit '{direction}' in room '{room_id}' leads to unknown room '{target_room_id}'")

                    if key_item_id not in items:
                        raise WorldError(f"Exit '{direction}' in room '{room_id}' has unknown key '{key_item_id}'")

