"""Static game world structure and loading logic."""

from dataclasses import dataclass, field
from typing import Dict, Tuple

DIRECTIONS: Tuple[str, ...] = ('north', 'south', 'east', 'west', 'up', 'down')

class WorldError(ValueError):
    """Raised when the world definition is invalid."""
    pass

@dataclass(frozen=True)
class Item:
    id: str
    name: str
    description: str
    portable: bool = True
    treasure: int = 0

@dataclass(frozen=True)
class Room:
    id: str
    name: str
    description: str
    exits: Dict[str, str]
    items: Tuple[str, ...]
    locks: Dict[str, str] = field(default_factory=dict)

class World:
    start: str
    rooms: Dict[str, Room]
    items: Dict[str, Item]

    def __init__(self, start: str, rooms: Dict[str, Room], items: Dict[str, Item]):
        self.start = start
        self.rooms = rooms
        self.items = items

    @classmethod
    def from_dict(cls, data: dict) -> 'World':
        """Builds a world from a plain dict."""
        # 1. Validate start
        if 'start' not in data:
            raise WorldError("'start' is missing")
        start_id = data['start']

        rooms_data = data.get('rooms', {})
        items_data = data.get('items', {})

        # 2. Validate start room exists
        if start_id not in rooms_data:
            raise WorldError(f"Start room '{start_id}' is not a room")

        # 3. Build Items
        items: Dict[str, Item] = {}
        for item_id, item_spec in items_data.items():
            name = item_spec.get('name', '')
            description = item_spec.get('description', '')
            portable = item_spec.get('portable', True)

            # Handle treasure
            treasure = item_spec.get('treasure', 0)
            if not isinstance(treasure, int) or isinstance(treasure, bool) or treasure < 0:
                raise WorldError(f"Item '{item_id}' has invalid treasure value")

            items[item_id] = Item(
                id=item_id,
                name=name,
                description=description,
                portable=portable,
                treasure=treasure
            )

        # 4. Build Rooms
        rooms: Dict[str, Room] = {}
        item_occurrences: Dict[str, int] = {}

        for room_id, room_spec in rooms_data.items():
            # Validate room fields
            name = room_spec.get('name')
            if not name:
                raise WorldError(f"Room '{room_id}' lacks a name")

            if 'description' not in room_spec:
                raise WorldError(f"Room '{room_id}' lacks a description")
            description = room_spec['description']

            # Parse exits
            raw_exits = room_spec.get('exits', {})
            exits: Dict[str, str] = {}
            locks: Dict[str, str] = {}

            for direction, target in raw_exits.items():
                if direction not in DIRECTIONS:
                    raise WorldError(f"Exit direction '{direction}' in room '{room_id}' is not a valid direction")

                if isinstance(target, dict):
                    # Locked exit format: {"to": room_id, "key": key_id}
                    if 'to' not in target:
                        raise WorldError(f"Exit '{direction}' in room '{room_id}' is missing 'to'")
                    if 'key' not in target:
                        raise WorldError(f"Exit '{direction}' in room '{room_id}' is missing 'key'")

                    target_room_id = target['to']
                    key_item_id = target['key']

                    if target_room_id not in rooms_data:
                        raise WorldError(f"Exit '{direction}' in room '{room_id}' leads to unknown room '{target_room_id}'")

                    if key_item_id not in items:
                        raise WorldError(f"Exit '{direction}' in room '{room_id}' has unknown key '{key_item_id}'")

                    exits[direction] = target_room_id
                    locks[direction] = key_item_id
                else:
                    # Unlocked exit format: room_id
                    target_room_id = target
                    if target_room_id not in rooms_data:
                        raise WorldError(f"Exit '{direction}' in room '{room_id}' leads to unknown room '{target_room_id}'")

                    exits[direction] = target_room_id

            # Parse items
            raw_items = room_spec.get('items', [])
            items_tuple: Tuple[str, ...] = tuple(raw_items)

            # Validate items in room and check for global duplicates
            for item_id in raw_items:
                if item_id not in items:
                    raise WorldError(f"Room '{room_id}' lists unknown item '{item_id}'")

                count = item_occurrences.get(item_id, 0) + 1
                if count > 1:
                    raise WorldError(f"Item '{item_id}' is listed more than once")
                item_occurrences[item_id] = count

            rooms[room_id] = Room(
                id=room_id,
                name=name,
                description=description,
                exits=exits,
                items=items_tuple,
                locks=locks
            )

        return cls(start_id, rooms, items)
