"""
Parser for text adventure commands.
"""

from typing import Optional, NamedTuple


class Command(NamedTuple):
    verb: str
    arg: Optional[str]


class ParseError(ValueError):
    pass


DIRECTIONS = {
    'north': 'north', 'n': 'north',
    'south': 'south', 's': 'south',
    'east': 'east', 'e': 'east',
    'west': 'west', 'w': 'west',
    'up': 'up', 'u': 'up',
    'down': 'down', 'd': 'down',
}

ARTICLES = {'the', 'a', 'an'}



def parse(line: str) -> Command:
    words = line.lower().split()

    if not words:
        raise ParseError("Say something.")

    verb = words[0]
    # Remove articles from the rest
    rest = [w for w in words[1:] if w not in ARTICLES]
    arg_str = " ".join(rest)

    # Direction verbs (shorthand)
    if verb in DIRECTIONS:
        if rest:
            raise ParseError("I don't understand that.")
        return Command('go', DIRECTIONS[verb])

    if verb == 'go':
        if not rest:
            raise ParseError("Go where?")
        if arg_str in DIRECTIONS:
            return Command('go', DIRECTIONS[arg_str])
        raise ParseError(f'"{arg_str}" is not a direction.')

    if verb in ('take', 'get'):
        if not rest:
            raise ParseError("Take what?")
        return Command('take', arg_str)

    if verb == 'drop':
        if not rest:
            raise ParseError("Drop what?")
        return Command('drop', arg_str)

    if verb in ('look', 'l'):
        if not rest:
            return Command('look', None)
        if rest[0] == 'at':
            examine_args = rest[1:]
            if not examine_args:
                raise ParseError("Examine what?")
            return Command('look', " ".join(examine_args))
        return Command('look', arg_str)

    if verb in ('examine', 'x'):
        if not rest:
            raise ParseError("Examine what?")
        return Command('look', arg_str)

    if verb in ('inventory', 'inv', 'i'):
        if rest:
            raise ParseError("I don't understand that.")
        return Command('inventory', None)

    if verb == 'use':
        if not rest:
            raise ParseError("Use what?")
        return Command('use', arg_str)

    if verb == 'score':
        if rest:
            raise ParseError("I don't understand that.")
        return Command('score', None)

    raise ParseError(f'I don\'t know the word "{verb}".')
