from __future__ import annotations


def normalize(path: str, cwd: str = "/") -> str:
    """
    Normalize a path to an absolute path with no '.' or '..' parts,
    no repeated '/' and no trailing '/' (except the root, '/').

    Args:
        path: The path to normalize. Can be relative or absolute.
        cwd: The current working directory, assumed to be an absolute
             normalized path. Used if 'path' is relative.

    Returns:
        An absolute, normalized path string.

    Raises:
        ValueError: If 'path' is empty.
    """
    if not path:
        raise ValueError("Path cannot be empty")

    # If relative, resolve against cwd
    if not path.startswith("/"):
        if cwd.endswith("/"):
            path = f"{cwd}{path}"
        else:
            path = f"{cwd}/{path}"

    parts = path.split("/")
    stack: list[str] = []

    for part in parts:
        if not part or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
            # If stack is empty, '..' at root stays at root (ignored)
        else:
            stack.append(part)

    if not stack:
        return "/"
    return "/" + "/".join(stack)


def join(base: str, *parts: str) -> str:
    """
    Join path components together and normalize the result.

    Behaves like posixpath.join followed by normalize.
    If a part starts with '/', the rest of the path is reset.

    Args:
        base: The starting path.
        *parts: Additional path parts to append.

    Returns:
        An absolute, normalized path string.
    """
    result = base
    for part in parts:
        if part.startswith("/"):
            result = part
        else:
            # Append with separator, avoiding double slashes if base ends with /
            if result.endswith("/"):
                result += part
            else:
                result += "/" + part

    return normalize(result)


def split(path: str) -> tuple[str, str]:
    """
    Split an absolute normalized path into (parent, name).

    Args:
        path: An absolute normalized path.

    Returns:
        A tuple (parent, name). For the root path '/', returns ('/', '').
    """
    if path == "/":
        return ("/", "")

    idx = path.rfind("/")
    if idx == 0:
        # Path like '/name'
        return ("/", path[1:])
    else:
        # Path like '/parent/name'
        return (path[:idx], path[idx + 1:])


def is_within(path: str, ancestor: str) -> bool:
    """
    Check if 'path' is 'ancestor' itself or lies below it.

    Args:
        path: The path to check.
        ancestor: The ancestor directory path.

    Returns:
        True if path is within ancestor, False otherwise.
    """
    p = normalize(path)
    a = normalize(ancestor)

    if p == a:
        return True

    # Special case for root ancestor: every absolute path starts with /
    if a == "/":
        return p.startswith("/")

    return p.startswith(a + "/")
