from __future__ import annotations

import fnmatch
from vfs.paths import normalize, join, split, is_within


class FSError(Exception):
    def __init__(self, path: str):
        super().__init__(path)
        self.path = path


class NotFound(FSError):
    pass


class AlreadyExists(FSError):
    pass


class NotADirectory(FSError):
    pass


class IsADirectory(FSError):
    pass


class InvalidOperation(FSError):
    pass


class _Node:
    def __init__(self, name: str):
        self.name = name


class _File(_Node):
    def __init__(self, name: str, content: str = ""):
        super().__init__(name)
        self.content = content


class _Dir(_Node):
    def __init__(self, name: str):
        super().__init__(name)
        self.children: dict[str, _Node] = {}


class FileSystem:
    def __init__(self):
        self.root = _Dir("")
        self.cwd = "/"

    def _resolve_components(self, path: str, cwd: str = None) -> tuple[list[str], str]:
        if cwd is None:
            cwd = self.cwd
        norm_path = normalize(path, cwd)
        if norm_path == "/":
            return [], "/"
        parts = [p for p in norm_path.split("/") if p]
        return parts, norm_path

    def _get_node(self, path: str, cwd: str = None) -> _Node | None:
        parts, norm_path = self._resolve_components(path, cwd)
        node = self.root

        for part in parts:
            if not isinstance(node, _Dir):
                raise NotADirectory(norm_path)
            if part not in node.children:
                return None
            node = node.children[part]

        return node

    def exists(self, path: str, cwd: str = None) -> bool:
        try:
            return self._get_node(path, cwd) is not None
        except FSError:
            return False

    def is_dir(self, path: str, cwd: str = None) -> bool:
        try:
            node = self._get_node(path, cwd)
            return isinstance(node, _Dir)
        except FSError:
            return False

    def pwd(self) -> str:
        return self.cwd

    def cd(self, path: str) -> None:
        norm_path = normalize(path, self.cwd)
        try:
            node = self._get_node(norm_path)
        except NotADirectory:
            raise NotADirectory(norm_path)

        if node is None:
            raise NotFound(norm_path)

        if not isinstance(node, _Dir):
            raise NotADirectory(norm_path)

        self.cwd = norm_path

    def mkdir(self, path: str, parents: bool = False) -> None:
        norm_path = normalize(path, self.cwd)
        if norm_path == "/":
            raise AlreadyExists(norm_path)

        parent_path, name = split(norm_path)

        if not parents:
            try:
                parent_node = self._get_node(parent_path)
            except NotADirectory:
                raise NotADirectory(norm_path)

            if parent_node is None:
                raise NotFound(norm_path)
            if not isinstance(parent_node, _Dir):
                raise NotADirectory(norm_path)
        else:
            # Ensure parent exists, creating if necessary
            # Recursive creation logic
            try:
                self._get_node(parent_path)
            except NotADirectory:
                raise NotADirectory(norm_path)

            if not self.exists(parent_path):
                # Need to create parent recursively
                # We call mkdir on parent with parents=True
                # But we need to be careful about errors propagating correctly
                # If parent_path is /, it exists.
                if parent_path != "/":
                    self.mkdir(parent_path, parents=True)

                # Now fetch parent node again
                try:
                    parent_node = self._get_node(parent_path)
                except NotADirectory:
                    raise NotADirectory(norm_path)
            else:
                try:
                    parent_node = self._get_node(parent_path)
                except NotADirectory:
                    raise NotADirectory(norm_path)

            if parent_node is None:
                 # Should have been created
                 raise NotFound(norm_path)
            if not isinstance(parent_node, _Dir):
                raise NotADirectory(norm_path)

        if name in parent_node.children:
            child = parent_node.children[name]
            if isinstance(child, _Dir):
                if parents:
                    return
                else:
                    raise AlreadyExists(norm_path)
            else:
                raise AlreadyExists(norm_path)

        parent_node.children[name] = _Dir(name)

    def write(self, path: str, text: str, append: bool = False) -> None:
        norm_path = normalize(path, self.cwd)
        parent_path, name = split(norm_path)

        if parent_path == norm_path:
            raise IsADirectory(norm_path)

        try:
            node = self._get_node(norm_path)
        except NotADirectory:
            raise NotADirectory(norm_path)

        if node is not None:
            if isinstance(node, _Dir):
                raise IsADirectory(norm_path)
            if append:
                node.content += text
            else:
                node.content = text
            return

        try:
            parent_node = self._get_node(parent_path)
        except NotADirectory:
            raise NotADirectory(norm_path)

        if parent_node is None:
            raise NotFound(norm_path)

        if not isinstance(parent_node, _Dir):
            raise NotADirectory(norm_path)

        parent_node.children[name] = _File(name, text)

    def read(self, path: str) -> str:
        norm_path = normalize(path, self.cwd)

        try:
            node = self._get_node(norm_path)
        except NotADirectory:
            raise NotADirectory(norm_path)

        if node is None:
            raise NotFound(norm_path)

        if isinstance(node, _Dir):
            raise IsADirectory(norm_path)

        return node.content

    def ls(self, path: str = ".") -> list[str]:
        norm_path = normalize(path, self.cwd)

        try:
            node = self._get_node(norm_path)
        except NotADirectory:
            raise NotADirectory(norm_path)

        if node is None:
            raise NotFound(norm_path)

        if isinstance(node, _File):
            return [node.name]

        entries = []
        for name, child in node.children.items():
            if isinstance(child, _Dir):
                entries.append(name + "/")
            else:
                entries.append(name)

        return sorted(entries)

    def rm(self, path: str, recursive: bool = False) -> None:
        norm_path = normalize(path, self.cwd)

        try:
            node = self._get_node(norm_path)
        except NotADirectory:
            raise NotADirectory(norm_path)

        if node is None:
            raise NotFound(norm_path)

        if norm_path == "/":
            raise InvalidOperation(norm_path)

        if norm_path == self.cwd or is_within(self.cwd, norm_path):
            raise InvalidOperation(norm_path)

        if isinstance(node, _Dir) and not recursive:
            raise IsADirectory(norm_path)

        parent_path, name = split(norm_path)
        try:
            parent_node = self._get_node(parent_path)
        except NotADirectory:
            raise NotADirectory(norm_path)

        if parent_node is None:
            raise NotFound(norm_path)

        if not isinstance(parent_node, _Dir):
            raise NotADirectory(norm_path)

        del parent_node.children[name]

    def mv(self, src: str, dst: str) -> None:
        norm_src = normalize(src, self.cwd)
        try:
            src_node = self._get_node(norm_src)
        except NotADirectory:
            raise NotADirectory(norm_src)

        if src_node is None:
            raise NotFound(norm_src)

        if norm_src == "/":
            raise InvalidOperation(norm_src)
        if norm_src == self.cwd or is_within(self.cwd, norm_src):
            raise InvalidOperation(norm_src)

        norm_dst = normalize(dst, self.cwd)
        target_path = norm_dst

        try:
            dst_node = self._get_node(norm_dst)
        except NotADirectory:
            raise NotADirectory(norm_dst)

        if dst_node is not None and isinstance(dst_node, _Dir):
            _, src_name = split(norm_src)
            target_path = join(norm_dst, src_name)

        if target_path == norm_src or is_within(target_path, norm_src):
            raise InvalidOperation(norm_src)

        try:
            target_node = self._get_node(target_path)
        except NotADirectory:
            raise NotADirectory(target_path)

        if target_node is not None:
            raise AlreadyExists(target_path)

        target_parent, target_name = split(target_path)
        try:
            parent_node = self._get_node(target_parent)
        except NotADirectory:
            raise NotADirectory(target_path)

        if parent_node is None:
            raise NotFound(target_path)

        if not isinstance(parent_node, _Dir):
            raise NotADirectory(target_path)

        src_parent_path, src_name = split(norm_src)
        try:
            src_parent = self._get_node(src_parent_path)
        except NotADirectory:
            raise NotADirectory(norm_src)

        if src_parent is None or not isinstance(src_parent, _Dir):
            raise NotADirectory(norm_src)

        del src_parent.children[src_name]
        src_node.name = target_name
        parent_node.children[target_name] = src_node

    def find(self, path: str = ".", pattern: str = "*") -> list[str]:
        norm_path = normalize(path, self.cwd)

        try:
            node = self._get_node(norm_path)
        except NotADirectory:
            raise NotADirectory(norm_path)

        if node is None:
            raise NotFound(norm_path)

        results = []

        if isinstance(node, _File):
            if fnmatch.fnmatchcase(node.name, pattern):
                return [norm_path]
            else:
                return []

        def traverse(current_node: _Dir, current_prefix: str):
            for name, child in current_node.children.items():
                abs_path = join(current_prefix, name)
                if fnmatch.fnmatchcase(name, pattern):
                    results.append(abs_path)
                if isinstance(child, _Dir):
                    traverse(child, abs_path)

        traverse(node, norm_path)
        return sorted(results)
