"""Interpreter for a Forth-like stack language."""

import sys
from typing import List, Dict, Tuple, Optional, TextIO
from stack.lexer import Token, tokenize


class StackError(Exception):
    """Base class for stack language errors."""
    def __init__(self, word: str, line: int, col: int):
        self.word = word
        self.line = line
        self.col = col
        super().__init__(f"{self.__class__.__name__}: {word} at line {line}, col {col}")


class StackUnderflow(StackError):
    """Raised when a word needs more stack items than available."""
    pass


class UnknownWord(StackError):
    """Raised when an undefined word is executed."""
    pass


class DivisionByZero(StackError):
    """Raised on division or modulo by zero."""
    pass


class ControlError(StackError):
    """Raised for malformed control structures or definitions."""
    pass


class StepLimitExceeded(StackError):
    """Raised when max_steps is exceeded."""
    pass


class CallDepthExceeded(StackError):
    """Raised when max_depth is exceeded."""
    pass


# Keywords that are reserved and cannot be user-defined word names
KEYWORDS = {"if", "else", "then", "begin", "until", ":", ";"}

# Built-in words (including those that might be defined in previous versions)
# We check these against definitions to prevent redefinition
BUILTIN_WORDS = {
    "+", "-", "*", "/", "mod", "negate", "abs", "dup", "drop", "swap", "over", "rot", "-rot",
    "print", ".", "depth", "clear"
}


def validate_program(tokens: List[Token]) -> None:
    """Validate the entire program including control structures and definitions.

    Rules:
    - Definitions (`:` ... `;`) must be at top level, not inside if/begin/definitions.
    - Control structures must be balanced.
    - `:` must have a valid name and a `;`.
    """
    # Stack for open structures: tuples of (kind, token)
    # kind: 'if', 'begin', 'definition'
    open_stack: List[Tuple[str, Token]] = []

    i = 0
    n = len(tokens)
    while i < n:
        tok = tokens[i]
        if tok.kind != 'word':
            i += 1
            continue

        word = tok.value

        if word == ':':
            if open_stack:
                raise ControlError(":", tok.line, tok.col)
            if i + 1 >= n:
                raise ControlError(":", tok.line, tok.col)
            name_tok = tokens[i + 1]
            if name_tok.kind != 'word' or name_tok.value in KEYWORDS or name_tok.value in BUILTIN_WORDS:
                raise ControlError(name_tok.value if name_tok.kind == 'word' else name_tok.value, name_tok.line, name_tok.col)
            open_stack.append(('definition', tok))
            i += 2
            continue

        if word == ';':
            if not open_stack or open_stack[-1][0] != 'definition':
                raise ControlError(";", tok.line, tok.col)
            open_stack.pop()
            i += 1
            continue

        if word == 'if':
            open_stack.append(('if', tok))
            i += 1
            continue

        if word == 'else':
            if not open_stack or open_stack[-1][0] != 'if':
                raise ControlError("else", tok.line, tok.col)
            i += 1
            continue

        if word == 'then':
            if not open_stack or open_stack[-1][0] != 'if':
                raise ControlError("then", tok.line, tok.col)
            open_stack.pop()
            i += 1
            continue

        if word == 'begin':
            open_stack.append(('begin', tok))
            i += 1
            continue

        if word == 'until':
            if not open_stack or open_stack[-1][0] != 'begin':
                raise ControlError("until", tok.line, tok.col)
            open_stack.pop()
            i += 1
            continue

        i += 1

    if open_stack:
        kind, opener = open_stack[-1]
        raise ControlError(opener.value, opener.line, opener.col)


class Interpreter:
    """Interpreter for the Forth-like stack language."""

    def __init__(self, max_steps: int = 100000, max_depth: int = 100):
        self.stack: List[int] = []
        self.output: List[int] = []
        self.max_steps = max_steps
        self.max_depth = max_depth

        # Persist definitions across runs
        self.definitions: Dict[str, List[Token]] = {}

        # State for current run
        self._steps = 0
        self._depth = 0

    def defined(self) -> List[str]:
        """Returns the sorted list of user-defined word names."""
        return sorted(self.definitions.keys())

    def run(self, source: str) -> None:
        """Run the given source code."""
        tokens = tokenize(source)

        # Validate control structures and definitions
        validate_program(tokens)

        self._steps = 0
        self._depth = 0

        self._run_tokens(tokens)

    def _check_step(self, word: str, line: int, col: int) -> None:
        """Check and increment step counter. Raise StepLimitExceeded if over limit."""
        if self._steps >= self.max_steps:
            raise StepLimitExceeded(word, line, col)
        self._steps += 1

    def _check_depth(self, word: str, line: int, col: int) -> None:
        """Check and increment call depth. Raise CallDepthExceeded if over limit."""
        if self._depth >= self.max_depth:
            raise CallDepthExceeded(word, line, col)
        self._depth += 1

    def _decrement_depth(self) -> None:
        self._depth -= 1

    def _run_tokens(self, tokens: List[Token]) -> None:
        """Execute a list of tokens."""
        i = 0
        n = len(tokens)

        while i < n:
            tok = tokens[i]

            if tok.kind == 'number':
                self._check_step('number', tok.line, tok.col)
                self.stack.append(tok.value)
                i += 1
                continue

            if tok.kind != 'word':
                i += 1
                continue

            word = tok.value

            # Handle Definition Syntax at Execution Time
            if word == ':':
                # Find the name and body
                name_tok = tokens[i + 1]
                name = name_tok.value

                # Find the closing ';'
                # We need to scan for the matching ';' respecting nesting of if/begin
                j = i + 2
                depth = 0
                while j < n:
                    t = tokens[j]
                    if t.kind == 'word':
                        if t.value == 'if':
                            depth += 1
                        elif t.value == 'begin':
                            depth += 1
                        elif t.value == 'then':
                            depth -= 1
                        elif t.value == 'until':
                            depth -= 1
                        elif t.value == ';':
                            if depth == 0:
                                break
                    j += 1

                # Store definition
                self.definitions[name] = tokens[i+2:j]
                i = j + 1
                continue

            # Handle Control Structures
            if word == 'if':
                self._check_step(word, tok.line, tok.col)
                # Find matching 'then', respecting nesting
                j = i + 1
                depth = 0
                while j < n:
                    t = tokens[j]
                    if t.kind == 'word':
                        if t.value == 'if':
                            depth += 1
                        elif t.value == 'then':
                            depth -= 1
                        elif t.value == 'else' and depth == 0:
                            break
                    j += 1

                if depth == 0 and t.value == 'else':
                    # Found else
                    else_tok_index = j
                    # Find matching 'then' for the if
                    j = else_tok_index + 1
                    depth = 0
                    while j < n:
                        t2 = tokens[j]
                        if t2.kind == 'word':
                            if t2.value == 'if':
                                depth += 1
                            elif t2.value == 'then':
                                if depth == 0:
                                    break
                                depth -= 1
                        j += 1
                    then_index = j

                    if self.stack:
                        # True branch: tokens between if and else
                        self._run_tokens(tokens[i+1:else_tok_index])
                    else:
                        # False branch: tokens between else and then
                        self._run_tokens(tokens[else_tok_index+1:then_index])

                    i = then_index + 1
                    continue
                else:
                    # No else, find then
                    # j is currently at 'then' or end
                    # We know validate_program passed, so there is a 'then'
                    # Scan from i+1 to find matching 'then'
                    j = i + 1
                    depth = 0
                    while j < n:
                        t = tokens[j]
                        if t.kind == 'word':
                            if t.value == 'if':
                                depth += 1
                            elif t.value == 'then':
                                if depth == 0:
                                    break
                                depth -= 1
                        j += 1
                    then_index = j

                    if self.stack:
                        self._run_tokens(tokens[i+1:then_index])

                    i = then_index + 1
                    continue

            elif word == 'begin':
                # Find matching 'until'
                j = i + 1
                depth = 0
                while j < n:
                    t = tokens[j]
                    if t.kind == 'word':
                        if t.value == 'begin':
                            depth += 1
                        elif t.value == 'until':
                            if depth == 0:
                                break
                            depth -= 1
                    j += 1
                until_index = j
                body = tokens[i+1:until_index]

                while True:
                    self._run_tokens(body)
                    if self.stack and self.stack[-1] != 0:
                        break
                i = until_index + 1
                continue

            elif word == 'then' or word == 'else' or word == 'until' or word == ';':
                # Should be handled by control flow, ignore if reached directly in bad state?
                # validate_program ensures they match. If we reach here, it's likely handled by skipping in control flow logic.
                i += 1
                continue

            # Handle User-Defined Words
            if word in self.definitions:
                self._check_depth(word, tok.line, tok.col)
                try:
                    self._run_tokens(self.definitions[word])
                finally:
                    self._decrement_depth()
                i += 1
                continue

            # Handle Built-in Words
            if word in BUILTIN_WORDS:
                self._check_step(word, tok.line, tok.col)

                if word == '+':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    b = self.stack.pop(); a = self.stack.pop()
                    self.stack.append(a + b)
                elif word == '-':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    b = self.stack.pop(); a = self.stack.pop()
                    self.stack.append(a - b)
                elif word == '*':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    b = self.stack.pop(); a = self.stack.pop()
                    self.stack.append(a * b)
                elif word == '/':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    b = self.stack.pop(); a = self.stack.pop()
                    if b == 0: raise DivisionByZero(word, tok.line, tok.col)
                    self.stack.append(a // b)
                elif word == 'mod':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    b = self.stack.pop(); a = self.stack.pop()
                    if b == 0: raise DivisionByZero(word, tok.line, tok.col)
                    self.stack.append(a % b)
                elif word == 'negate':
                    if len(self.stack) < 1: raise StackUnderflow(word, tok.line, tok.col)
                    a = self.stack.pop()
                    self.stack.append(-a)
                elif word == 'abs':
                    if len(self.stack) < 1: raise StackUnderflow(word, tok.line, tok.col)
                    a = self.stack.pop()
                    self.stack.append(abs(a))
                elif word == 'dup':
                    if len(self.stack) < 1: raise StackUnderflow(word, tok.line, tok.col)
                    self.stack.append(self.stack[-1])
                elif word == 'drop':
                    if len(self.stack) < 1: raise StackUnderflow(word, tok.line, tok.col)
                    self.stack.pop()
                elif word == 'swap':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    self.stack[-1], self.stack[-2] = self.stack[-2], self.stack[-1]
                elif word == 'over':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    self.stack.append(self.stack[-2])
                elif word == 'rot':
                    if len(self.stack) < 3: raise StackUnderflow(word, tok.line, tok.col)
                    self.stack[-3], self.stack[-2], self.stack[-1] = self.stack[-2], self.stack[-1], self.stack[-3]
                elif word == '-rot':
                    if len(self.stack) < 3: raise StackUnderflow(word, tok.line, tok.col)
                    self.stack[-3], self.stack[-2], self.stack[-1] = self.stack[-1], self.stack[-3], self.stack[-2]
                elif word == 'print':
                    pass
                elif word == '.':
                    if len(self.stack) < 1: raise StackUnderflow(word, tok.line, tok.col)
                    val = self.stack.pop()
                    self.output.append(val)
                elif word == 'depth':
                    self.stack.append(len(self.stack))
                elif word == 'clear':
                    self.stack.clear()
                else:
                    raise UnknownWord(word, tok.line, tok.col)

                i += 1
                continue

            # Unknown Word
            raise UnknownWord(word, tok.line, tok.col)


def evaluate(source: str) -> list:
    """Run source in a new Interpreter and return its stack."""
    interp = Interpreter(max_steps=100000)
    interp.run(source)
    return interp.stack


def repl(infile: TextIO, outfile: TextIO, interp: Optional[Interpreter] = None) -> int:
    """Interactive REPL."""
    if interp is None:
        interp = Interpreter()

    for line in infile:
        line = line.strip()
        if not line:
            continue

        start_output_len = len(interp.output)

        try:
            interp.run(line)
            new_outputs = interp.output[start_output_len:]
            if new_outputs:
                outfile.write(" ".join(map(str, new_outputs)) + " ok\n")
            else:
                outfile.write("ok\n")
            outfile.flush()
        except StackError as e:
            outfile.write(f"error: {e.__class__.__name__}: {e.word}\n")
            outfile.flush()
        except Exception:
            outfile.write("error: internal error\n")
            outfile.flush()

    return 0


def main(argv: Optional[List[str]] = None) -> int:
    """Command line entry point."""
    import sys
    if argv is None:
        argv = sys.argv[1:]

    if len(argv) == 0:
        return repl(sys.stdin, sys.stdout)
    elif len(argv) == 1:
        filename = argv[0]
