            if word == ':':
                # Find the name and body
                name_tok = tokens[i + 1]
                name = name_tok.value

                # Find the closing ';'
                # We need to scan for the matching ';' respecting nesting of if/begin
                j = i + 2
                depth = 0
                while j < n:
                    t = tokens[j]
                    if t.kind == 'word':
                        if t.value == 'if':
                            depth += 1
                        elif t.value == 'begin':
                            depth += 1
                        elif t.value == 'then':
                            depth -= 1
                        elif t.value == 'until':
                            depth -= 1
                        elif t.value == ';':
                            if depth == 0:
                                break
                    j += 1

                # Store definition
                self.definitions[name] = tokens[i+2:j]
                i = j + 1
                continue

            # Handle Control Structures
            if word == 'if':
                self._check_step(word, tok.line, tok.col)
                # Find matching 'then', respecting nesting
                j = i + 1
                depth = 0
                while j < n:
                    t = tokens[j]
                    if t.kind == 'word':
                        if t.value == 'if':
                            depth += 1
                        elif t.value == 'then':
                            depth -= 1
                        elif t.value == 'else' and depth == 0:
                            break
                    j += 1

                if depth == 0 and t.value == 'else':
                    # Found else
                    else_tok_index = j
                    # Find matching 'then' for the if
                    j = else_tok_index + 1
                    depth = 0
                    while j < n:
                        t2 = tokens[j]
                        if t2.kind == 'word':
                            if t2.value == 'if':
                                depth += 1
                            elif t2.value == 'then':
                                if depth == 0:
                                    break
                                depth -= 1
                        j += 1
                    then_index = j

                    if self.stack:
                        # True branch: tokens between if and else
                        self._run_tokens(tokens[i+1:else_tok_index])
                    else:
                        # False branch: tokens between else and then
                        self._run_tokens(tokens[else_tok_index+1:then_index])

                    i = then_index + 1
                    continue
                else:
                    # No else, find then
                    # j is currently at 'then' or end
                    # We know validate_program passed, so there is a 'then'
                    # Scan from i+1 to find matching 'then'
                    j = i + 1
                    depth = 0
                    while j < n:
                        t = tokens[j]
                        if t.kind == 'word':
                            if t.value == 'if':
                                depth += 1
                            elif t.value == 'then':
                                if depth == 0:
