                    i = then_index + 1
                    continue

            elif word == 'begin':
                # Find matching 'until'
                j = i + 1
                depth = 0
                while j < n:
                    t = tokens[j]
                    if t.kind == 'word':
                        if t.value == 'begin':
                            depth += 1
                        elif t.value == 'until':
                            if depth == 0:
                                break
                            depth -= 1
