            # Handle User-Defined Words
            if word in self.definitions:
                self._check_depth(word, tok.line, tok.col)
                try:
                    self._run_tokens(self.definitions[word])
                finally:
                    self._decrement_depth()
                i += 1
                continue

            # Handle Built-in Words
            if word in BUILTIN_WORDS:
                self._check_step(word, tok.line, tok.col)

                if word == '+':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    b = self.stack.pop(); a = self.stack.pop()
                    self.stack.append(a + b)
                elif word == '-':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    b = self.stack.pop(); a = self.stack.pop()
                    self.stack.append(a - b)
                elif word == '*':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    b = self.stack.pop(); a = self.stack.pop()
                    self.stack.append(a * b)
