                    if b == 0: raise DivisionByZero(word, tok.line, tok.col)
                    self.stack.append(a // b)
                elif word == 'mod':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    b = self.stack.pop(); a = self.stack.pop()
                    if b == 0: raise DivisionByZero(word, tok.line, tok.col)
                    self.stack.append(a % b)
                elif word == 'negate':
                    if len(self.stack) < 1: raise StackUnderflow(word, tok.line, tok.col)
                    a = self.stack.pop()
                    self.stack.append(-a)
                elif word == 'abs':
                    if len(self.stack) < 1: raise StackUnderflow(word, tok.line, tok.col)
                    a = self.stack.pop()
                    self.stack.append(abs(a))
                elif word == 'dup':
                    if len(self.stack) < 1: raise StackUnderflow(word, tok.line, tok.col)
                    self.stack.append(self.stack[-1])
                elif word == 'drop':
                    if len(self.stack) < 1: raise StackUnderflow(word, tok.line, tok.col)
