                    self.stack[-1], self.stack[-2] = self.stack[-2], self.stack[-1]
                elif word == 'over':
                    if len(self.stack) < 2: raise StackUnderflow(word, tok.line, tok.col)
                    self.stack.append(self.stack[-2])
                elif word == 'rot':
                    if len(self.stack) < 3: raise StackUnderflow(word, tok.line, tok.col)
                    self.stack[-3], self.stack[-2], self.stack[-1] = self.stack[-2], self.stack[-1], self.stack[-3]
                elif word == '-rot':
                    if len(self.stack) < 3: raise StackUnderflow(word, tok.line, tok.col)
                    self.stack[-3], self.stack[-2], self.stack[-1] = self.stack[-1], self.stack[-3], self.stack[-2]
                elif word == 'print':
                    pass
                elif word == '.':
                    if len(self.stack) < 1: raise StackUnderflow(word, tok.line, tok.col)
                    val = self.stack.pop()
                    self.output.append(val)
                elif word == 'depth':
                    self.stack.append(len(self.stack))
                elif word == 'clear':
                    self.stack.clear()
                else:
                    raise UnknownWord(word, tok.line, tok.col)

                i += 1
                continue

            # Unknown Word
            raise UnknownWord(word, tok.line, tok.col)


def evaluate(source: str) -> list:
    """Run source in a new Interpreter and return its stack."""
    interp = Interpreter(max_steps=100000)
    interp.run(source)
    return interp.stack


def repl(infile: TextIO, outfile: TextIO, interp: Optional[Interpreter] = None) -> int:
    """Interactive REPL."""
    if interp is None:
        interp = Interpreter()

    for line in infile:
        line = line.strip()
        if not line:
            continue

        start_output_len = len(interp.output)

        try:
            interp.run(line)
            new_outputs = interp.output[start_output_len:]
            if new_outputs:
                outfile.write(" ".join(map(str, new_outputs)) + " ok\n")
            else:
                outfile.write("ok\n")
            outfile.flush()
        except StackError as e:
            outfile.write(f"error: {e.__class__.__name__}: {e.word}\n")
            outfile.flush()
        except Exception:
            outfile.write("error: internal error\n")
            outfile.flush()

    return 0


def main(argv: Optional[List[str]] = None) -> int:
    """Command line entry point."""
    import sys
    if argv is None:
        argv = sys.argv[1:]

    if len(argv) == 0:
        return repl(sys.stdin, sys.stdout)
    elif len(argv) == 1:
        filename = argv[0]
        try:
            with open(filename, 'r') as f:
                source = f.read()
        except OSError:
            print(f"error: could not read file {filename}", file=sys.stderr)
            return 2

        interp = Interpreter(max_steps=100000)
        try:
            interp.run(source)
            if interp.output:
                print(" ".join(map(str, interp.output)))
            return 0
        except StackError as e:
            if interp.output:
                print(" ".join(map(str, interp.output)))
            print(f"error: {e.__class__.__name__}: {e.word} at line {e.line}, column {e.col}", file=sys.stderr)
            return 1
        except Exception as e:
             print(f"error: unexpected error: {e}", file=sys.stderr)
             return 1
    else:
        print("usage: python -m stack.interp [filename]", file=sys.stderr)
        return 1

if __name__ == "__main__":
    sys.exit(main())
