```python
"""Object model, serialization and parsing for the content-addressed store."""

from __future__ import annotations

import re
import hashlib
from dataclasses import dataclass
from typing import Any, NamedTuple

__all__ = [
    "Blob",
    "TreeEntry",
    "Tree",
    "Commit",
    "serialize",
    "object_id",
    "parse_object",
    "CorruptObject",
]


_OID_RE = re.compile(r"^[0-9a-f]{40}$")
_BAD_NAME_CHARS = frozenset({"/", "\0", "\t", "\n"})
_VALID_KINDS = frozenset({"blob", "tree"})


class CorruptObject(ValueError):
    """Raised when a serialisation cannot be decoded into a valid object."""


def _is_valid_oid(oid: Any) -> bool:
    return isinstance(oid, str) and _OID_RE.match(oid) is not None


def _is_valid_name(name: Any) -> bool:
    if not isinstance(name, str):
        return False
    if not name or name in (".", ".."):
        return False
    for ch in name:
        if ch in _BAD_NAME_CHARS:
            return False
    return True


def _require_valid_oid(oid: Any, what: str = "oid") -> None:
    if not _is_valid_oid(oid):
        raise ValueError(f"invalid {what}: {oid!r}")


def _require_valid_name(name: Any, what: str = "name") -> None:
    if not _is_valid_name(name):
        raise ValueError(f"invalid {what}: {name!r}")


def _require_valid_kind(kind: Any) -> None:
    if kind not in _VALID_KINDS:
        raise ValueError(f"invalid kind: {kind!r}")


@dataclass(frozen=True, eq=True)
class Blob:
    """A file's content."""

    data: bytes


class TreeEntry(NamedTuple):
    """A single entry in a tree."""

    name: str
    kind: str
    oid: str

    def __new__(cls, name: str, kind: str, oid: str) -> "TreeEntry":
        _require_valid_name(name)
        _require_valid_kind(kind)
        _require_valid_oid(oid)
        return super().__new__(cls, name, kind, oid)


@dataclass(frozen=True, eq=True)
class Tree:
    """A directory listing: sorted, unique-named entries."""

    entries: tuple[TreeEntry, ...]

    def __post_init__(self) -> None:
        entries = list(self.entries)
        seen: set[str] = set()
        for e in entries:
            # Constructing via the public constructor enforces validation.
            if not isinstance(e, TreeEntry):
                e = TreeEntry(e.name, e.kind, e.oid)  # type: ignore[attr-defined]
            if e.name in seen:
                raise ValueError(f"duplicate tree entry name: {e.name!r}")
            seen.add(e.name)
        entries.sort(key=lambda e: e.name.encode("utf-8"))
        object.__setattr__(self, "entries", tuple(entries))


@dataclass(frozen=True, eq=True)
class Commit:
    """A commit object."""

    tree: str
    parents: tuple[str, ...]
    author: str
    timestamp: int
    message: str

    def __post_init__(self) -> None:
        _require_valid_oid(self.tree, "tree oid")
        object.__setattr__(
            self, "parents", tuple(self.parents)
        )  # normalise any iterable to a tuple
        for p in self.parents:
            _require_valid_oid(p, "parent oid")
        if not isinstance(self.author, str) or "\n" in self.author:
            raise ValueError(f"invalid author: {self.author!r}")
        if not isinstance(self.timestamp, int) or isinstance(
            self.timestamp, bool
        ) or self.timestamp < 0:
            raise ValueError(f"invalid timestamp: {self.timestamp!r}")
        if not isinstance(self.message, str):
            raise ValueError(f"invalid message: {self.message!r}")


def serialize(obj: Blob | Tree | Commit) -> bytes:
    """Serialise an object as ``header\0body``."""
    if isinstance(obj, Blob):
        body = obj.data
        header = b"blob "
    elif isinstance(obj, Tree):
        body = b"".join(
            f"{e.kind} {e.oid}\t{e.name}\n".encode("utf-8") for e in obj.entries
        )
        header = b"tree "
    elif isinstance(obj, Commit):
        parts = [f"tree {obj.tree}\n"]
        parts.extend(f"parent {p}\n" for p in obj.parents)
        parts.append(f"author {obj.author}\n")
        parts.append(f"time {obj.timestamp}\n")
        parts.append("\n")
        parts.append(obj.message)
        body = "".join(parts).encode("utf-8")
        header = b"commit "
    else:  # pragma: no cover - defensive
        raise TypeError(f"cannot serialise {type(obj).__name__}")
    return header + str(len(body)).encode("ascii") + b"\0" + body


def object_id(obj: Blob | Tree | Commit) -> str:
    """Return the SHA-1 oid of an object."""
    return hashlib.sha1(serialize(obj)).hexdigest()


def _split_header(raw: bytes) -> tuple[bytes, bytes]:
    """Split ``raw`` into (header_without_zero, body) or raise CorruptObject."""
    nul = raw.find(b"\0")
    if nul < 0:
        raise CorruptObject("missing null terminator in header")
    header = raw[:nul]
    body = raw[nul + 1 :]
    return header, body


def _parse_header_type_length(header: bytes) -> tuple[bytes, int]:
    parts = header.split(b" ")
    if len(parts) != 2:
        raise CorruptObject("malformed header")
    typ, length_bytes = parts
    if typ not in (b"blob", b"tree", b"commit"):
        raise CorruptObject(f"unknown object type: {typ!r}")
    try:
        length = int(length_bytes.decode("ascii"))
    except (UnicodeDecodeError, ValueError):
        raise CorruptObject("malformed header length") from None
    if length < 0:
        raise CorruptObject("negative length")
    return typ, length


def _read_line(body: bytes, pos: int) -> tuple[bytes, int]:
    nl = body.find(b"\n", pos)
    if nl < 0:
        raise CorruptObject("unexpected end of object body")
    return body[pos:nl], nl + 1


def _parse_tree_body(body: bytes) -> Tree:
    entries: list[TreeEntry] = []
    pos = 0
    n = len(body)
    while pos < n:
        line, pos = _read_line(body, pos)
        tab = line.find(b"\t")
        if tab < 0:
            raise CorruptObject("tree entry missing tab separator")
        head = line[:tab]
        name_bytes = line[tab + 1 :]
        sp = head.find(b" ")
        if sp < 0:
            raise CorruptObject("tree entry missing kind/oid separator")
        kind_bytes = head[:sp]
        oid_bytes = head[sp + 1 :]
        try:
            kind = kind_bytes.decode("utf-8")
            oid = oid_bytes.decode("utf-8")
            name = name_bytes.decode("utf-8")
        except UnicodeDecodeError:
            raise CorruptObject("tree entry is not valid utf-8") from None
        try:
            entries.append(TreeEntry(name=name, kind=kind, oid=oid))
        except ValueError as exc:
            raise CorruptObject(str(exc)) from exc
    try:
        return Tree(entries)
    except ValueError as exc:
        raise CorruptObject(str(exc)) from exc


def _parse_commit_body(body: bytes) -> Commit:
    pos = 0

    # tree line
    line, pos = _read_line(body, pos)
    if not line.startswith(b"tree "):
        raise CorruptObject("commit body must start with a tree line")
    tree = line[5:].decode("utf-8", errors="strict")

    # parent lines
    parents: list[str] = []
    while True:
        nl = body.find(b"\n", pos)
        if nl < 0:
            raise CorruptObject("unexpected end of commit body")
        line = body[pos:nl]
        if not line.startswith(b"parent "):
            break
        pos = nl + 1
        parents.append(line[7:].decode("utf-8", errors="strict"))

    # author line
    line, pos = _read_line(body, pos)
    if not line.startswith(b"author "):
        raise CorruptObject("commit body missing author line")
    author = line[7:].decode("utf-8", errors="strict")

    # time line
    line, pos = _read_line(body, pos)
    if not line.startswith(b"time "):
        raise CorruptObject("commit body missing time line")
    timestamp_s = line[5:].decode("utf-8", errors="strict")
    try:
        timestamp = int(timestamp_s)
    except ValueError:
        raise CorruptObject("commit time is not an integer") from None

    # blank line
    line, pos = _read_line(body, pos)
    if line != b"":
        raise CorruptObject("commit body missing blank line")

    message = body[pos:].decode("utf-8", errors="strict")

    try:
        return Commit(
            tree=tree,
            parents=tuple(parents),
            author=author,
            timestamp=timestamp,
            message=message,
        )
    except UnicodeDecodeError as exc:
        raise CorruptObject(f"commit field is not valid utf-8: {exc}") from exc
    except ValueError as exc:
        raise CorruptObject(str(exc)) from exc


def parse_object(raw: bytes) -> Blob | Tree | Commit:
    """Decode a serialisation back into an object.

    Raises ``CorruptObject`` (a ``ValueError`` subclass) if the bytes do not
    describe a valid object.
    """
    if not isinstance(raw, bytes):
        raise CorruptObject("serialisation must be bytes")

    header, body = _split_header(raw)
    typ, length = _parse_header_type_length(header)
    if len(body) != length:
        raise CorruptObject(
            f"length mismatch: header says {length}, body has {len(body)}"
        )

    if typ == b"blob":
        return Blob(data=body)
    if typ == b"tree":
        return _parse_tree_body(body)
    if typ == b"commit":
        return _parse_commit_body(body)
    raise CorruptObject(f"unknown object type: {typ!r}")  # pragma: no cover
