"""Tree and commit diffing logic for the content-addressed store."""

from __future__ import annotations

from typing import Iterator, Optional, NamedTuple

from .objects import Tree, Commit
from .store import ObjectStore


class Change(NamedTuple):
    """A single change between two trees or commits."""

    status: str  # 'A', 'D', 'M'
    path: str
    old: Optional[str]
    new: Optional[str]


def _list_files(store: ObjectStore, oid: str, prefix: str) -> Iterator[tuple[str, str]]:
    """Yield (path, blob_oid) for all blobs under the tree with the given oid."""
    tree = store.get(oid)
    if not isinstance(tree, Tree):
        return

    for entry in tree.entries:
        full_path = f"{prefix}{entry.name}" if prefix else entry.name
        if entry.kind == "blob":
            yield (full_path, entry.oid)
        elif entry.kind == "tree":
            sub_prefix = f"{full_path}/"
            yield from _list_files(store, entry.oid, sub_prefix)


def _diff_trees(
    store: ObjectStore,
    old_oid: Optional[str],
    new_oid: Optional[str],
    prefix: str,
) -> Iterator[Change]:
    """Recursively diff two trees and yield Change objects."""
    # Fetch entries. If oid is None, it's an empty tree (no entries).
    old_entries: dict[str, TreeEntry] = {}  # type: ignore[assignment]
    new_entries: dict[str, TreeEntry] = {}  # type: ignore[assignment]

    if old_oid is not None:
        old_tree = store.get(old_oid)
        if not isinstance(old_tree, Tree):
            raise ValueError(f"not a tree: {old_oid}")
        old_entries = {e.name: e for e in old_tree.entries}

    if new_oid is not None:
        new_tree = store.get(new_oid)
        if not isinstance(new_tree, Tree):
            raise ValueError(f"not a tree: {new_oid}")
        new_entries = {e.name: e for e in new_tree.entries}

    # Get all names and sort them
    names = sorted(set(old_entries.keys()) | set(new_entries.keys()), key=lambda n: n.encode("utf-8"))

    for name in names:
        path = f"{prefix}{name}" if prefix else name

        old_entry = old_entries.get(name)
        new_entry = new_entries.get(name)

        if old_entry is not None and new_entry is not None:
            # Both exist
            if old_entry.kind == "blob" and new_entry.kind == "blob":
                if old_entry.oid != new_entry.oid:
                    yield Change(status="M", path=path, old=old_entry.oid, new=new_entry.oid)
            elif old_entry.kind == "tree" and new_entry.kind == "tree":
                if old_entry.oid != new_entry.oid:
                    yield from _diff_trees(store, old_entry.oid, new_entry.oid, f"{path}/")
            else:
                # Conflict: one is blob, one is tree
                if old_entry.kind == "blob":
                    # File deleted, dir added
                    yield Change(status="D", path=path, old=old_entry.oid, new=None)
                    # Add everything under the new tree
                    yield from _list_files_changes(store, new_entry.oid, f"{path}/", "A")
                else:
                    # Dir deleted, file added
                    # Delete everything under the old tree
                    yield from _list_files_changes(store, old_entry.oid, f"{path}/", "D")
                    yield Change(status="A", path=path, old=None, new=new_entry.oid)
        elif old_entry is not None:
            # Only in old: Deleted
            if old_entry.kind == "blob":
                yield Change(status="D", path=path, old=old_entry.oid, new=None)
            else:
                yield from _list_files_changes(store, old_entry.oid, f"{path}/", "D")
        else:
            # Only in new: Added
            if new_entry is not None:
                if new_entry.kind == "blob":
                    yield Change(status="A", path=path, old=None, new=new_entry.oid)
                else:
                    yield from _list_files_changes(store, new_entry.oid, f"{path}/", "A")


def _list_files_changes(store: ObjectStore, tree_oid: str, prefix: str, status: str) -> Iterator[Change]:
    """Yield Change objects for all files under a tree, marking them as added or deleted."""
    for path, blob_oid in _list_files(store, tree_oid, prefix):
        if status == "A":
            yield Change(status=status, path=path, old=None, new=blob_oid)
        else:
            yield Change(status=status, path=path, old=blob_oid, new=None)


def diff_trees(store: ObjectStore, old: Optional[str], new: Optional[str]) -> list[Change]:
    """Compare two trees and return a list of Changes.

    Args:
        store: The object store.
        old: The oid of the old tree, or None for an empty tree.
        new: The oid of the new tree, or None for an empty tree.

    Returns:
        A list of Change objects, sorted by path.
    """
    return list(_diff_trees(store, old, new, ""))


def diff_commits(store: ObjectStore, old: Optional[str], new: Optional[str]) -> list[Change]:
    """Compare the trees of two commits and return a list of Changes.

    Args:
        store: The object store.
        old: The oid of the old commit, or None.
        new: The oid of the new commit.

    Returns:
        A list of Change objects, sorted by path.
    """
    old_tree_oid = None
    if old is not None:
        old_commit = store.get(old)
        if not isinstance(old_commit, Commit):
            raise ValueError(f"not a commit: {old}")
        old_tree_oid = old_commit.tree

    new_commit = store.get(new)
    if not isinstance(new_commit, Commit):
        raise ValueError(f"not a commit: {new}")
    new_tree_oid = new_commit.tree

    return diff_trees(store, old_tree_oid, new_tree_oid)


def format_changes(changes: list[Change]) -> str:
    """Format a list of Changes as a string.

    Args:
        changes: A list of Change objects.

    Returns:
        A string with one line per change: ``status\\tpath\\n``.
    """
    return "".join(f"{c.status}\t{c.path}\n" for c in changes)
