"""In-memory content-addressed object store with tree/commit helpers."""

from __future__ import annotations

import re
import heapq
from typing import Any, Optional

from objstore.objects import (
    Blob,
    Tree,
    TreeEntry,
    Commit,
    serialize,
    object_id,
    parse_object,
    CorruptObject,
)

__all__ = [
    "ObjectNotFound",
    "AmbiguousPrefix",
    "ObjectStore",
]

_HEX_RE = re.compile(r"^[0-9a-f]{4,40}$")


class ObjectNotFound(KeyError):
    """Raised when an object is not found in the store."""


class AmbiguousPrefix(ValueError):
    """Raised when a prefix matches more than one object."""


class ObjectStore:
    """In-memory content-addressed object store."""

    def __init__(self) -> None:
        self._objects: dict[str, bytes] = {}

    def put(self, obj: Blob | Tree | Commit) -> str:
        """Store an object and return its oid."""
        oid = object_id(obj)
        raw = serialize(obj)
        self._objects[oid] = raw
        return oid

    def put_raw(self, raw: bytes) -> str:
        """Store a serialisation after validating it, returning its oid."""
        obj = parse_object(raw)
        oid = object_id(obj)
        # Verify consistency: re-serialising should yield the same bytes
        if serialize(obj) != raw:
            raise ValueError("serialisation does not round-trip")
        self._objects[oid] = raw
        return oid

    def get(self, oid: str) -> Blob | Tree | Commit:
        """Return the object for an oid."""
        if oid not in self._objects:
            raise ObjectNotFound(oid)
        return parse_object(self._objects[oid])

    def get_raw(self, oid: str) -> bytes:
        """Return the serialisation for an oid."""
        if oid not in self._objects:
            raise ObjectNotFound(oid)
        return self._objects[oid]

    def __contains__(self, oid: str) -> bool:
        return oid in self._objects

    def resolve(self, prefix: str) -> str:
        """Resolve a short hex prefix to a full oid."""
        if not isinstance(prefix, str) or not _HEX_RE.match(prefix):
            raise ValueError(
                "prefix must be 4 to 40 lowercase hex characters"
            )

        matches = [oid for oid in self._objects if oid.startswith(prefix)]
        if not matches:
            raise ObjectNotFound(prefix)
        if len(matches) > 1:
            raise AmbiguousPrefix(prefix)
        return matches[0]

    def write_tree(self, files: dict[str, bytes]) -> str:
        """Create blobs and trees from a flat path->content dict.

        Returns the oid of the root tree.
        Raises ValueError on invalid paths or conflicting file/directory names.
        """
        # Build a nested dict representing the directory structure
        # Leaves are bytes (file content), internal nodes are dicts
        tree_struct: dict[str, Any] = {}

        for path, content in files.items():
            if not path:
                raise ValueError("empty path")
            if path.startswith("/") or path.endswith("/"):
                raise ValueError("leading or trailing slash")

            parts = path.split("/")
            # Check for empty parts or invalid names
            for part in parts:
                if not part:
                    raise ValueError("empty path component")
                if part in (".", "..") or "/" in part or "\0" in part or "\t" in part or "\n" in part:
                    raise ValueError(f"invalid path component: {part!r}")

            current = tree_struct
            for i, part in enumerate(parts):
                is_leaf = (i == len(parts) - 1)

                if is_leaf:
                    if part in current:
                        if isinstance(current[part], dict):
                            raise ValueError(f"conflict: {part} is a directory, cannot be file in {path}")
                    current[part] = content
                else:
                    if part not in current:
                        current[part] = {}
                    elif not isinstance(current[part], dict):
                        raise ValueError(f"conflict: {part} is a file, cannot be directory in {path}")
                    current = current[part]

        # Recursively build trees from bottom up
        def build_tree(subtree: dict[str, Any]) -> str:
            entries: list[TreeEntry] = []
            for name, val in subtree.items():
                if isinstance(val, dict):
                    # It's a directory
                    child_oid = build_tree(val)
                    entries.append(TreeEntry(name=name, kind="tree", oid=child_oid))
                else:
                    # It's a file (bytes)
                    blob = Blob(data=val)
                    blob_oid = self.put(blob)
                    entries.append(TreeEntry(name=name, kind="blob", oid=blob_oid))

            tree = Tree(entries)
            return self.put(tree)

        return build_tree(tree_struct)

    def read_tree(self, oid: str) -> dict[str, bytes]:
        """Flatten a tree into a dict of path -> content."""
        result: dict[str, bytes] = {}

        def walk(oid: str, prefix: str) -> None:
            obj = self.get(oid)
            if not isinstance(obj, Tree):
                raise ValueError("read_tree expects a tree oid")

            for entry in obj.entries:
                full_path = f"{prefix}/{entry.name}" if prefix else entry.name
                if entry.kind == "blob":
                    blob = self.get(entry.oid)
                    if not isinstance(blob, Blob):
                        raise ValueError("tree entry points to non-blob")
                    result[full_path] = blob.data
                elif entry.kind == "tree":
                    walk(entry.oid, full_path)
                else:
                    raise ValueError(f"unknown kind in tree: {entry.kind}")

        walk(oid, "")
        return dict(sorted(result.items()))

    def commit(
        self,
        tree: str,
        parents: tuple[str, ...] = (),
        *,
        author: str,
        timestamp: int,
        message: str,
    ) -> str:
        """Store a commit, validating that the tree and parents exist and have correct types."""
        # Validate tree
        if tree not in self._objects:
            raise ObjectNotFound(tree)
        tree_obj = self.get(tree)
        if not isinstance(tree_obj, Tree):
            raise ValueError("tree oid is not a tree")

        # Validate parents
        for p in parents:
            if p not in self._objects:
                raise ObjectNotFound(p)
            p_obj = self.get(p)
            if not isinstance(p_obj, Commit):
                raise ValueError("parent oid is not a commit")

        c = Commit(
            tree=tree,
            parents=parents,
            author=author,
            timestamp=timestamp,
            message=message,
        )
        return self.put(c)

    def log(
        self,
        oid: str,
        first_parent: bool = False,
    ) -> list[str]:
        """Return commit oids in history.

        If first_parent is True, follow the first parent only.
        Otherwise, return all ancestors, newest first (timestamp desc, oid asc).
        """
        if first_parent:
            result: list[str] = []
            current: Optional[str] = oid
            while current is not None:
                if current not in self._objects:
                    raise ObjectNotFound(current)
                obj = self.get(current)
                if not isinstance(obj, Commit):
                    raise ValueError("log requires commit oids")
                result.append(current)
                if not obj.parents:
                    break
                current = obj.parents[0]
            return result

        # General history: collect all reachable commits, then sort
        visited: set[str] = set()
        queue: list[str] = [oid]
        commits: list[tuple[int, str]] = []  # (-timestamp, oid) for heap or sort key

        # Use BFS/DFS to collect
        stack = [oid]
        while stack:
            curr = stack.pop()
            if curr in visited:
                continue
            visited.add(curr)

            if curr not in self._objects:
                raise ObjectNotFound(curr)
            obj = self.get(curr)
            if not isinstance(obj, Commit):
                raise ValueError("log requires commit oids")

            commits.append((obj.timestamp, curr))
            for p in obj.parents:
                if p not in visited:
                    stack.append(p)

        # Sort: newest first (descending timestamp), then ascending oid for ties
        # Python sort is stable, we can sort by (-timestamp, oid)
        commits.sort(key=lambda x: (-x[0], x[1]))
        return [oid for _, oid in commits]
