    payments_data = data.get("payments", [])
    if payments_data:
        if not isinstance(payments_data, list):
            raise ValueError("Payments must be a list")
        for pay_data in payments_data:
            if not isinstance(pay_data, dict):
                raise ValueError("Payment entry must be a dict")

            payer = pay_data.get("from")
            payee = pay_data.get("to")
            amount_str = pay_data.get("amount")

            if not payer or not isinstance(payer, str):
                raise ValueError("Payment missing 'from'")
            if not payee or not isinstance(payee, str):
                raise ValueError("Payment missing 'to'")
            if not amount_str or not isinstance(amount_str, str):
                raise ValueError("Payment missing amount or amount not a string")

            amount_cents = parse_amount(amount_str)

            group.add_payment(payer, payee, amount_cents)

    return group
