            raise ValueError("Expense must be an Expense instance")

        # Check payer
        if expense.paid_by not in self._members:
            raise ValueError(f"Payer {expense.paid_by!r} is not a member")

        split = expense.split
        participants = []
        shares = {}

        if isinstance(split, Equal):
            if split.members is not None:
                # Validate members in Equal
                for m in split.members:
                    if m not in self._members:
                        raise ValueError(f"Participant {m!r} in Equal split is not a member")
                participants = list(split.members)
            else:
                participants = list(self._members)

            if not participants:
                raise ValueError("Equal split has no participants")

            n = len(participants)
            base = expense.amount // n
            remainder = expense.amount % n

            # Sort participants alphabetically to distribute remainder
            sorted_participants = sorted(participants)

            for i, m in enumerate(sorted_participants):
                if i < remainder:
                    shares[m] = base + 1
                else:
                    shares[m] = base

        elif isinstance(split, Exact):
            for m, amount in split.shares.items():
                if m not in self._members:
                    raise ValueError(f"Participant {m!r} in Exact split is not a member")
                shares[m] = amount
                participants.append(m)

            total_share = sum(split.shares.values())
            if total_share != expense.amount:
                raise ValueError(f"Exact shares sum to {total_share}, but expense amount is {expense.amount}")

        elif isinstance(split, Percent):
            for m, pct in split.shares.items():
                if m not in self._members:
                    raise ValueError(f"Participant {m!r} in Percent split is not a member")
                participants.append(m)

            # Calculate shares
            # Compute floor of amount * percentage / 100
            # And track fractional parts for largest remainder method

            calculated = {}
            fractional_parts = {}

            # We need to ensure percentages are handled as Decimal for precision
            temp_shares = {}
            for m, pct in split.shares.items():
                if isinstance(pct, str):
                    p_dec = Decimal(pct)
                elif isinstance(pct, int):
                    p_dec = Decimal(pct)
                elif isinstance(pct, Decimal):
                    p_dec = pct
                else:
                    raise ValueError(f"Invalid percentage type for {m}: {type(pct)}")

                if p_dec < 0:
                    raise ValueError(f"Percentage for {m} cannot be negative")

                temp_shares[m] = p_dec

            # Check if percentages sum to exactly 100
            total_pct = sum(temp_shares.values())
            if total_pct != 100:
                raise ValueError(f"Percentages sum to {total_pct}, must be exactly 100")

            amount_dec = Decimal(expense.amount)
            cents_per_percent = amount_dec / Decimal(100)

            for m in participants:
                pct_val = temp_shares[m]
                # exact value of share in cents
                exact_cents = pct_val * cents_per_percent

                # Floor
                floor_cents = int(exact_cents.to_integral_value(rounding=decimal.ROUND_FLOOR))
                if floor_cents < 0:
                     # Should be non-negative if inputs are valid
                    raise ValueError("Calculated negative share")

                shares[m] = floor_cents

                # Fractional part for remainder distribution
                frac = exact_cents - Decimal(floor_cents)
                fractional_parts[m] = frac

            distributed = sum(shares.values())
            missing = expense.amount - distributed

            if missing > 0:
                # Sort by fractional part descending, then alphabetically for ties
                # We need to pick 'missing' people to give 1 extra cent
                # Sort key: (-fractional_part, name)
                candidates = sorted(participants, key=lambda m: (-fractional_parts[m], m))
                for i in range(missing):
                    m = candidates[i]
                    shares[m] += 1

        else:
            raise ValueError(f"Unknown split type: {type(split)}")

        # Ensure result dict has keys in group order?
        # Spec: "returns the shares: a dict from member to cents, with one key per participant, in the group's member order"

        # Create ordered dict based on self._members
        result_shares = {}
        for m in self._members:
            if m in shares:
                result_shares[m] = shares[m]

        # Validate that all participants in result_shares sum to amount
        if sum(result_shares.values()) != expense.amount:
            raise ValueError("Internal error: shares do not sum to amount")

        self._expenses.append((expense, result_shares))
        return result_shares

    def add_payment(self, payer: str, payee: str, amount: int):
        if payer not in self._members:
            raise ValueError(f"Payer {payer!r} is not a member")
        if payee not in self._members:
            raise ValueError(f"Payee {payee!r} is not a member")
        if payer == payee:
            raise ValueError("Payer and payee must be different people")
        if not isinstance(amount, int):
            raise ValueError("Payment amount must be an int")
        if amount <= 0:
            raise ValueError("Payment amount must be greater than 0")

        self._payments.append((payer, payee, amount))


def load_group(data: dict) -> Group:
    if not isinstance(data, dict):
        raise ValueError("Data must be a dictionary")

    members = data.get("members")
    if not members or not isinstance(members, list):
        raise ValueError("Members must be a non-empty list")

    group = Group(members)

    expenses_data = data.get("expenses", [])
    if expenses_data:
        if not isinstance(expenses_data, list):
            raise ValueError("Expenses must be a list")
        for exp_data in expenses_data:
            if not isinstance(exp_data, dict):
                raise ValueError("Expense entry must be a dict")

            desc = exp_data.get("description")
            paid_by = exp_data.get("paid_by")
            amount_str = exp_data.get("amount")
            split_data = exp_data.get("split")

            if not desc or not isinstance(desc, str):
                raise ValueError("Expense missing description")
            if not paid_by or not isinstance(paid_by, str):
                raise ValueError("Expense missing paid_by")
            if not amount_str or not isinstance(amount_str, str):
                raise ValueError("Expense missing amount or amount not a string")
            if not split_data or not isinstance(split_data, dict):
                raise ValueError("Expense missing split")

            amount_cents = parse_amount(amount_str)

            split_type = split_data.get("type")
            if split_type == "equal":
                # members in split_data is optional
                split_members = split_data.get("members")
                if split_members is not None:
                    if not isinstance(split_members, list):
                        raise ValueError("Equal split members must be a list")
                split_obj = Equal(members=split_members)

            elif split_type == "exact":
                shares_raw = split_data.get("shares")
                if not isinstance(shares_raw, dict):
                    raise ValueError("Exact split shares must be a dict")

                shares_int = {}
                for name, val in shares_raw.items():
                    if not isinstance(val, str):
                        # The example shows string amounts for exact shares too
                        # But the spec says "a dict from member to cents" for Exact class.
                        # However load_group description says "Amounts are strings parsed with parse_amount"
                        # So we parse here.
                        pass
                    if not isinstance(val, str):
                        raise ValueError(f"Exact share amount for {name} must be a string")
                    shares_int[name] = parse_amount(val)

                split_obj = Exact(shares=shares_int)

            elif split_type == "percent":
                shares_raw = split_data.get("shares")
                if not isinstance(shares_raw, dict):
                    raise ValueError("Percent split shares must be a dict")

                # Percent shares are passed as-is to Percent class, which handles validation
                # But Percent expects dict from member to percentage (int, Decimal, or string)
                # The example uses strings.
                split_obj = Percent(shares=shares_raw)
            else:
                raise ValueError(f"Unknown split type: {split_type}")

            expense = Expense(
                description=desc,
                paid_by=paid_by,
                amount=amount_cents,
                split=split_obj
            )
            group.add_expense(expense)

    payments_data = data.get("payments", [])
    if payments_data:
        if not isinstance(payments_data, list):
            raise ValueError("Payments must be a list")
        for pay_data in payments_data:
            if not isinstance(pay_data, dict):
                raise ValueError("Payment entry must be a dict")

            payer = pay_data.get("from")
            payee = pay_data.get("to")
            amount_str = pay_data.get("amount")

            if not payer or not isinstance(payer, str):
                raise ValueError("Payment missing 'from'")
            if not payee or not isinstance(payee, str):
                raise ValueError("Payment missing 'to'")
            if not amount_str or not isinstance(amount_str, str):
                raise ValueError("Payment missing amount or amount not a string")

            amount_cents = parse_amount(amount_str)

            group.add_payment(payer, payee, amount_cents)

    return group
