"""Calculate balances and format them for display."""

from __future__ import annotations

from typing import Dict


def balances(group) -> Dict[str, int]:
    """Return a dict mapping each member's name to their net balance in cents.

    Positive means the group owes them money; negative means they owe the group.
    The balances add up to 0.
    """
    # Initialize every member with zero
    bals: Dict[str, int] = {name: 0 for name in group.members}

    # Add expenses: payer gets paid, everyone's share is subtracted
    for expense, shares in group.expenses:
        # Payer paid the full amount
        bals[expense.paid_by] += expense.amount
        # Each participant owes their share
        for member, share in shares.items():
            bals[member] -= share

    # Add direct payments
    for payer, payee, amount in group.payments:
        bals[payer] -= amount
        bals[payee] += amount

    # Return in alphabetical order
    return {name: bals[name] for name in sorted(bals.keys())}


def format_amount(cents: int) -> str:
    """Format cents as a decimal string with two decimal places and sign for positives."""
    if cents < 0:
        return f"-{abs(cents) // 100}.{abs(cents) % 100:02d}"
    elif cents == 0:
        return "0.00"
    else:
        return f"{cents // 100}.{cents % 100:02d}"


def format_balances(bals: Dict[str, int]) -> str:
    """Return one line per member in alphabetical order, e.g. 'name: +12.50\n'."""
    lines = []
    for name in sorted(bals.keys()):
        amount = bals[name]
        if amount > 0:
            formatted = f"+{format_amount(amount)}"
        elif amount < 0:
            formatted = f"-{format_amount(-amount)}"
        else:
            formatted = "0.00"
        lines.append(f"{name}: {formatted}\n")
    return "".join(lines)
